import json
with open('/workspace/contracts/openapi.contract.json') as f:
    spec = json.load(f)
paths = list(spec['paths'].items())
for path, methods in paths[25:39]:
    print(f'*** {path} ***')
    for m, op in methods.items():
        print(f'Method: {m.upper()}, opId: {op.get(\"operationId\")}, sec: {op.get(\"security\")}')
        if op.get('parameters'):
            print('  Params:', json.dumps(op['parameters']))
        if op.get('requestBody'):
            print('  ReqBody:', json.dumps(op['requestBody']['content']['application/json']['schema']))
        for code, resp in op.get('responses', {}).items():
            content = resp.get('content', {})
            for ctype, cval in content.items():
                print(f'  Resp {code} ({ctype}):', json.dumps(cval['schema']))
"

