package internal

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
	"github.com/jackc/pgx/v5/pgxpool"
)

const (
	OfferExpiryDuration  = 15 * time.Minute
	StaleLocationMinutes = 15 * time.Minute
	DefaultNodeCapacity  = 50
	DefaultConnCapacity  = 50
	DefaultWorkerCap     = 10
)

type PersistentSnapshot struct {
	Users                    map[string]*User              `json:"users"`
	Sessions                 map[string]*Session           `json:"sessions"`
	SampleTypes              map[string]*SampleType        `json:"sampleTypes"`
	Locations                map[string]*Location          `json:"locations"`
	Connections              map[string]*Connection        `json:"connections"`
	LabAcceptances           map[string]map[string]string  `json:"labAcceptances"` // labId -> sampleTypeId -> acceptanceId
	Samples                  map[string]*Sample            `json:"samples"`
	Journeys                 map[string]*JourneyPlan       `json:"journeys"`
	Assignments              map[string]*Assignment        `json:"assignments"`
	Handoffs                 map[string]*Handoff           `json:"handoffs"`
	Idempotency              map[string]*IdempotencyRecord `json:"idempotency"`
	AuditEntries             []AuditEntry                  `json:"auditEntries"`
	RealtimeEvents           []RealtimeEvent               `json:"realtimeEvents"`
	ServiceabilitySnapshot   ServiceabilitySnapshot        `json:"serviceabilitySnapshot"`
	NextEventID              int                           `json:"nextEventId"`
	NextAuditSeq             int                           `json:"nextAuditSeq"`
	NextRealtimeID           int64                         `json:"nextRealtimeId"`
	NextOfferSeq             int64                         `json:"nextOfferSeq"`
	NetworkRevision          int                           `json:"networkRevision"`
	ServiceabilityVersionSeq int                           `json:"serviceabilityVersionSeq"`
}

type Store struct {
	mu    sync.RWMutex
	pool  *pgxpool.Pool
	state PersistentSnapshot

	wsMu      sync.Mutex
	wsClients map[*websocket.Conn]bool
}

func NewUUID() string {
	b := make([]byte, 16)
	_, _ = rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func HashPassword(pw string) string {
	sum := sha256.Sum256([]byte("arena-salt:" + pw))
	return hex.EncodeToString(sum[:])
}

func HashPayload(b []byte) string {
	var v any
	if err := json.Unmarshal(b, &v); err == nil {
		if norm, err := json.Marshal(v); err == nil {
			b = norm
		}
	}
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

func HaversineKm(a, b Coordinate) float64 {
	const R = 6371.0
	lat1 := a.Latitude * math.Pi / 180.0
	lat2 := b.Latitude * math.Pi / 180.0
	dLat := (b.Latitude - a.Latitude) * math.Pi / 180.0
	dLon := (b.Longitude - a.Longitude) * math.Pi / 180.0
	sinLat := math.Sin(dLat / 2)
	sinLon := math.Sin(dLon / 2)
	h := sinLat*sinLat + math.Cos(lat1)*math.Cos(lat2)*sinLon*sinLon
	return 2 * R * math.Atan2(math.Sqrt(h), math.Sqrt(1-h))
}

const schemaSQL = `
CREATE TABLE IF NOT EXISTS app_state (
	id INTEGER PRIMARY KEY CHECK (id = 1),
	payload JSONB NOT NULL,
	updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS users (
	user_id UUID PRIMARY KEY,
	username TEXT UNIQUE NOT NULL,
	active BOOLEAN NOT NULL DEFAULT TRUE,
	roles JSONB NOT NULL DEFAULT '[]'::jsonb,
	data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_users_username ON users (username);

CREATE TABLE IF NOT EXISTS sessions (
	token TEXT PRIMARY KEY,
	user_id UUID NOT NULL,
	active_role TEXT NOT NULL,
	created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions (user_id);

CREATE TABLE IF NOT EXISTS sample_types (
	sample_type_id UUID PRIMARY KEY,
	name TEXT NOT NULL,
	data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sample_types_name ON sample_types (name);

CREATE TABLE IF NOT EXISTS locations (
	location_id UUID PRIMARY KEY,
	name TEXT NOT NULL,
	active BOOLEAN NOT NULL DEFAULT TRUE,
	data JSONB NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_locations_active ON locations (active);

CREATE TABLE IF NOT EXISTS connections (
	connection_id UUID PRIMARY KEY,
	from_location_id UUID NOT NULL,
	to_location_id UUID NOT NULL,
