func (s *Store) load(ctx context.Context) error {
	var raw []byte
	err := s.pool.QueryRow(ctx, `SELECT payload FROM app_state WHERE id = 1`).Scan(&raw)
	if err != nil {
		// Initialize empty state in DB
		s.state = NewEmptySnapshot()
		return s.saveLocked(ctx)
	}
	var snap PersistentSnapshot
	if err := json.Unmarshal(raw, &snap); err != nil {
		return err
	}
	if snap.Users == nil {
		snap.Users = make(map[string]*User)
	}
	for _, u := range snap.Users {
		if u.LastLocationSeq == nil {
			u.LastLocationSeq = make(map[string]int)
		}
		if u.Roles == nil {
			u.Roles = []string{}
