		if u.Qualifications == nil {
			u.Qualifications = []string{}
		}
		if u.Certifications == nil {
			u.Certifications = []Certification{}
		}
	}
	if snap.Sessions == nil {
		snap.Sessions = make(map[string]*Session)
	}
	if snap.SampleTypes == nil {
		snap.SampleTypes = make(map[string]*SampleType)
	}
	seedDefaultSampleTypes(&snap)
	if snap.Locations == nil {
		snap.Locations = make(map[string]*Location)
	}
	if snap.Connections == nil {
		snap.Connections = make(map[string]*Connection)
	}
	if snap.LabAcceptances == nil {
		snap.LabAcceptances = make(map[string]map[string]string)
	}
	if snap.Samples == nil {
		snap.Samples = make(map[string]*Sample)
	}
	if snap.Journeys == nil {
		snap.Journeys = make(map[string]*JourneyPlan)
	}
	for _, j := range snap.Journeys {
		if j.ReservedResources == nil {
			j.ReservedResources = make(map[string]bool)
		}
	}
	if snap.Assignments == nil {
		snap.Assignments = make(map[string]*Assignment)
	}
	for _, a := range snap.Assignments {
		if a.DeclinedByWorkerIDs == nil {
			a.DeclinedByWorkerIDs = make(map[string]bool)
		}
	}
	if snap.Handoffs == nil {
		snap.Handoffs = make(map[string]*Handoff)
	}
	if snap.Idempotency == nil {
		snap.Idempotency = make(map[string]*IdempotencyRecord)
	}
	if snap.AuditEntries == nil {
		snap.AuditEntries = []AuditEntry{}
	}
	if snap.RealtimeEvents == nil {
		snap.RealtimeEvents = []RealtimeEvent{}
	}
	if snap.ServiceabilitySnapshot.Regions == nil {
		snap.ServiceabilitySnapshot.Regions = []ServiceabilityRegion{}
	}
	if snap.ServiceabilitySnapshot.Version < 1 {
		snap.ServiceabilitySnapshot.Version = 1
		snap.ServiceabilitySnapshot.Status = "complete"
		snap.ServiceabilitySnapshot.ComputedAt = time.Now().UTC().Format(time.RFC3339)
	}
	if snap.NextEventID < 1 {
		snap.NextEventID = 1
	}
	if snap.NextAuditSeq < 1 {
		snap.NextAuditSeq = 1
	}
	if snap.NextRealtimeID < 1 {
		snap.NextRealtimeID = 1
	}
	if snap.NextOfferSeq < 1 {
		snap.NextOfferSeq = 1
	}
	s.state = snap
	return nil
}

func (s *Store) saveLocked(ctx context.Context) error {
	raw, err := json.Marshal(s.state)
	if err != nil {
		return err
	}
	_, err = s.pool.Exec(ctx, `
		INSERT INTO app_state (id, payload, updated_at)
		VALUES (1, $1, NOW())
		ON CONFLICT (id) DO UPDATE SET payload = EXCLUDED.payload, updated_at = NOW()
	`, raw)
	return err
}

func (s *Store) ensureInitialAdmin(ctx context.Context) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.state.Users) > 0 {
		return
	}
	adminUser := strings.TrimSpace(os.Getenv("ADMIN_USERNAME"))
	adminPass := os.Getenv("ADMIN_PASSWORD")
	if adminUser == "" {
		adminUser = "admin"
	}
	if adminPass == "" {
		adminPass = "admin123"
	}
	uid := NewUUID()
	s.state.Users[uid] = &User{
		UserID:          uid,
		Username:        adminUser,
		PasswordHash:    HashPassword(adminPass),
		FullName:        "System Administrator",
		Roles:           []string{"administrator"},
		Qualifications:  []string{},
		Certifications:  []Certification{},
		Active:          true,
		Available:       true,
		CapacityUnits:   DefaultWorkerCap,
		LastLocationSeq: make(map[string]int),
	}
	_ = s.saveLocked(ctx)
}

func (s *Store) recordAuditLocked(actorID, role, action, entityType, entityID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	if actorID == "" {
		actorID = "anonymous"
	}
	if role == "" {
		role = "unselected"
	}
	if entityType == "" {
		entityType = "system"
	}
	if entityID == "" {
		entityID = "global"
	}
	now := time.Now().UTC().Format(time.RFC3339Nano)
	auditID := fmt.Sprintf("aud-%06d-%s", s.state.NextAuditSeq, NewUUID()[:8])
	s.state.NextAuditSeq++
	entry := AuditEntry{
		AuditID:      auditID,
		AuditIDSnake: auditID,
		ActorID:      actorID,
		ActorIDSnake: actorID,
		Role:         role,
		ActorRole:    role,
		Action:       action,
		EntityType:   entityType,
		EntitySnake:  entityType,
		EntityID:     entityID,
		EntityIDSnk:  entityID,
		Success:      success,
		OccurredAt:   now,
		OccurredSnk:  now,
		Details:      details,
	}
	s.state.AuditEntries = append(s.state.AuditEntries, entry)
}

func (s *Store) newTimelineEntryLocked(actorID, role, action, entityType, entityID string, success bool, occurredAt string, details map[string]any) TimelineEntry {
	if details == nil {
		details = map[string]any{}
	}
	if occurredAt == "" {
		occurredAt = time.Now().UTC().Format(time.RFC3339)
	}
	evID := s.state.NextEventID
	s.state.NextEventID++
	return TimelineEntry{
		EventID:    evID,
		Action:     action,
		ActorID:    actorID,
		Role:       role,
		EntityType: entityType,
		EntityID:   entityID,
		Success:    success,
		OccurredAt: occurredAt,
		Details:    details,
	}
}

func (s *Store) publishRealtimeLocked(eventType, entityType, entityID string, payload map[string]any) RealtimeEvent {
	if payload == nil {
		payload = map[string]any{}
	}
	id := s.state.NextRealtimeID
	s.state.NextRealtimeID++
	ev := RealtimeEvent{
		ID:         id,
		Type:       eventType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  time.Now().UTC().Format(time.RFC3339),
	}
	s.state.RealtimeEvents = append(s.state.RealtimeEvents, ev)
	go s.broadcastWS(ev)
	return ev
}

func (s *Store) RegisterWS(conn *websocket.Conn) {
	s.wsMu.Lock()
	s.wsClients[conn] = true
	s.wsMu.Unlock()
}

func (s *Store) UnregisterWS(conn *websocket.Conn) {
	s.wsMu.Lock()
	delete(s.wsClients, conn)
	s.wsMu.Unlock()
	_ = conn.Close()
}

func (s *Store) broadcastWS(ev RealtimeEvent) {
	s.wsMu.Lock()
	clients := make([]*websocket.Conn, 0, len(s.wsClients))
	for c := range s.wsClients {
		clients = append(clients, c)
	}
	s.wsMu.Unlock()
	msg, err := json.Marshal(ev)
	if err != nil {
		return
	}
	for _, c := range clients {
		_ = c.SetWriteDeadline(time.Now().Add(2 * time.Second))
		if err := c.WriteMessage(websocket.TextMessage, msg); err != nil {
			s.UnregisterWS(c)
		}
	}
}
