package internal

import (
	"sort"
	"strings"
	"time"
)

type routeCandidate struct {
	nodeIDs       []string
	connIDs       []string
	totalMinutes  int
	totalCost     float64
	arrivalAt     time.Time
	minAvailUnits int
}

func (s *Store) getLocationCapacityLocked(loc *Location) Capacity {
	capUnits := loc.Capacity.CapacityUnits
	cooledUnits := loc.Capacity.CooledCapacityUnits
	if !loc.CapacityConfigured {
		capUnits = DefaultNodeCapacity
		cooledUnits = DefaultNodeCapacity
	}
	avail := capUnits - loc.Capacity.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledUnits - loc.Capacity.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return Capacity{
		CapacityUnits:        capUnits,
		ReservedUnits:        loc.Capacity.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  cooledUnits,
		CooledReservedUnits:  loc.Capacity.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func (s *Store) getConnectionCapacityLocked(conn *Connection) Capacity {
	capUnits := conn.Capacity.CapacityUnits
	cooledUnits := conn.Capacity.CooledCapacityUnits
	if !conn.CapacityConfigured {
		capUnits = DefaultConnCapacity
		if conn.Cooled {
			cooledUnits = DefaultConnCapacity
		} else {
			cooledUnits = 0
		}
	}
	avail := capUnits - conn.Capacity.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledUnits - conn.Capacity.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return Capacity{
		CapacityUnits:        capUnits,
		ReservedUnits:        conn.Capacity.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  cooledUnits,
		CooledReservedUnits:  conn.Capacity.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func (s *Store) recomputeServiceabilityLocked(bumpRevision bool) {
	if bumpRevision {
		s.state.NetworkRevision++
		s.state.ServiceabilityVersionSeq++
	}
	if s.state.ServiceabilityVersionSeq < 1 {
		s.state.ServiceabilityVersionSeq = 1
	}
	regions := []ServiceabilityRegion{}
	locIDs := make([]string, 0, len(s.state.Locations))
	for id := range s.state.Locations {
		locIDs = append(locIDs, id)
	}
	sort.Strings(locIDs)
	for _, id := range locIDs {
		loc := s.state.Locations[id]
		if loc.Active && loc.Functions.CollectionPoint {
			regions = append(regions, ServiceabilityRegion{
				LocationID: loc.LocationID,
				Name:       loc.Name,
				Latitude:   loc.Coordinate.Latitude,
				Longitude:  loc.Coordinate.Longitude,
				CoverageKm: loc.CoverageKm,
			})
		}
	}
	s.state.ServiceabilitySnapshot = ServiceabilitySnapshot{
		Version:                    s.state.ServiceabilityVersionSeq,
		Status:                     "complete",
		ComputedAt:                 time.Now().UTC().Format(time.RFC3339),
		NetworkRevision:            s.state.NetworkRevision,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}
}

func (s *Store) labAcceptsSampleTypeLocked(labID, sampleTypeID string) bool {
	m, ok := s.state.LabAcceptances[labID]
	if !ok {
		return false
	}
	accID, ok := m[sampleTypeID]
	return ok && accID != ""
}

func (s *Store) sampleNeedsCooledLocked(st *SampleType) bool {
	if st == nil {
		return false
	}
	return st.RequiresCooledRoute || strings.EqualFold(st.Name, "Frost")
}

func (s *Store) sampleDisallowsBatchingLocked(st *SampleType) bool {
	if st == nil {
		return false
	}
	return !st.BatchingAllowed || strings.EqualFold(st.Name, "Pulse")
}

func (s *Store) samplesCompatibleLocked(a, b *Sample) bool {
	stA := s.state.SampleTypes[a.SampleTypeID]
	stB := s.state.SampleTypes[b.SampleTypeID]
	if stA == nil || stB == nil {
		return false
	}
	if (strings.EqualFold(stA.Name, "Amber") && strings.EqualFold(stB.Name, "Indigo")) ||
		(strings.EqualFold(stA.Name, "Indigo") && strings.EqualFold(stB.Name, "Amber")) {
		return false
	}
	for _, inc := range stA.IncompatibleSampleTypes {
		if inc == stB.SampleTypeID {
			return false
		}
	}
	for _, inc := range stB.IncompatibleSampleTypes {
		if inc == stA.SampleTypeID {
			return false
		}
	}
	for _, inc := range a.IncompatibleSampleTypes {
		if inc == b.SampleTypeID {
			return false
		}
	}
	for _, inc := range b.IncompatibleSampleTypes {
		if inc == a.SampleTypeID {
			return false
		}
	}
	// Check overlapping temperature range
	minT := a.TemperatureMinC
	if b.TemperatureMinC > minT {
		minT = b.TemperatureMinC
	}
	maxT := a.TemperatureMaxC
	if b.TemperatureMaxC < maxT {
		maxT = b.TemperatureMaxC
	}
	if minT > maxT {
		return false
	}
	return true
}

func (s *Store) evaluateServiceabilityLocked(
	origin Coordinate,
	originType string,
	originNodeID string,
	st *SampleType,
	startAt time.Time,
	deadline time.Time,
	units int,
	fixedStartNodeID string,
) (bool, string, *routeCandidate) {
	if units < 1 {
		units = 1
	}

	// 1. Find candidate start nodes
	startNodes := []*Location{}
	if fixedStartNodeID != "" {
		loc := s.state.Locations[fixedStartNodeID]
		if loc != nil && loc.Active {
			startNodes = append(startNodes, loc)
		}
	} else {
		locIDs := make([]string, 0, len(s.state.Locations))
		for id := range s.state.Locations {
			locIDs = append(locIDs, id)
		}
		sort.Strings(locIDs)
		for _, id := range locIDs {
			loc := s.state.Locations[id]
			if !loc.Active || !loc.Functions.CollectionPoint {
				continue
			}
			if originNodeID != "" && loc.LocationID != originNodeID {
				continue
			}
			cov := loc.CoverageKm
			if cov <= 0 || cov > 5.0 {
				cov = 5.0
			}
			dist := HaversineKm(origin, loc.Coordinate)
			if dist <= cov+1e-6 && dist <= 5.0+1e-6 {
				startNodes = append(startNodes, loc)
			}
		}
	}
	if len(startNodes) == 0 {
		return false, "outside_service_coverage", nil
	}

	// 2. Find active accepting laboratories
	acceptingLabs := map[string]*Location{}
	for id, loc := range s.state.Locations {
		if loc.Active && loc.Functions.Laboratory && s.labAcceptsSampleTypeLocked(id, st.SampleTypeID) {
			acceptingLabs[id] = loc
		}
	}
	if len(acceptingLabs) == 0 {
		return false, "no_accepting_laboratory", nil
	}

	// 3. Enumerate simple active paths from startNodes to acceptingLabs
	type rawPath struct {
		nodeIDs []string
		connIDs []string
	}
	var allPaths []rawPath

	adj := map[string][]*Connection{}
	connIDs := make([]string, 0, len(s.state.Connections))
	for id := range s.state.Connections {
		connIDs = append(connIDs, id)
	}
	sort.Strings(connIDs)
	for _, cid := range connIDs {
		c := s.state.Connections[cid]
		if !c.Active {
			continue
		}
		fromLoc := s.state.Locations[c.FromLocationID]
		toLoc := s.state.Locations[c.ToLocationID]
		if fromLoc == nil || !fromLoc.Active || toLoc == nil || !toLoc.Active {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], c)
	}

	var dfs func(curr string, visited map[string]bool, nodes []string, conns []string)
	dfs = func(curr string, visited map[string]bool, nodes []string, conns []string) {
		if len(conns) > 0 {
			if _, isLab := acceptingLabs[curr]; isLab {
				nCopy := append([]string{}, nodes...)
				cCopy := append([]string{}, conns...)
				allPaths = append(allPaths, rawPath{nodeIDs: nCopy, connIDs: cCopy})
			}
		}
		if len(conns) >= 8 {
			return
		}
		// Can only continue through curr if curr is start node or has transfer/hub/collection function
		if len(conns) > 0 {
			loc := s.state.Locations[curr]
			if loc == nil || (!loc.Functions.TransferPoint && !loc.Functions.Hub && !loc.Functions.CollectionPoint) {
				return
			}
		}
		for _, c := range adj[curr] {
			if visited[c.ToLocationID] {
				continue
			}
			visited[c.ToLocationID] = true
			dfs(c.ToLocationID, visited, append(nodes, c.ToLocationID), append(conns, c.ConnectionID))
			delete(visited, c.ToLocationID)
		}
	}

	for _, sn := range startNodes {
		visited := map[string]bool{sn.LocationID: true}
		dfs(sn.LocationID, visited, []string{sn.LocationID}, nil)
	}

	if len(allPaths) == 0 {
		return false, "no_route", nil
	}

	// 4. Filter by handling rules (cooled route requirement)
	needsCooled := s.sampleNeedsCooledLocked(st)
	var handlingValid []rawPath
	for _, p := range allPaths {
		ok := true
		if needsCooled {
			for _, cid := range p.connIDs {
				if !s.state.Connections[cid].Cooled {
					ok = false
					break
				}
			}
		}
		if ok {
			handlingValid = append(handlingValid, p)
		}
	}
	if len(handlingValid) == 0 {
		return false, "handling_rules_unsatisfiable", nil
	}

	// 5. Filter by available capacity
	var capValid []routeCandidate
	for _, p := range handlingValid {
		ok := true
		minAvail := 1000000
		for _, nid := range p.nodeIDs {
			loc := s.state.Locations[nid]
			capState := s.getLocationCapacityLocked(loc)
			avail := capState.AvailableUnits
			if needsCooled {
				avail = capState.CooledAvailableUnits
			}
			if avail < units {
				ok = false
				break
			}
			if avail < minAvail {
				minAvail = avail
			}
		}
		if !ok {
			continue
		}
		for _, cid := range p.connIDs {
			conn := s.state.Connections[cid]
			capState := s.getConnectionCapacityLocked(conn)
			avail := capState.AvailableUnits
			if needsCooled {
				avail = capState.CooledAvailableUnits
			}
			if avail < units {
				ok = false
				break
			}
			if avail < minAvail {
				minAvail = avail
			}
		}
		if !ok {
			continue
		}

		totalMins := 0
		totalCost := 0.0
		for _, nid := range p.nodeIDs {
			totalMins += s.state.Locations[nid].HandlingMinutes
		}
		for _, cid := range p.connIDs {
			c := s.state.Connections[cid]
			totalMins += c.TravelMinutes
			totalCost += c.CostUnits
		}
		arr := startAt.Add(time.Duration(totalMins) * time.Minute)
		capValid = append(capValid, routeCandidate{
			nodeIDs:       p.nodeIDs,
			connIDs:       p.connIDs,
			totalMinutes:  totalMins,
			totalCost:     totalCost,
			arrivalAt:     arr,
			minAvailUnits: minAvail,
		})
	}
	if len(capValid) == 0 {
		return false, "insufficient_capacity", nil
	}

	// 6. Filter by delivery deadline
	var deadlineValid []routeCandidate
	for _, rc := range capValid {
		if !rc.arrivalAt.After(deadline) {
			deadlineValid = append(deadlineValid, rc)
		}
	}
	if len(deadlineValid) == 0 {
		return false, "deadline_unreachable", nil
	}

	sort.Slice(deadlineValid, func(i, j int) bool {
		if !deadlineValid[i].arrivalAt.Equal(deadlineValid[j].arrivalAt) {
			return deadlineValid[i].arrivalAt.Before(deadlineValid[j].arrivalAt)
		}
		if deadlineValid[i].totalCost != deadlineValid[j].totalCost {
			return deadlineValid[i].totalCost < deadlineValid[j].totalCost
		}
		return len(deadlineValid[i].connIDs) < len(deadlineValid[j].connIDs)
	})

	best := deadlineValid[0]
	return true, "serviceable", &best
}

func (s *Store) reserveJourneyCapacityLocked(j *JourneyPlan, needsCooled bool, units int) {
	if j.ReservedResources == nil {
		j.ReservedResources = make(map[string]bool)
	}
	j.ReservedUnitsCount = units
	seen := map[string]bool{}
	for _, st := range j.OrderedStops {
		if st.LocationID != "" && !seen[st.LocationID] {
			seen[st.LocationID] = true
			if loc := s.state.Locations[st.LocationID]; loc != nil {
				if needsCooled {
					loc.Capacity.CooledReservedUnits += units
				} else {
					loc.Capacity.ReservedUnits += units
				}
				j.ReservedResources[st.LocationID] = needsCooled
			}
		}
	}
	for _, leg := range j.Legs {
		if leg.ConnectionID != "" && !seen[leg.ConnectionID] {
			seen[leg.ConnectionID] = true
			if conn := s.state.Connections[leg.ConnectionID]; conn != nil {
				if needsCooled {
					conn.Capacity.CooledReservedUnits += units
				} else {
					conn.Capacity.ReservedUnits += units
				}
				j.ReservedResources[leg.ConnectionID] = needsCooled
			}
		}
	}
}

func (s *Store) releaseJourneyCapacityLocked(j *JourneyPlan) {
	if j == nil || len(j.ReservedResources) == 0 {
		return
	}
	units := j.ReservedUnitsCount
	if units < 1 {
		units = 1
	}
	for resID, cooled := range j.ReservedResources {
		if loc := s.state.Locations[resID]; loc != nil {
			if cooled {
				loc.Capacity.CooledReservedUnits -= units
				if loc.Capacity.CooledReservedUnits < 0 {
					loc.Capacity.CooledReservedUnits = 0
				}
			} else {
				loc.Capacity.ReservedUnits -= units
				if loc.Capacity.ReservedUnits < 0 {
					loc.Capacity.ReservedUnits = 0
				}
			}
		} else if conn := s.state.Connections[resID]; conn != nil {
			if cooled {
				conn.Capacity.CooledReservedUnits -= units
				if conn.Capacity.CooledReservedUnits < 0 {
					conn.Capacity.CooledReservedUnits = 0
				}
			} else {
				conn.Capacity.ReservedUnits -= units
				if conn.Capacity.ReservedUnits < 0 {
					conn.Capacity.ReservedUnits = 0
				}
			}
		}
	}
	j.ReservedResources = make(map[string]bool)
	j.ReservedUnitsCount = 0
}

