}

func (s *Store) activeWorkloadLocked(workerID string) int {
	cnt := 0
	for _, a := range s.state.Assignments {
		if a.WorkerID == workerID || a.OfferedToWorkerID == workerID {
			switch a.Status {
			case "offered", "accepted", "at_pickup", "picked_up", "in_transit", "arrived", "in_progress":
				cnt++
			}
		}
	}
	return cnt
}

func (s *Store) selectNextWorkerForAssignmentLocked(a *Assignment, now time.Time) *User {
	if a.DeclinedByWorkerIDs == nil {
		a.DeclinedByWorkerIDs = make(map[string]bool)
	}
	var candidates []*User
	for _, u := range s.state.Users {
		elig, certOK := s.isWorkerEligibleForAssignmentLocked(u, a, now)
		if !elig || !certOK {
			continue
		}
		if !u.Available || u.CapacityUnits <= 0 {
			continue
		}
		if u.ReservedUnits >= u.CapacityUnits {
			continue
		}
		if a.DeclinedByWorkerIDs[u.UserID] {
			continue
		}
		candidates = append(candidates, u)
	}
	// If all eligible available workers previously declined, allow re-offering to least-declined available worker
	// only when not immediately in the same decline call (caller adds declining worker to DeclinedByWorkerIDs before calling).
	if len(candidates) == 0 {
		return nil
	}
	sort.Slice(candidates, func(i, j int) bool {
		wi := s.activeWorkloadLocked(candidates[i].UserID)
		wj := s.activeWorkloadLocked(candidates[j].UserID)
		if wi != wj {
			return wi < wj
		}
		if candidates[i].AssignmentCount != candidates[j].AssignmentCount {
			return candidates[i].AssignmentCount < candidates[j].AssignmentCount
		}
		if candidates[i].DeclineCount != candidates[j].DeclineCount {
			return candidates[i].DeclineCount < candidates[j].DeclineCount
		}
		if candidates[i].RecentOfferSeq != candidates[j].RecentOfferSeq {
			return candidates[i].RecentOfferSeq < candidates[j].RecentOfferSeq
		}
		return candidates[i].UserID < candidates[j].UserID
	})
	return candidates[0]
}

func (s *Store) offerAssignmentLocked(a *Assignment, now time.Time, actorID, role string) *User {
	w := s.selectNextWorkerForAssignmentLocked(a, now)
	if w == nil {
		a.Status = "pending"
		a.OfferedToWorkerID = ""
		a.WorkerID = ""
		a.OfferExpiresAt = ""
		return nil
	}
	a.Status = "offered"
	a.OfferedToWorkerID = w.UserID
	a.WorkerID = w.UserID
	a.OfferedAt = now.UTC().Format(time.RFC3339)
	a.OfferExpiresAt = now.Add(OfferExpiryDuration).UTC().Format(time.RFC3339)
	w.RecentOfferSeq = s.state.NextOfferSeq
	s.state.NextOfferSeq++

	tl := s.newTimelineEntryLocked(actorID, role, "offer_assignment", "assignment", a.AssignmentID, true, a.OfferedAt, map[string]any{
		"workerId":       w.UserID,
		"kind":           a.Kind,
		"offerExpiresAt": a.OfferExpiresAt,
	})
	a.History = append(a.History, tl)
	if smp := s.state.Samples[a.SampleID]; smp != nil {
		smp.Timeline = append(smp.Timeline, tl)
	}
	s.recordAuditLocked(actorID, role, "offer_assignment", "assignment", a.AssignmentID, true, map[string]any{
		"workerId": w.UserID,
		"sampleId": a.SampleID,
		"kind":     a.Kind,
	})
	return w
}

func (s *Store) expireStaleOffersLocked(now time.Time) {
	for _, a := range s.state.Assignments {
		if a.Status == "offered" && a.OfferExpiresAt != "" {
			exp, err := time.Parse(time.RFC3339, a.OfferExpiresAt)
			if err == nil && now.After(exp) {
				prevWorker := a.OfferedToWorkerID
				if a.DeclinedByWorkerIDs == nil {
					a.DeclinedByWorkerIDs = make(map[string]bool)
				}
				if prevWorker != "" {
					a.DeclinedByWorkerIDs[prevWorker] = true
					if u := s.state.Users[prevWorker]; u != nil {
						u.DeclineCount++
						u.LastDeclinedAt = now.UTC().Format(time.RFC3339)
					}
				}
				w := s.offerAssignmentLocked(a, now, "system", "system")
				if w == nil {
					if smp := s.state.Samples[a.SampleID]; smp != nil && smp.Status != "received" && smp.Status != "cancelled" && smp.Status != "expired" {
						smp.Status = "exception"
						smp.Exception = map[string]any{
							"reason":       "no_qualified_worker_available",
							"code":         "no_qualified_worker",
							"assignmentId": a.AssignmentID,
							"kind":         a.Kind,
						}
					}
				}
			}
		}
	}
}

func (s *Store) syncJourneyAssignmentsLocked(j *JourneyPlan) {
	workerSet := map[string]bool{}
	var workerIDs []string
	for i := range j.Legs {
		if a := s.state.Assignments[j.Legs[i].AssignmentID]; a != nil {
			j.Legs[i].Status = a.Status
			j.Legs[i].WorkerID = a.WorkerID
			j.Legs[i].WorkerSnake = a.WorkerID
			if a.WorkerID != "" && !workerSet[a.WorkerID] {
				workerSet[a.WorkerID] = true
				workerIDs = append(workerIDs, a.WorkerID)
			}
		}
	}
	for _, cid := range j.CollectionAssignmentIDs {
		if a := s.state.Assignments[cid]; a != nil && a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID)
		}
	}
	for _, nid := range j.NodeAssignmentIDs {
		if a := s.state.Assignments[nid]; a != nil && a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID)
		}
	}
	for _, lid := range j.LaboratoryAssignmentIDs {
		if a := s.state.Assignments[lid]; a != nil && a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID)
		}
	}
	j.AssignedWorkerIDs = workerIDs
}

func (s *Store) buildJourneyPlanForSampleLocked(
	smp *Sample,
	rc *routeCandidate,
	startAt time.Time,
	alreadySealed bool,
	actorID, role string,
) *JourneyPlan {
	journeyID := NewUUID()
	now := time.Now().UTC()
	nowStr := now.Format(time.RFC3339)

	// Build stops
	stops := make([]JourneyStop, 0, len(rc.nodeIDs))
	currTime := startAt
	for idx, nid := range rc.nodeIDs {
		loc := s.state.Locations[nid]
		stopType := "handoff"
		if idx == 0 {
			stopType = "pickup"
		} else if idx == len(rc.nodeIDs)-1 {
			stopType = "delivery"
		}
		dwell := 0
		var coord *Coordinate
		if loc != nil {
			dwell = loc.HandlingMinutes
			c := loc.Coordinate
			coord = &c
		}
		if idx > 0 {
			conn := s.state.Connections[rc.connIDs[idx-1]]
			if conn != nil {
				currTime = currTime.Add(time.Duration(conn.TravelMinutes) * time.Minute)
			}
		}
		estStr := currTime.UTC().Format(time.RFC3339)
		stops = append(stops, JourneyStop{
			StopID:          NewUUID(),
			LocationID:      nid,
			LocationIDSnake: nid,
			StopType:        stopType,
			StopTypeSnake:   stopType,
			Sequence:        idx + 1,
			EstimatedAt:     estStr,
			EstimatedSnake:  estStr,
			DwellMinutes:    dwell,
			Coordinate:      coord,
		})
		currTime = currTime.Add(time.Duration(dwell) * time.Minute)
	}

	var activeAssignIDs []string
	var collectionAssignID string
	var collectionAssignIDs []string

	// 1. Collection assignment if not already sealed and originType is home or clinic
	if !alreadySealed && (smp.OriginType == "home" || smp.OriginType == "clinic") {
		caID := NewUUID()
		ca := &Assignment{
			AssignmentID:        caID,
			Kind:                "collection",
			SampleID:            smp.SampleID,
			SampleIDs:           []string{smp.SampleID},
			JourneyID:           journeyID,
			Status:              "pending",
			FromLocationID:      rc.nodeIDs[0],
			ToLocationID:        rc.nodeIDs[0],
			Sequence:            1,
			DeclinedByWorkerIDs: make(map[string]bool),
			History:             []TimelineEntry{},
		}
		s.state.Assignments[caID] = ca
		w := s.offerAssignmentLocked(ca, now, actorID, role)
		if w == nil {
			smp.Status = "exception"
			smp.Exception = map[string]any{
				"reason":       "no_qualified_worker_available",
				"code":         "no_qualified_worker",
				"assignmentId": caID,
				"kind":         "collection",
			}
		}
		collectionAssignID = caID
		collectionAssignIDs = append(collectionAssignIDs, caID)
		activeAssignIDs = append(activeAssignIDs, caID)
	}

	// 2. Transport leg assignments
	legs := make([]JourneyLeg, 0, len(rc.connIDs))
	for idx, cid := range rc.connIDs {
		conn := s.state.Connections[cid]
		taID := NewUUID()
		ta := &Assignment{
			AssignmentID:        taID,
			Kind:                "transport",
			SampleID:            smp.SampleID,
			SampleIDs:           []string{smp.SampleID},
			JourneyID:           journeyID,
			Status:              "pending",
			FromLocationID:      conn.FromLocationID,
			ToLocationID:        conn.ToLocationID,
			ConnectionID:        cid,
			Sequence:            idx + 1,
			DeclinedByWorkerIDs: make(map[string]bool),
			History:             []TimelineEntry{},
		}
		s.state.Assignments[taID] = ta
		w := s.offerAssignmentLocked(ta, now, actorID, role)
		workerID := ""
		if w != nil {
			workerID = w.UserID
		}
		legs = append(legs, JourneyLeg{
			AssignmentID:    taID,
			AssignmentSnake: taID,
			Sequence:        idx + 1,
			Status:          ta.Status,
			FromLocationID:  conn.FromLocationID,
			FromLocSnake:    conn.FromLocationID,
			ToLocationID:    conn.ToLocationID,
			ToLocSnake:      conn.ToLocationID,
			WorkerID:        workerID,
			WorkerSnake:     workerID,
			SampleID:        smp.SampleID,
			ConnectionID:    cid,
		})
		activeAssignIDs = append(activeAssignIDs, taID)
	}

	// 3. Node assignments for intermediate nodes (and start node if a node handler is assigned to it)
	var nodeAssignIDs []string
	for idx := 0; idx < len(rc.nodeIDs)-1; idx++ {
		nid := rc.nodeIDs[idx]
		if idx == 0 {
			// Only create a node assignment at start node if there is a node_handler assigned to nid
			hasHandler := false
			for _, u := range s.state.Users {
				if u.Active && u.AssignedLocationID == nid {
					for _, r := range u.Roles {
						if r == "node_handler" {
							hasHandler = true
							break
						}
					}
				}
			}
			if !hasHandler {
				continue
			}
		}
		inFrom := nid
		if idx > 0 {
			inFrom = rc.nodeIDs[idx-1]
		}
		outTo := rc.nodeIDs[idx+1]
		naID := NewUUID()
		na := &Assignment{
			AssignmentID:           naID,
			Kind:                   "node",
			SampleID:               smp.SampleID,
			SampleIDs:              []string{smp.SampleID},
			JourneyID:              journeyID,
			Status:                 "pending",
			FromLocationID:         nid,
			ToLocationID:           nid,
			NodeID:                 nid,
			IncomingFromLocationID: inFrom,
			OutgoingToLocationID:   outTo,
			Sequence:               idx + 1,
			DeclinedByWorkerIDs:    make(map[string]bool),
			History:                []TimelineEntry{},
		}
		s.state.Assignments[naID] = na
		_ = s.offerAssignmentLocked(na, now, actorID, role)
		nodeAssignIDs = append(nodeAssignIDs, naID)
		activeAssignIDs = append(activeAssignIDs, naID)
	}

	// 4. Laboratory assignment at target laboratory
	targetLabID := rc.nodeIDs[len(rc.nodeIDs)-1]
	laID := NewUUID()
	la := &Assignment{
		AssignmentID:         laID,
		Kind:                 "laboratory",
		SampleID:             smp.SampleID,
		SampleIDs:            []string{smp.SampleID},
		JourneyID:            journeyID,
		Status:               "pending",
		FromLocationID:       targetLabID,
		ToLocationID:         targetLabID,
		LaboratoryID:         targetLabID,
		ExpectedSampleTypeID: smp.SampleTypeID,
		Sequence:             len(rc.connIDs) + 1,
		DeclinedByWorkerIDs:  make(map[string]bool),
		History:              []TimelineEntry{},
	}
	s.state.Assignments[laID] = la
	_ = s.offerAssignmentLocked(la, now, actorID, role)
	labAssignIDs := []string{laID}
	activeAssignIDs = append(activeAssignIDs, laID)

	routeMode := "direct"
	if len(legs) > 1 {
		routeMode = "multi_stop"
	}

	var firstTA, middleTA, finalTA string
	if len(legs) > 0 {
		firstTA = legs[0].AssignmentID
		finalTA = legs[len(legs)-1].AssignmentID
		if len(legs) >= 3 {
			middleTA = legs[1].AssignmentID
		} else if len(legs) == 2 {
			middleTA = legs[1].AssignmentID
		}
	}

	validTrue := true
	capAvail := rc.minAvailUnits - 1
	if capAvail < 0 {
		capAvail = 0
	}

	jp := &JourneyPlan{
		JourneyID:                   journeyID,
		PlanVersion:                 1,
		RouteMode:                   routeMode,
		Status:                      "planned",
		EstimatedDeliveryAt:         rc.arrivalAt.UTC().Format(time.RFC3339),
		TotalCostUnits:              rc.totalCost,
		CapacityUsed:                1,
		CapacityAvailable:           capAvail,
		SampleIDs:                   []string{smp.SampleID},
		OrderedStops:                stops,
		Legs:                        legs,
		CollectionAssignmentID:      collectionAssignID,
		CollectionAssignmentIDs:     collectionAssignIDs,
		NodeAssignmentIDs:           nodeAssignIDs,
		LaboratoryAssignmentIDs:     labAssignIDs,
		FirstTransportAssignmentID:  firstTA,
		MiddleTransportAssignmentID: middleTA,
		FinalTransportAssignmentID:  finalTA,
		Valid:                       &validTrue,
		History: []TimelineEntry{
			s.newTimelineEntryLocked(actorID, role, "create_journey", "journey", journeyID, true, nowStr, map[string]any{
				"sampleId":  smp.SampleID,
				"routeMode": routeMode,
			}),
		},
		ReservedResources: make(map[string]bool),
	}
	s.syncJourneyAssignmentsLocked(jp)

	st := s.state.SampleTypes[smp.SampleTypeID]
	s.reserveJourneyCapacityLocked(jp, s.sampleNeedsCooledLocked(st), 1)
	s.state.Journeys[journeyID] = jp

	smp.ActiveJourneyID = journeyID
	smp.TargetLaboratoryID = targetLabID
	smp.ActiveAssignmentIDs = activeAssignIDs
	return jp
}
