package internal

import (
	"sort"
	"strings"
	"time"
)

type routeCandidate struct {
	nodeIDs       []string
	connIDs       []string
	totalMinutes  int
	totalCost     float64
	arrivalAt     time.Time
	minAvailUnits int
}

func (s *Store) getLocationCapacityLocked(loc *Location) Capacity {
	capUnits := loc.Capacity.CapacityUnits
	cooledUnits := loc.Capacity.CooledCapacityUnits
	if !loc.CapacityConfigured {
		capUnits = DefaultNodeCapacity
		cooledUnits = DefaultNodeCapacity
	}
	avail := capUnits - loc.Capacity.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledUnits - loc.Capacity.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return Capacity{
		CapacityUnits:        capUnits,
		ReservedUnits:        loc.Capacity.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  cooledUnits,
		CooledReservedUnits:  loc.Capacity.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func (s *Store) getConnectionCapacityLocked(conn *Connection) Capacity {
	capUnits := conn.Capacity.CapacityUnits
	cooledUnits := conn.Capacity.CooledCapacityUnits
	if !conn.CapacityConfigured {
		capUnits = DefaultConnCapacity
		if conn.Cooled {
			cooledUnits = DefaultConnCapacity
		} else {
			cooledUnits = 0
		}
	}
	avail := capUnits - conn.Capacity.ReservedUnits
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledUnits - conn.Capacity.CooledReservedUnits
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return Capacity{
		CapacityUnits:        capUnits,
		ReservedUnits:        conn.Capacity.ReservedUnits,
		AvailableUnits:       avail,
		CooledCapacityUnits:  cooledUnits,
		CooledReservedUnits:  conn.Capacity.CooledReservedUnits,
		CooledAvailableUnits: cooledAvail,
	}
}

func (s *Store) recomputeServiceabilityLocked(bumpRevision bool) {
	if bumpRevision {
		s.state.NetworkRevision++
		s.state.ServiceabilityVersionSeq++
	}
	if s.state.ServiceabilityVersionSeq < 1 {
		s.state.ServiceabilityVersionSeq = 1
	}
	regions := []ServiceabilityRegion{}
	locIDs := make([]string, 0, len(s.state.Locations))
	for id := range s.state.Locations {
		locIDs = append(locIDs, id)
	}
	sort.Strings(locIDs)
	for _, id := range locIDs {
		loc := s.state.Locations[id]
		if loc.Active && loc.Functions.CollectionPoint {
			regions = append(regions, ServiceabilityRegion{
				LocationID: loc.LocationID,
				Name:       loc.Name,
				Latitude:   loc.Coordinate.Latitude,
				Longitude:  loc.Coordinate.Longitude,
				CoverageKm: loc.CoverageKm,
			})
		}
	}
	s.state.ServiceabilitySnapshot = ServiceabilitySnapshot{
		Version:                    s.state.ServiceabilityVersionSeq,
		Status:                     "complete",
		ComputedAt:                 time.Now().UTC().Format(time.RFC3339),
		NetworkRevision:            s.state.NetworkRevision,
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}
}

func (s *Store) labAcceptsSampleTypeLocked(labID, sampleTypeID string) bool {
	m, ok := s.state.LabAcceptances[labID]
	if !ok {
		return false
	}
	accID, ok := m[sampleTypeID]
	return ok && accID != ""
}

func (s *Store) sampleNeedsCooledLocked(st *SampleType) bool {
	if st == nil {
		return false
	}
	return st.RequiresCooledRoute || strings.EqualFold(st.Name, "Frost")
}

func (s *Store) sampleDisallowsBatchingLocked(st *SampleType) bool {
	if st == nil {
		return false
	}
	return !st.BatchingAllowed || strings.EqualFold(st.Name, "Pulse")
}

func (s *Store) samplesCompatibleLocked(a, b *Sample) bool {
	stA := s.state.SampleTypes[a.SampleTypeID]
	stB := s.state.SampleTypes[b.SampleTypeID]
	if stA == nil || stB == nil {
		return false
	}
	if (strings.EqualFold(stA.Name, "Amber") && strings.EqualFold(stB.Name, "Indigo")) ||
		(strings.EqualFold(stA.Name, "Indigo") && strings.EqualFold(stB.Name, "Amber")) {
		return false
	}
	for _, inc := range stA.IncompatibleSampleTypes {
		if inc == stB.SampleTypeID {
			return false
		}
	}
	for _, inc := range stB.IncompatibleSampleTypes {
		if inc == stA.SampleTypeID {
			return false
		}
	}
	for _, inc := range a.IncompatibleSampleTypes {
		if inc == b.SampleTypeID {
			return false
		}
	}
	for _, inc := range b.IncompatibleSampleTypes {
		if inc == a.SampleTypeID {
			return false
		}
	}
	// Check overlapping temperature range
	minT := a.TemperatureMinC
	if b.TemperatureMinC > minT {
		minT = b.TemperatureMinC
	}
	maxT := a.TemperatureMaxC
	if b.TemperatureMaxC < maxT {
		maxT = b.TemperatureMaxC
	}
	if minT > maxT {
		return false
	}
	return true
}

func (s *Store) evaluateServiceabilityLocked(
	origin Coordinate,
	originType string,
	originNodeID string,
	st *SampleType,
	startAt time.Time,
	deadline time.Time,
	units int,
	fixedStartNodeID string,
) (bool, string, *routeCandidate) {
	if units < 1 {
		units = 1
	}

	// 1. Find candidate start nodes
	startNodes := []*Location{}
	if fixedStartNodeID != "" {
		loc := s.state.Locations[fixedStartNodeID]
		if loc != nil && loc.Active {
			startNodes = append(startNodes, loc)
		}
	} else {
		locIDs := make([]string, 0, len(s.state.Locations))
		for id := range s.state.Locations {
			locIDs = append(locIDs, id)
		}
		sort.Strings(locIDs)
		for _, id := range locIDs {
			loc := s.state.Locations[id]
			if !loc.Active || !loc.Functions.CollectionPoint {
				continue
			}
			if originNodeID != "" && loc.LocationID != originNodeID {
				continue
			}
			cov := loc.CoverageKm
			if cov <= 0 || cov > 5.0 {
				cov = 5.0
			}
			dist := HaversineKm(origin, loc.Coordinate)
			if dist <= cov+1e-6 && dist <= 5.0+1e-6 {
				startNodes = append(startNodes, loc)
			}
		}
	}
	if len(startNodes) == 0 {
		return false, "outside_service_coverage", nil
	}

	// 2. Find active accepting laboratories
	acceptingLabs := map[string]*Location{}
	for id, loc := range s.state.Locations {
		if loc.Active && loc.Functions.Laboratory && s.labAcceptsSampleTypeLocked(id, st.SampleTypeID) {
			acceptingLabs[id] = loc
		}
	}
	if len(acceptingLabs) == 0 {
		return false, "no_accepting_laboratory", nil
	}

	// 3. Enumerate simple active paths from startNodes to acceptingLabs
	type rawPath struct {
		nodeIDs []string
		connIDs []string
	}
	var allPaths []rawPath

	adj := map[string][]*Connection{}
	connIDs := make([]string, 0, len(s.state.Connections))
	for id := range s.state.Connections {
		connIDs = append(connIDs, id)
	}
	sort.Strings(connIDs)
	for _, cid := range connIDs {
		c := s.state.Connections[cid]
		if !c.Active {
			continue
		}
		fromLoc := s.state.Locations[c.FromLocationID]
		toLoc := s.state.Locations[c.ToLocationID]
		if fromLoc == nil || !fromLoc.Active || toLoc == nil || !toLoc.Active {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], c)
	}

	var dfs func(curr string, visited map[string]bool, nodes []string, conns []string)
	dfs = func(curr string, visited map[string]bool, nodes []string, conns []string) {
		if len(conns) > 0 {
			if _, isLab := acceptingLabs[curr]; isLab {
				nCopy := append([]string{}, nodes...)
				cCopy := append([]string{}, conns...)
				allPaths = append(allPaths, rawPath{nodeIDs: nCopy, connIDs: cCopy})
			}
		}
		if len(conns) >= 8 {
			return
		}
		// Can only continue through curr if curr is start node or has transfer/hub/collection function
		if len(conns) > 0 {
			loc := s.state.Locations[curr]
			if loc == nil || (!loc.Functions.TransferPoint && !loc.Functions.Hub && !loc.Functions.CollectionPoint) {
				return
			}
		}
		for _, c := range adj[curr] {
			if visited[c.ToLocationID] {
				continue
			}
			visited[c.ToLocationID] = true
			dfs(c.ToLocationID, visited, append(nodes, c.ToLocationID), append(conns, c.ConnectionID))
			delete(visited, c.ToLocationID)
		}
	}

	for _, sn := range startNodes {
		visited := map[string]bool{sn.LocationID: true}
		dfs(sn.LocationID, visited, []string{sn.LocationID}, nil)
	}

	if len(allPaths) == 0 {
		return false, "no_route", nil
	}

	// 4. Filter by handling rules (cooled route requirement)
	needsCooled := s.sampleNeedsCooledLocked(st)
	var handlingValid []rawPath
	for _, p := range allPaths {
		ok := true
		if needsCooled {
			for _, cid := range p.connIDs {
				if !s.state.Connections[cid].Cooled {
					ok = false
					break
				}
			}
		}
		if ok {
			handlingValid = append(handlingValid, p)
		}
	}
	if len(handlingValid) == 0 {
		return false, "handling_rules_unsatisfiable", nil
	}

	// 5. Filter by available capacity
	var capValid []routeCandidate
	for _, p := range handlingValid {
		ok := true
		minAvail := 1000000
		for _, nid := range p.nodeIDs {
			loc := s.state.Locations[nid]
			capState := s.getLocationCapacityLocked(loc)
			avail := capState.AvailableUnits
			if needsCooled {
				avail = capState.CooledAvailableUnits
			}
			if avail < units {
				ok = false
				break
			}
			if avail < minAvail {
				minAvail = avail
			}
		}
		if !ok {
			continue
		}
		for _, cid := range p.connIDs {
			conn := s.state.Connections[cid]
			capState := s.getConnectionCapacityLocked(conn)
			avail := capState.AvailableUnits
			if needsCooled {
				avail = capState.CooledAvailableUnits
			}
			if avail < units {
				ok = false
				break
			}
			if avail < minAvail {
				minAvail = avail
			}
		}
		if !ok {
			continue
		}

		totalMins := 0
		totalCost := 0.0
		for _, nid := range p.nodeIDs {
			totalMins += s.state.Locations[nid].HandlingMinutes
		}
		for _, cid := range p.connIDs {
			c := s.state.Connections[cid]
			totalMins += c.TravelMinutes
			totalCost += c.CostUnits
		}
		arr := startAt.Add(time.Duration(totalMins) * time.Minute)
		capValid = append(capValid, routeCandidate{
			nodeIDs:       p.nodeIDs,
			connIDs:       p.connIDs,
			totalMinutes:  totalMins,
			totalCost:     totalCost,
			arrivalAt:     arr,
			minAvailUnits: minAvail,
		})
	}
	if len(capValid) == 0 {
		return false, "insufficient_capacity", nil
	}

	// 6. Filter by delivery deadline
	var deadlineValid []routeCandidate
	for _, rc := range capValid {
		if !rc.arrivalAt.After(deadline) {
			deadlineValid = append(deadlineValid, rc)
		}
	}
	if len(deadlineValid) == 0 {
		return false, "deadline_unreachable", nil
	}

	sort.Slice(deadlineValid, func(i, j int) bool {
		if !deadlineValid[i].arrivalAt.Equal(deadlineValid[j].arrivalAt) {
			return deadlineValid[i].arrivalAt.Before(deadlineValid[j].arrivalAt)
		}
		if deadlineValid[i].totalCost != deadlineValid[j].totalCost {
			return deadlineValid[i].totalCost < deadlineValid[j].totalCost
		}
		return len(deadlineValid[i].connIDs) < len(deadlineValid[j].connIDs)
	})

	best := deadlineValid[0]
	return true, "serviceable", &best
}

func (s *Store) reserveJourneyCapacityLocked(j *JourneyPlan, needsCooled bool, units int) {
	if j.ReservedResources == nil {
		j.ReservedResources = make(map[string]bool)
	}
	j.ReservedUnitsCount = units
	seen := map[string]bool{}
	for _, st := range j.OrderedStops {
		if st.LocationID != "" && !seen[st.LocationID] {
			seen[st.LocationID] = true
			if loc := s.state.Locations[st.LocationID]; loc != nil {
				if needsCooled {
					loc.Capacity.CooledReservedUnits += units
				} else {
					loc.Capacity.ReservedUnits += units
				}
				j.ReservedResources[st.LocationID] = needsCooled
			}
		}
	}
	for _, leg := range j.Legs {
		if leg.ConnectionID != "" && !seen[leg.ConnectionID] {
			seen[leg.ConnectionID] = true
			if conn := s.state.Connections[leg.ConnectionID]; conn != nil {
				if needsCooled {
					conn.Capacity.CooledReservedUnits += units
				} else {
					conn.Capacity.ReservedUnits += units
				}
				j.ReservedResources[leg.ConnectionID] = needsCooled
			}
		}
	}
}

func (s *Store) releaseJourneyCapacityLocked(j *JourneyPlan) {
	if j == nil || len(j.ReservedResources) == 0 {
		return
	}
	units := j.ReservedUnitsCount
	if units < 1 {
		units = 1
	}
	for resID, cooled := range j.ReservedResources {
		if loc := s.state.Locations[resID]; loc != nil {
			if cooled {
				loc.Capacity.CooledReservedUnits -= units
				if loc.Capacity.CooledReservedUnits < 0 {
					loc.Capacity.CooledReservedUnits = 0
				}
			} else {
				loc.Capacity.ReservedUnits -= units
				if loc.Capacity.ReservedUnits < 0 {
					loc.Capacity.ReservedUnits = 0
				}
			}
		} else if conn := s.state.Connections[resID]; conn != nil {
			if cooled {
				conn.Capacity.CooledReservedUnits -= units
				if conn.Capacity.CooledReservedUnits < 0 {
					conn.Capacity.CooledReservedUnits = 0
				}
			} else {
				conn.Capacity.ReservedUnits -= units
				if conn.Capacity.ReservedUnits < 0 {
					conn.Capacity.ReservedUnits = 0
				}
			}
		}
	}
	j.ReservedResources = make(map[string]bool)
	j.ReservedUnitsCount = 0
}

func (s *Store) isCollectorQualifiedAndActiveLocked(u *User, st *SampleType, atTime time.Time) (qualified bool, certActive bool) {
	if st == nil || !st.QualifiedCollectorRequired {
		return true, true
	}
	reqQual := strings.TrimSpace(st.RequiredQualification)
	if reqQual == "" {
		reqQual = strings.TrimSpace(st.Name)
	}
	hasQual := false
	for _, q := range u.Qualifications {
		if strings.EqualFold(strings.TrimSpace(q), reqQual) || strings.EqualFold(strings.TrimSpace(q), st.Name) {
			hasQual = true
			break
		}
	}
	matchedCerts := 0
	activeCerts := 0
	for _, c := range u.Certifications {
		if strings.EqualFold(strings.TrimSpace(c.Code), reqQual) || strings.EqualFold(strings.TrimSpace(c.Code), st.Name) {
			matchedCerts++
			if c.Active {
				expired := false
				if c.ExpiresAt != "" {
					if exp, err := time.Parse(time.RFC3339, c.ExpiresAt); err == nil {
						if !atTime.IsZero() && atTime.After(exp) {
							expired = true
						}
					}
				}
				if !expired {
					activeCerts++
				}
			}
		}
	}
	if matchedCerts > 0 {
		if activeCerts == 0 {
			return true, false
		}
		return true, true
	}
	if hasQual {
		return true, true
	}
	return false, false
}

func (s *Store) isWorkerEligibleForAssignmentLocked(u *User, a *Assignment, checkTime time.Time) (eligible bool, certActive bool) {
	if u == nil || !u.Active {
		return false, false
	}
	hasRole := func(r string) bool {
		for _, ur := range u.Roles {
			if ur == r {
				return true
			}
		}
		return false
	}
	switch a.Kind {
	case "collection":
		if !hasRole("collection_professional") {
			return false, false
		}
		smp := s.state.Samples[a.SampleID]
		if smp != nil {
			st := s.state.SampleTypes[smp.SampleTypeID]
			q, ca := s.isCollectorQualifiedAndActiveLocked(u, st, checkTime)
			if !q {
				return false, false
			}
			if !ca {
				return true, false
			}
		}
		return true, true
	case "transport":
		if !hasRole("delivery_partner") {
			return false, false
		}
		return true, true
	case "node":
		if !hasRole("node_handler") {
			return false, false
		}
		if a.NodeID != "" && u.AssignedLocationID != a.NodeID {
			return false, false
		}
		return true, true
	case "laboratory":
		if !hasRole("laboratory_team") {
			return false, false
		}
		if a.LaboratoryID != "" && u.AssignedLocationID != a.LaboratoryID {
			return false, false
		}
		return true, true
	}
	return false, false
}

func (s *Store) activeWorkloadLocked(workerID string) int {
	cnt := 0
	for _, a := range s.state.Assignments {
		if a.WorkerID == workerID || a.OfferedToWorkerID == workerID {
			switch a.Status {
			case "offered", "accepted", "at_pickup", "picked_up", "in_transit", "arrived", "in_progress":
				cnt++
			}
		}
	}
	return cnt
}

func (s *Store) selectNextWorkerForAssignmentLocked(a *Assignment, now time.Time) *User {
	if a.DeclinedByWorkerIDs == nil {
		a.DeclinedByWorkerIDs = make(map[string]bool)
	}
	var candidates []*User
	for _, u := range s.state.Users {
		elig, certOK := s.isWorkerEligibleForAssignmentLocked(u, a, now)
		if !elig || !certOK {
			continue
		}
		if !u.Available || u.CapacityUnits <= 0 {
			continue
		}
		if u.ReservedUnits >= u.CapacityUnits {
			continue
		}
		if a.DeclinedByWorkerIDs[u.UserID] {
			continue
		}
		candidates = append(candidates, u)
	}
	// If all eligible available workers previously declined, allow re-offering to least-declined available worker
	// only when not immediately in the same decline call (caller adds declining worker to DeclinedByWorkerIDs before calling).
	if len(candidates) == 0 {
		return nil
	}
	sort.Slice(candidates, func(i, j int) bool {
		wi := s.activeWorkloadLocked(candidates[i].UserID)
		wj := s.activeWorkloadLocked(candidates[j].UserID)
		if wi != wj {
			return wi < wj
		}
		if candidates[i].AssignmentCount != candidates[j].AssignmentCount {
			return candidates[i].AssignmentCount < candidates[j].AssignmentCount
		}
		if candidates[i].DeclineCount != candidates[j].DeclineCount {
			return candidates[i].DeclineCount < candidates[j].DeclineCount
		}
		if candidates[i].RecentOfferSeq != candidates[j].RecentOfferSeq {
			return candidates[i].RecentOfferSeq < candidates[j].RecentOfferSeq
		}
		return candidates[i].UserID < candidates[j].UserID
	})
	return candidates[0]
}

func (s *Store) offerAssignmentLocked(a *Assignment, now time.Time, actorID, role string) *User {
	w := s.selectNextWorkerForAssignmentLocked(a, now)
	if w == nil {
		a.Status = "pending"
		a.OfferedToWorkerID = ""
		a.WorkerID = ""
		a.OfferExpiresAt = ""
		return nil
	}
	a.Status = "offered"
	a.OfferedToWorkerID = w.UserID
	a.WorkerID = w.UserID
	a.OfferedAt = now.UTC().Format(time.RFC3339)
	a.OfferExpiresAt = now.Add(OfferExpiryDuration).UTC().Format(time.RFC3339)
	w.RecentOfferSeq = s.state.NextOfferSeq
	s.state.NextOfferSeq++

	tl := s.newTimelineEntryLocked(actorID, role, "offer_assignment", "assignment", a.AssignmentID, true, a.OfferedAt, map[string]any{
		"workerId":       w.UserID,
		"kind":           a.Kind,
		"offerExpiresAt": a.OfferExpiresAt,
	})
	a.History = append(a.History, tl)
	if smp := s.state.Samples[a.SampleID]; smp != nil {
		smp.Timeline = append(smp.Timeline, tl)
	}
	s.recordAuditLocked(actorID, role, "offer_assignment", "assignment", a.AssignmentID, true, map[string]any{
		"workerId": w.UserID,
		"sampleId": a.SampleID,
		"kind":     a.Kind,
	})
	return w
}

func (s *Store) expireStaleOffersLocked(now time.Time) {
	for _, a := range s.state.Assignments {
		if a.Status == "offered" && a.OfferExpiresAt != "" {
			exp, err := time.Parse(time.RFC3339, a.OfferExpiresAt)
			if err == nil && now.After(exp) {
				prevWorker := a.OfferedToWorkerID
				if a.DeclinedByWorkerIDs == nil {
					a.DeclinedByWorkerIDs = make(map[string]bool)
				}
				if prevWorker != "" {
					a.DeclinedByWorkerIDs[prevWorker] = true
					if u := s.state.Users[prevWorker]; u != nil {
						u.DeclineCount++
						u.LastDeclinedAt = now.UTC().Format(time.RFC3339)
					}
				}
				w := s.offerAssignmentLocked(a, now, "system", "system")
				if w == nil {
					if smp := s.state.Samples[a.SampleID]; smp != nil && smp.Status != "received" && smp.Status != "cancelled" && smp.Status != "expired" {
						smp.Status = "exception"
						smp.Exception = map[string]any{
							"reason":       "no_qualified_worker_available",
							"code":         "no_qualified_worker",
							"assignmentId": a.AssignmentID,
							"kind":         a.Kind,
						}
					}
				}
			}
		}
	}
}

func (s *Store) syncJourneyAssignmentsLocked(j *JourneyPlan) {
	workerSet := map[string]bool{}
	var workerIDs []string
	for i := range j.Legs {
		if a := s.state.Assignments[j.Legs[i].AssignmentID]; a != nil {
			j.Legs[i].Status = a.Status
			j.Legs[i].WorkerID = a.WorkerID
			j.Legs[i].WorkerSnake = a.WorkerID
			if a.WorkerID != "" && !workerSet[a.WorkerID] {
				workerSet[a.WorkerID] = true
				workerIDs = append(workerIDs, a.WorkerID)
			}
		}
	}
	for _, cid := range j.CollectionAssignmentIDs {
		if a := s.state.Assignments[cid]; a != nil && a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID)
		}
	}
	for _, nid := range j.NodeAssignmentIDs {
		if a := s.state.Assignments[nid]; a != nil && a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID)
		}
	}
	for _, lid := range j.LaboratoryAssignmentIDs {
		if a := s.state.Assignments[lid]; a != nil && a.WorkerID != "" && !workerSet[a.WorkerID] {
			workerSet[a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID)
		}
	}
	j.AssignedWorkerIDs = workerIDs
}

func (s *Store) buildJourneyPlanForSampleLocked(
	smp *Sample,
	rc *routeCandidate,
	startAt time.Time,
	alreadySealed bool,
	actorID, role string,
) *JourneyPlan {
	journeyID := NewUUID()
	now := time.Now().UTC()
	nowStr := now.Format(time.RFC3339)

	// Build stops
	stops := make([]JourneyStop, 0, len(rc.nodeIDs))
	currTime := startAt
	for idx, nid := range rc.nodeIDs {
		loc := s.state.Locations[nid]
		stopType := "handoff"
		if idx == 0 {
			stopType = "pickup"
		} else if idx == len(rc.nodeIDs)-1 {
			stopType = "delivery"
		}
		dwell := 0
		var coord *Coordinate
		if loc != nil {
			dwell = loc.HandlingMinutes
			c := loc.Coordinate
			coord = &c
		}
		if idx > 0 {
			conn := s.state.Connections[rc.connIDs[idx-1]]
			if conn != nil {
				currTime = currTime.Add(time.Duration(conn.TravelMinutes) * time.Minute)
			}
		}
		estStr := currTime.UTC().Format(time.RFC3339)
		stops = append(stops, JourneyStop{
			StopID:          NewUUID(),
			LocationID:      nid,
			LocationIDSnake: nid,
			StopType:        stopType,
			StopTypeSnake:   stopType,
			Sequence:        idx + 1,
			EstimatedAt:     estStr,
			EstimatedSnake:  estStr,
			DwellMinutes:    dwell,
			Coordinate:      coord,
		})
		currTime = currTime.Add(time.Duration(dwell) * time.Minute)
	}

	var activeAssignIDs []string
	var collectionAssignID string
	var collectionAssignIDs []string

	// 1. Collection assignment if not already sealed and originType is home or clinic
	if !alreadySealed && (smp.OriginType == "home" || smp.OriginType == "clinic") {
		caID := NewUUID()
		ca := &Assignment{
			AssignmentID:        caID,
			Kind:                "collection",
			SampleID:            smp.SampleID,
			SampleIDs:           []string{smp.SampleID},
			JourneyID:           journeyID,
			Status:              "pending",
			FromLocationID:      rc.nodeIDs[0],
			ToLocationID:        rc.nodeIDs[0],
			Sequence:            1,
			DeclinedByWorkerIDs: make(map[string]bool),
			History:             []TimelineEntry{},
		}
		s.state.Assignments[caID] = ca
		w := s.offerAssignmentLocked(ca, now, actorID, role)
		if w == nil {
			smp.Status = "exception"
			smp.Exception = map[string]any{
				"reason":       "no_qualified_worker_available",
				"code":         "no_qualified_worker",
				"assignmentId": caID,
				"kind":         "collection",
			}
		}
		collectionAssignID = caID
		collectionAssignIDs = append(collectionAssignIDs, caID)
		activeAssignIDs = append(activeAssignIDs, caID)
	}

	// 2. Transport leg assignments
	legs := make([]JourneyLeg, 0, len(rc.connIDs))
	for idx, cid := range rc.connIDs {
		conn := s.state.Connections[cid]
		taID := NewUUID()
		ta := &Assignment{
			AssignmentID:        taID,
			Kind:                "transport",
			SampleID:            smp.SampleID,
			SampleIDs:           []string{smp.SampleID},
			JourneyID:           journeyID,
			Status:              "pending",
			FromLocationID:      conn.FromLocationID,
			ToLocationID:        conn.ToLocationID,
			ConnectionID:        cid,
			Sequence:            idx + 1,
			DeclinedByWorkerIDs: make(map[string]bool),
			History:             []TimelineEntry{},
		}
		s.state.Assignments[taID] = ta
		w := s.offerAssignmentLocked(ta, now, actorID, role)
		workerID := ""
		if w != nil {
			workerID = w.UserID
		}
		legs = append(legs, JourneyLeg{
			AssignmentID:    taID,
			AssignmentSnake: taID,
			Sequence:        idx + 1,
			Status:          ta.Status,
			FromLocationID:  conn.FromLocationID,
			FromLocSnake:    conn.FromLocationID,
			ToLocationID:    conn.ToLocationID,
			ToLocSnake:      conn.ToLocationID,
			WorkerID:        workerID,
			WorkerSnake:     workerID,
			SampleID:        smp.SampleID,
			ConnectionID:    cid,
		})
		activeAssignIDs = append(activeAssignIDs, taID)
	}

	// 3. Node assignments for intermediate nodes (and start node if a node handler is assigned to it)
	var nodeAssignIDs []string
	for idx := 0; idx < len(rc.nodeIDs)-1; idx++ {
		nid := rc.nodeIDs[idx]
		if idx == 0 {
			// Only create a node assignment at start node if there is a node_handler assigned to nid
			hasHandler := false
			for _, u := range s.state.Users {
				if u.Active && u.AssignedLocationID == nid {
					for _, r := range u.Roles {
						if r == "node_handler" {
							hasHandler = true
							break
						}
					}
				}
			}
			if !hasHandler {
				continue
			}
		}
		inFrom := nid
		if idx > 0 {
			inFrom = rc.nodeIDs[idx-1]
		}
		outTo := rc.nodeIDs[idx+1]
		naID := NewUUID()
		na := &Assignment{
			AssignmentID:           naID,
			Kind:                   "node",
			SampleID:               smp.SampleID,
			SampleIDs:              []string{smp.SampleID},
			JourneyID:              journeyID,
			Status:                 "pending",
			FromLocationID:         nid,
			ToLocationID:           nid,
			NodeID:                 nid,
			IncomingFromLocationID: inFrom,
			OutgoingToLocationID:   outTo,
			Sequence:               idx + 1,
			DeclinedByWorkerIDs:    make(map[string]bool),
			History:                []TimelineEntry{},
		}
		s.state.Assignments[naID] = na
		_ = s.offerAssignmentLocked(na, now, actorID, role)
		nodeAssignIDs = append(nodeAssignIDs, naID)
		activeAssignIDs = append(activeAssignIDs, naID)
	}

	// 4. Laboratory assignment at target laboratory
	targetLabID := rc.nodeIDs[len(rc.nodeIDs)-1]
	laID := NewUUID()
	la := &Assignment{
		AssignmentID:         laID,
		Kind:                 "laboratory",
		SampleID:             smp.SampleID,
		SampleIDs:            []string{smp.SampleID},
		JourneyID:            journeyID,
		Status:               "pending",
		FromLocationID:       targetLabID,
		ToLocationID:         targetLabID,
		LaboratoryID:         targetLabID,
		ExpectedSampleTypeID: smp.SampleTypeID,
		Sequence:             len(rc.connIDs) + 1,
		DeclinedByWorkerIDs:  make(map[string]bool),
		History:              []TimelineEntry{},
	}
	s.state.Assignments[laID] = la
	_ = s.offerAssignmentLocked(la, now, actorID, role)
	labAssignIDs := []string{laID}
	activeAssignIDs = append(activeAssignIDs, laID)

	routeMode := "direct"
	if len(legs) > 1 {
		routeMode = "multi_stop"
	}

	var firstTA, middleTA, finalTA string
	if len(legs) > 0 {
		firstTA = legs[0].AssignmentID
		finalTA = legs[len(legs)-1].AssignmentID
		if len(legs) >= 3 {
			middleTA = legs[1].AssignmentID
		} else if len(legs) == 2 {
			middleTA = legs[1].AssignmentID
		}
	}

	validTrue := true
	capAvail := rc.minAvailUnits - 1
	if capAvail < 0 {
		capAvail = 0
	}

	jp := &JourneyPlan{
		JourneyID:                   journeyID,
		PlanVersion:                 1,
		RouteMode:                   routeMode,
		Status:                      "planned",
		EstimatedDeliveryAt:         rc.arrivalAt.UTC().Format(time.RFC3339),
		TotalCostUnits:              rc.totalCost,
		CapacityUsed:                1,
		CapacityAvailable:           capAvail,
		SampleIDs:                   []string{smp.SampleID},
		OrderedStops:                stops,
		Legs:                        legs,
		CollectionAssignmentID:      collectionAssignID,
		CollectionAssignmentIDs:     collectionAssignIDs,
		NodeAssignmentIDs:           nodeAssignIDs,
		LaboratoryAssignmentIDs:     labAssignIDs,
		FirstTransportAssignmentID:  firstTA,
		MiddleTransportAssignmentID: middleTA,
		FinalTransportAssignmentID:  finalTA,
		Valid:                       &validTrue,
		History: []TimelineEntry{
			s.newTimelineEntryLocked(actorID, role, "create_journey", "journey", journeyID, true, nowStr, map[string]any{
				"sampleId":  smp.SampleID,
				"routeMode": routeMode,
			}),
		},
		ReservedResources: make(map[string]bool),
	}
	s.syncJourneyAssignmentsLocked(jp)

	st := s.state.SampleTypes[smp.SampleTypeID]
	s.reserveJourneyCapacityLocked(jp, s.sampleNeedsCooledLocked(st), 1)
	s.state.Journeys[journeyID] = jp

	smp.ActiveJourneyID = journeyID
	smp.TargetLaboratoryID = targetLabID
	smp.ActiveAssignmentIDs = activeAssignIDs
	return jp
}

