func (srv *Server) handleRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	srv.store.mu.Lock()
	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		srv.store.mu.Unlock()
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}
	_ = ac

	sinceStr := strings.TrimSpace(r.URL.Query().Get("since"))
	var since int64
	if sinceStr != "" {
		val, err := strconv.ParseInt(sinceStr, 10, 64)
		if err != nil || val < 0 {
			srv.store.mu.Unlock()
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid since parameter")
			return
		}
		since = val
	}

	events := []RealtimeEvent{}
	var cursor int64 = since
	for _, ev := range srv.store.state.RealtimeEvents {
		if ev.ID > since {
			events = append(events, ev)
			if ev.ID > cursor {
				cursor = ev.ID
			}
		}
	}
	srv.store.mu.Unlock()

	if websocket.IsWebSocketUpgrade(r) {
		var respHeader http.Header
		if proto := strings.TrimSpace(r.Header.Get("Sec-WebSocket-Protocol")); proto != "" {
			parts := strings.Split(proto, ",")
			respHeader = http.Header{"Sec-WebSocket-Protocol": []string{strings.TrimSpace(parts[0])}}
		}
		conn, err := srv.upgrader.Upgrade(w, r, respHeader)
		if err != nil {
			return
		}
		srv.store.RegisterWS(conn)
		for _, ev := range events {
			if msg, err := json.Marshal(ev); err == nil {
				_ = conn.WriteMessage(websocket.TextMessage, msg)
			}
		}
		go func() {
			defer srv.store.UnregisterWS(conn)
			for {
				if _, _, err := conn.ReadMessage(); err != nil {
					return
				}
			}
		}()
		return
	}

	writeData(w, http.StatusOK, map[string]any{
		"events": events,
		"cursor": cursor,
	})
}

func (srv *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	userObj := map[string]any{
		"userId":                ac.user.UserID,
		"username":              ac.user.Username,
		"roles":                 ac.user.Roles,
		"activeRole":            ac.session.ActiveRole,
		"roleSelectionRequired": ac.session.RoleSelectionRequired,
	}
	if ac.user.FullName != "" {
		userObj["fullName"] = ac.user.FullName
	}

	resp := map[string]any{
		"user":       userObj,
		"serverTime": time.Now().UTC().Format(time.RFC3339),
	}

	if !ac.session.RoleSelectionRequired && ac.role != "" {
		if ac.role == "requester" {
			var reqSamples []map[string]any
			for _, smp := range srv.store.state.Samples {
				if smp.RequesterID == ac.user.UserID {
					srv.refreshSampleStaleLocked(smp)
					reqSamples = append(reqSamples, map[string]any{
						"sampleId":           smp.SampleID,
						"requestId":          smp.RequestID,
						"status":             smp.Status,
						"serviceability":     smp.Serviceability,
						"origin":             smp.Origin,
						"originType":         smp.OriginType,
						"deliveryDeadline":   smp.DeliveryDeadline,
						"activeJourneyId":    smp.ActiveJourneyID,
						"targetLaboratoryId": smp.TargetLaboratoryID,
						"currentHolderId":    smp.CurrentHolderID,
						"latestLocation":     smp.LatestLocation,
						"locationRecordedAt": smp.LocationRecordedAt,
						"locationStale":      smp.LocationStale,
						"timeline":           smp.Timeline,
					})
				}
			}
			if reqSamples == nil {
				reqSamples = []map[string]any{}
			}
			resp["requesterSamples"] = reqSamples
		}
		if ac.role == "administrator" || ac.role == "dispatcher" {
			ops := srv.buildOperationsStateLocked("")
			resp["operations"] = ops
		}
	}

	writeData(w, http.StatusOK, resp)
}
