package internal

import (
	"math"
	"net/http"
	"strings"
	"time"
)

func (srv *Server) handleAuthenticateUser(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read request body")
		return
	}
	var req struct {
		Username *string `json:"username"`
		Password *string `json:"password"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Username == nil || req.Password == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	username := strings.TrimSpace(*req.Username)
	password := *req.Password

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	var matched *User
	for _, u := range srv.store.state.Users {
		if u.Username == username {
			matched = u
			break
		}
	}
	if matched == nil || !matched.Active || matched.PasswordHash != HashPassword(password) {
		actor := "anonymous"
		if matched != nil {
			actor = matched.UserID
		}
		srv.store.recordAuditLocked(actor, "unauthenticated", "authenticate_user", "user", username, false, map[string]any{"username": username})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
		return
	}

	activeRole := ""
	roleSelReq := true
	if len(matched.Roles) == 1 {
		activeRole = matched.Roles[0]
		roleSelReq = false
	}

	tok := NewUUID() + "-" + NewUUID()
	sess := &Session{
		Token:                 tok,
		UserID:                matched.UserID,
		ActiveRole:            activeRole,
		RoleSelectionRequired: roleSelReq,
		CreatedAt:             time.Now().UTC().Format(time.RFC3339),
	}
	srv.store.state.Sessions[tok] = sess
	srv.store.recordAuditLocked(matched.UserID, activeRole, "authenticate_user", "user", matched.UserID, true, map[string]any{"username": matched.Username, "activeRole": activeRole})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusOK, map[string]any{
		"sessionToken": tok,
		"userId":       matched.UserID,
		"roles":        matched.Roles,
		"activeRole":   activeRole,
	})
}

func (srv *Server) handleSelectActiveRole(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Role *string `json:"role"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Role == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}
	role := strings.TrimSpace(*req.Role)

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		srv.store.recordAuditLocked("anonymous", "unauthenticated", "select_active_role", "user", "unknown", false, nil)
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if !isValidRole(role) {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "select_active_role", "user", ac.user.UserID, false, map[string]any{"role": role})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_role", "invalid role specified")
		return
	}

	held := false
	for _, rName := range ac.user.Roles {
		if rName == role {
			held = true
			break
		}
	}
	if !held {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "select_active_role", "user", ac.user.UserID, false, map[string]any{"requestedRole": role, "error": "role_not_held"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "role_not_held", "user does not hold the requested role")
		return
	}

	ac.session.ActiveRole = role
	ac.session.RoleSelectionRequired = false
	srv.store.recordAuditLocked(ac.user.UserID, role, "select_active_role", "user", ac.user.UserID, true, map[string]any{"activeRole": role})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusOK, map[string]any{
		"activeRole": role,
		"roles":      ac.user.Roles,
	})
}

func (srv *Server) offerPendingAssignmentsLocked(actorID, role string) {
	now := time.Now().UTC()
	for _, a := range srv.store.state.Assignments {
		if a.Status == "pending" && a.OfferedToWorkerID == "" {
			w := srv.store.offerAssignmentLocked(a, now, actorID, role)
			if w != nil {
				if jp := srv.store.state.Journeys[a.JourneyID]; jp != nil {
					srv.store.syncJourneyAssignmentsLocked(jp)
				}
				if smp := srv.store.state.Samples[a.SampleID]; smp != nil && smp.Status == "exception" {
					if code, _ := smp.Exception["code"].(string); code == "no_qualified_worker" {
						smp.Status = "scheduled"
						smp.Exception = nil
					}
				}
			}
		}
	}
}

func (srv *Server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Username           *string         `json:"username"`
		InitialPassword    *string         `json:"initialPassword"`
		Email              string          `json:"email"`
		FullName           string          `json:"fullName"`
		Phone              string          `json:"phone"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             *bool           `json:"active"`
		AssignedLocationID string          `json:"assignedLocationId"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Username == nil || req.InitialPassword == nil || req.Roles == nil || req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "create_user", "user", "", true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	username := strings.TrimSpace(*req.Username)
	if username == "" || *req.InitialPassword == "" || len(req.Roles) == 0 {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_user", "user", username, false, map[string]any{"error": "invalid_user"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusBadRequest, "invalid_user", "username, initialPassword, and at least one role are required")
		return
	}
	for _, rName := range req.Roles {
		if !isValidRole(rName) {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_user", "user", username, false, map[string]any{"error": "invalid_user"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusBadRequest, "invalid_user", "invalid role in roles")
			return
		}
	}
	if req.AssignedLocationID != "" && !isValidUUID(req.AssignedLocationID) {
		writeError(w, http.StatusBadRequest, "invalid_user", "invalid assignedLocationId")
		return
	}
	for _, cert := range req.Certifications {
		if strings.TrimSpace(cert.Code) == "" {
			writeError(w, http.StatusBadRequest, "invalid_certification", "certification code cannot be empty")
			return
		}
		if cert.ExpiresAt != "" {
			if _, ok := parseTimeRFC3339(cert.ExpiresAt); !ok {
				writeError(w, http.StatusBadRequest, "invalid_certification", "invalid certification expiresAt")
				return
			}
		}
	}

	for _, existing := range srv.store.state.Users {
		if existing.Username == username {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_user", "user", username, false, map[string]any{"error": "username_exists"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusConflict, "username_exists", "username already exists")
			return
		}
	}

	quals := req.Qualifications
	if quals == nil {
		quals = []string{}
	}
	certs := req.Certifications
	if certs == nil {
		certs = []Certification{}
	}

	uid := NewUUID()
	newUser := &User{
		UserID:             uid,
		Username:           username,
		PasswordHash:       HashPassword(*req.InitialPassword),
		Email:              req.Email,
		FullName:           req.FullName,
		Phone:              req.Phone,
		Roles:              req.Roles,
		Qualifications:     quals,
		Certifications:     certs,
		Active:             *req.Active,
		AssignedLocationID: req.AssignedLocationID,
		Available:          *req.Active,
		CapacityUnits:      DefaultWorkerCap,
		LastLocationSeq:    make(map[string]int),
	}
	srv.store.state.Users[uid] = newUser
	srv.offerPendingAssignmentsLocked(ac.user.UserID, ac.role)

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_user", "user", uid, true, map[string]any{
		"username": username,
		"roles":    req.Roles,
		"active":   *req.Active,
	})
	_ = srv.store.saveLocked(r.Context())

	respData := map[string]any{
		"userId":         uid,
		"username":       username,
		"roles":          newUser.Roles,
		"qualifications": newUser.Qualifications,
		"certifications": newUser.Certifications,
		"active":         newUser.Active,
	}
	if newUser.Email != "" {
		respData["email"] = newUser.Email
	}
	if newUser.FullName != "" {
		respData["fullName"] = newUser.FullName
	}
	if newUser.Phone != "" {
		respData["phone"] = newUser.Phone
	}
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		UserID             *string         `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             *bool           `json:"active"`
		AssignedLocationID *string         `json:"assignedLocationId"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.UserID == nil || req.Roles == nil || req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "update_user_access", "user", *req.UserID, true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if !isValidUUID(*req.UserID) || len(req.Roles) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid userId or empty roles")
		return
	}
	for _, rName := range req.Roles {
		if !isValidRole(rName) {
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid role")
			return
		}
	}
	for _, cert := range req.Certifications {
		if strings.TrimSpace(cert.Code) == "" {
			writeError(w, http.StatusBadRequest, "invalid_certification", "empty certification code")
			return
		}
		if cert.ExpiresAt != "" {
			if _, ok := parseTimeRFC3339(cert.ExpiresAt); !ok {
				writeError(w, http.StatusBadRequest, "invalid_certification", "invalid certification expiresAt")
				return
			}
		}
	}

	u, ok := srv.store.state.Users[*req.UserID]
	if !ok || u == nil {
		writeError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}

	u.Roles = req.Roles
	if req.Qualifications != nil {
		u.Qualifications = req.Qualifications
	}
	if req.Certifications != nil {
		u.Certifications = req.Certifications
	}
	u.Active = *req.Active
	if !u.Active {
		u.Available = false
	}
	if req.AssignedLocationID != nil {
		u.AssignedLocationID = *req.AssignedLocationID
	}

	srv.offerPendingAssignmentsLocked(ac.user.UserID, ac.role)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "update_user_access", "user", u.UserID, true, map[string]any{
		"roles":  u.Roles,
		"active": u.Active,
	})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusCreated, map[string]any{
		"userId":         u.UserID,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": u.Certifications,
		"active":         u.Active,
	})
}

func (srv *Server) handleReadUser(w http.ResponseWriter, r *http.Request, targetUserID string) {
	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if ac.role != "administrator" && ac.role != "dispatcher" && ac.user.UserID != targetUserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_user", "user", targetUserID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "not permitted to read this user")
		return
	}

	u, ok := srv.store.state.Users[targetUserID]
	if !ok || u == nil {
		writeError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}

	respData := map[string]any{
		"userId":         u.UserID,
		"username":       u.Username,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": u.Certifications,
		"active":         u.Active,
	}
	if u.Email != "" {
		respData["email"] = u.Email
	}
	if u.FullName != "" {
		respData["fullName"] = u.FullName
	}
	if u.Phone != "" {
		respData["phone"] = u.Phone
	}
	writeData(w, http.StatusOK, respData)
}

func (srv *Server) handleCreateSampleType(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Name                       *string  `json:"name"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      *string  `json:"requiredQualification"`
		ContainerType              *string  `json:"containerType"`
		TemperatureMinC            *float64 `json:"temperatureMinC"`
		TemperatureMaxC            *float64 `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Name == nil || req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "create_sample_type", "sample_type", "", true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	name := strings.TrimSpace(*req.Name)
	container := strings.TrimSpace(*req.ContainerType)
	minC := *req.TemperatureMinC
	maxC := *req.TemperatureMaxC

	if name == "" || container == "" || math.IsNaN(minC) || math.IsNaN(maxC) || minC >= maxC {
		writeError(w, http.StatusBadRequest, "invalid_handling_rule", "invalid sample type name, container, or temperature range")
		return
	}
	for _, incID := range req.IncompatibleSampleTypes {
		if !isValidUUID(incID) {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "invalid incompatibleSampleTypes UUID")
			return
		}
	}

	isNamed4 := strings.EqualFold(name, "Amber") || strings.EqualFold(name, "Indigo") || strings.EqualFold(name, "Frost") || strings.EqualFold(name, "Pulse")
	qualReq := isNamed4
	if req.QualifiedCollectorRequired != nil {
		qualReq = *req.QualifiedCollectorRequired
	}
	reqQual := ""
	if req.RequiredQualification != nil {
		reqQual = strings.TrimSpace(*req.RequiredQualification)
		if qualReq && reqQual == "" {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "requiredQualification cannot be empty when qualifiedCollectorRequired is true")
			return
		}
	} else if qualReq {
		if isNamed4 {
			reqQual = name
		} else {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "requiredQualification is required when qualifiedCollectorRequired is true")
			return
		}
	}

	cooled := strings.EqualFold(name, "Frost")
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute || strings.EqualFold(name, "Frost")
	}
	batchAllowed := !strings.EqualFold(name, "Pulse")
	if req.BatchingAllowed != nil {
		batchAllowed = *req.BatchingAllowed && !strings.EqualFold(name, "Pulse")
	}

	incomp := req.IncompatibleSampleTypes
	if incomp == nil {
		incomp = []string{}
	}
	if strings.EqualFold(name, "Indigo") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Amber") {
				incomp = append(incomp, other.SampleTypeID)
			}
		}
	} else if strings.EqualFold(name, "Amber") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Indigo") {
				incomp = append(incomp, other.SampleTypeID)
			}
		}
	}
	incomp = sortStringsUnique(incomp)
	if incomp == nil {
		incomp = []string{}
	}

	stID := NewUUID()
	st := &SampleType{
		SampleTypeID:               stID,
		Name:                       name,
		QualifiedCollectorRequired: qualReq,
		RequiredQualification:      reqQual,
		ContainerType:              container,
		TemperatureMinC:            minC,
		TemperatureMaxC:            maxC,
		IncompatibleSampleTypes:    incomp,
		RequiresCooledRoute:        cooled,
		BatchingAllowed:            batchAllowed,
	}
	srv.store.state.SampleTypes[stID] = st
	// Maintain symmetry for Amber/Indigo
	if strings.EqualFold(name, "Indigo") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Amber") {
				other.IncompatibleSampleTypes = sortStringsUnique(append(other.IncompatibleSampleTypes, stID))
			}
		}
	} else if strings.EqualFold(name, "Amber") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Indigo") {
				other.IncompatibleSampleTypes = sortStringsUnique(append(other.IncompatibleSampleTypes, stID))
			}
		}
	}

	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_sample_type", "sample_type", stID, true, map[string]any{"name": name})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusCreated, st)
}

func (srv *Server) handleUpdateSampleType(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleTypeID               *string  `json:"sampleTypeId"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      *string  `json:"requiredQualification"`
		ContainerType              *string  `json:"containerType"`
		TemperatureMinC            *float64 `json:"temperatureMinC"`
		TemperatureMaxC            *float64 `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleTypeID == nil || req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "update_sample_type", "sample_type", *req.SampleTypeID, true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	st, ok := srv.store.state.SampleTypes[*req.SampleTypeID]
	if !ok || st == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample type not found")
		return
	}

	container := strings.TrimSpace(*req.ContainerType)
	minC := *req.TemperatureMinC
	maxC := *req.TemperatureMaxC
	if container == "" || math.IsNaN(minC) || math.IsNaN(maxC) || minC >= maxC {
		writeError(w, http.StatusBadRequest, "invalid_handling_rule", "invalid container or temperature range")
		return
	}
	for _, incID := range req.IncompatibleSampleTypes {
		if !isValidUUID(incID) || incID == st.SampleTypeID {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "invalid incompatibleSampleTypes")
			return
		}
	}

	if req.QualifiedCollectorRequired != nil {
		st.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
	}
	if req.RequiredQualification != nil {
		st.RequiredQualification = strings.TrimSpace(*req.RequiredQualification)
	}
	if st.QualifiedCollectorRequired && st.RequiredQualification == "" {
		writeError(w, http.StatusBadRequest, "invalid_handling_rule", "requiredQualification required")
		return
	}

	st.ContainerType = container
	st.TemperatureMinC = minC
	st.TemperatureMaxC = maxC
	if req.IncompatibleSampleTypes != nil {
		st.IncompatibleSampleTypes = req.IncompatibleSampleTypes
	}
	if req.RequiresCooledRoute != nil {
		st.RequiresCooledRoute = *req.RequiresCooledRoute
	}
	if req.BatchingAllowed != nil {
		st.BatchingAllowed = *req.BatchingAllowed
	}

	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "update_sample_type", "sample_type", st.SampleTypeID, true, map[string]any{"name": st.Name})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusCreated, st)
}

func (srv *Server) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Name            *string     `json:"name"`
		Coordinate      *Coordinate `json:"coordinate"`
		CoverageKm      *float64    `json:"coverageKm"`
		HandlingMinutes *int        `json:"handlingMinutes"`
		Active          *bool       `json:"active"`
		Functions       []string    `json:"functions"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Name == nil || req.Coordinate == nil || req.Active == nil || req.Functions == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "create_location", "location", "", true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeError(w, http.StatusBadRequest, "invalid_coordinate", "coordinate out of bounds")
		return
	}
	covKm := 5.0
	if req.CoverageKm != nil {
		covKm = *req.CoverageKm
	}
	if covKm <= 0 || covKm > 5.0 {
		writeError(w, http.StatusBadRequest, "invalid_node_coverage", "coverageKm must be in (0, 5]")
		return
	}
	handlingMins := 0
	if req.HandlingMinutes != nil {
		handlingMins = *req.HandlingMinutes
	}
	if handlingMins < 0 || handlingMins > 1440 {
		writeError(w, http.StatusBadRequest, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
		return
	}
	if strings.TrimSpace(*req.Name) == "" || len(req.Functions) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_location_function", "name and at least one location function required")
		return
	}
	fnStates := LocationFunctionStates{}
	for _, fn := range req.Functions {
		if !isValidLocationFunction(fn) {
			writeError(w, http.StatusBadRequest, "invalid_location_function", "invalid location function")
			return
		}
		switch fn {
		case "collection_point":
			fnStates.CollectionPoint = true
		case "transfer_point":
			fnStates.TransferPoint = true
		case "hub":
			fnStates.Hub = true
		case "laboratory":
			fnStates.Laboratory = true
		}
	}

	locID := NewUUID()
	loc := &Location{
		LocationID:      locID,
		Name:            strings.TrimSpace(*req.Name),
		Coordinate:      *req.Coordinate,
		CoverageKm:      covKm,
		HandlingMinutes: handlingMins,
		Active:          *req.Active,
		Functions:       fnStates,
		Capacity: Capacity{
			CapacityUnits:        DefaultNodeCapacity,
			AvailableUnits:       DefaultNodeCapacity,
			CooledCapacityUnits:  DefaultNodeCapacity,
			CooledAvailableUnits: DefaultNodeCapacity,
		},
	}
	srv.store.state.Locations[locID] = loc
	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_location", "location", locID, true, map[string]any{"name": loc.Name})
	srv.store.publishRealtimeLocked("location.created", "location", locID, map[string]any{"locationId": locID, "name": loc.Name})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusCreated, loc)
}

