func (srv *Server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		FromLocationID *string  `json:"fromLocationId"`
		ToLocationID   *string  `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.FromLocationID == nil || req.ToLocationID == nil || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "create_connection", "connection", "", true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	fromID := strings.TrimSpace(*req.FromLocationID)
	toID := strings.TrimSpace(*req.ToLocationID)
	if !isValidUUID(fromID) || !isValidUUID(toID) || fromID == toID || *req.TravelMinutes < 1 || *req.CostUnits < 0 {
		writeError(w, http.StatusBadRequest, "invalid_connection", "invalid connection parameters")
		return
	}
	if srv.store.state.Locations[fromID] == nil || srv.store.state.Locations[toID] == nil {
		writeError(w, http.StatusBadRequest, "invalid_connection", "fromLocationId or toLocationId does not exist")
		return
	}

	cooled := false
	if req.Cooled != nil {
		cooled = *req.Cooled
	}
	cooledCap := 0
	if cooled {
		cooledCap = DefaultConnCapacity
	}

	connID := NewUUID()
	conn := &Connection{
		ConnectionID:   connID,
		FromLocationID: fromID,
		ToLocationID:   toID,
		TravelMinutes:  *req.TravelMinutes,
		CostUnits:      *req.CostUnits,
		Cooled:         cooled,
		Active:         *req.Active,
		Capacity: Capacity{
			CapacityUnits:        DefaultConnCapacity,
			AvailableUnits:       DefaultConnCapacity,
			CooledCapacityUnits:  cooledCap,
			CooledAvailableUnits: cooledCap,
		},
	}
	srv.store.state.Connections[connID] = conn
	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_connection", "connection", connID, true, map[string]any{
		"fromLocationId": fromID,
		"toLocationId":   toID,
	})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusCreated, conn)
}

