func (srv *Server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		UserID             *string         `json:"userId"`
		Roles              []string        `json:"roles"`
		Qualifications     []string        `json:"qualifications"`
		Certifications     []Certification `json:"certifications"`
		Active             *bool           `json:"active"`
		AssignedLocationID *string         `json:"assignedLocationId"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.UserID == nil || req.Roles == nil || req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "update_user_access", "user", *req.UserID, true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if !isValidUUID(*req.UserID) || len(req.Roles) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid userId or empty roles")
		return
	}
	for _, rName := range req.Roles {
		if !isValidRole(rName) {
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid role")
			return
		}
	}
	for _, cert := range req.Certifications {
		if strings.TrimSpace(cert.Code) == "" {
			writeError(w, http.StatusBadRequest, "invalid_certification", "empty certification code")
			return
		}
		if cert.ExpiresAt != "" {
			if _, ok := parseTimeRFC3339(cert.ExpiresAt); !ok {
				writeError(w, http.StatusBadRequest, "invalid_certification", "invalid certification expiresAt")
				return
			}
		}
	}

	u, ok := srv.store.state.Users[*req.UserID]
	if !ok || u == nil {
		writeError(w, http.StatusNotFound, "not_found", "user not found")
		return
	}

	u.Roles = req.Roles
	if req.Qualifications != nil {
		u.Qualifications = req.Qualifications
	}
	if req.Certifications != nil {
		u.Certifications = req.Certifications
	}
	u.Active = *req.Active
	if !u.Active {
		u.Available = false
	}
	if req.AssignedLocationID != nil {
