			return
		}
		loc.CapacityConfigured = true
		loc.Capacity.CapacityUnits = capUnits
		loc.Capacity.CooledCapacityUnits = cooledUnits
		srv.store.recomputeServiceabilityLocked(true)
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "configure_capacity", "location", resID, true, map[string]any{
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		_ = srv.store.saveLocked(r.Context())
		writeData(w, http.StatusOK, map[string]any{
			"resourceId":          resID,
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		return
	}

	if conn, ok := srv.store.state.Connections[resID]; ok && conn != nil {
		if ac.role != "administrator" {
			writeError(w, http.StatusForbidden, "forbidden", "only administrator can configure connection capacity")
			return
		}
		if capUnits < conn.Capacity.ReservedUnits || cooledUnits < conn.Capacity.CooledReservedUnits {
			writeError(w, http.StatusConflict, "capacity_reserved", "cannot reduce capacity below currently reserved units")
			return
		}
		conn.CapacityConfigured = true
		conn.Capacity.CapacityUnits = capUnits
		conn.Capacity.CooledCapacityUnits = cooledUnits
		srv.store.recomputeServiceabilityLocked(true)
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "configure_capacity", "connection", resID, true, map[string]any{
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		_ = srv.store.saveLocked(r.Context())
		writeData(w, http.StatusOK, map[string]any{
			"resourceId":          resID,
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		return
	}

	writeError(w, http.StatusBadRequest, "invalid_capacity", "resource not found")
}

