		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "set_worker_availability", "worker", *req.WorkerID, true)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if ac.role != "administrator" && ac.role != "dispatcher" && ac.user.UserID != *req.WorkerID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "set_worker_availability", "worker", *req.WorkerID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "not permitted to update worker availability")
		return
	}

	if *req.CapacityUnits < 0 {
		writeError(w, http.StatusBadRequest, "invalid_capacity", "capacityUnits must be >= 0")
		return
	}

	u, ok := srv.store.state.Users[*req.WorkerID]
	if !ok || u == nil {
		writeError(w, http.StatusNotFound, "not_found", "worker not found")
		return
	}

	if *req.CapacityUnits < u.ReservedUnits {
		writeError(w, http.StatusConflict, "capacity_reserved", "cannot reduce worker capacity below active reserved assignments")
		return
	}

	u.AvailabilityConfigured = true
	u.Available = *req.Available && u.Active
	u.CapacityUnits = *req.CapacityUnits

	if u.Available && u.CapacityUnits > u.ReservedUnits {
		srv.offerPendingAssignmentsLocked(ac.user.UserID, ac.role)
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "set_worker_availability", "worker", u.UserID, true, map[string]any{
		"available":     u.Available,
		"capacityUnits": u.CapacityUnits,
	})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusOK, map[string]any{
		"workerId":      u.UserID,
		"available":     u.Available,
		"capacityUnits": u.CapacityUnits,
	})
}
