		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Name == nil || req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "create_sample_type", "sample_type", "", true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	name := strings.TrimSpace(*req.Name)
	container := strings.TrimSpace(*req.ContainerType)
	minC := *req.TemperatureMinC
	maxC := *req.TemperatureMaxC

	if name == "" || container == "" || math.IsNaN(minC) || math.IsNaN(maxC) || minC >= maxC {
		writeError(w, http.StatusBadRequest, "invalid_handling_rule", "invalid sample type name, container, or temperature range")
		return
	}
	for _, incID := range req.IncompatibleSampleTypes {
		if !isValidUUID(incID) {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "invalid incompatibleSampleTypes UUID")
			return
		}
	}

	isNamed4 := strings.EqualFold(name, "Amber") || strings.EqualFold(name, "Indigo") || strings.EqualFold(name, "Frost") || strings.EqualFold(name, "Pulse")
	qualReq := isNamed4
	if req.QualifiedCollectorRequired != nil {
		qualReq = *req.QualifiedCollectorRequired
	}
	reqQual := ""
	if req.RequiredQualification != nil {
		reqQual = strings.TrimSpace(*req.RequiredQualification)
		if qualReq && reqQual == "" {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "requiredQualification cannot be empty when qualifiedCollectorRequired is true")
			return
		}
	} else if qualReq {
		if isNamed4 {
			reqQual = name
		} else {
			writeError(w, http.StatusBadRequest, "invalid_handling_rule", "requiredQualification is required when qualifiedCollectorRequired is true")
			return
		}
	}

	cooled := strings.EqualFold(name, "Frost")
	if req.RequiresCooledRoute != nil {
		cooled = *req.RequiresCooledRoute || strings.EqualFold(name, "Frost")
	}
	batchAllowed := !strings.EqualFold(name, "Pulse")
	if req.BatchingAllowed != nil {
		batchAllowed = *req.BatchingAllowed && !strings.EqualFold(name, "Pulse")
	}

	incomp := req.IncompatibleSampleTypes
	if incomp == nil {
		incomp = []string{}
	}
	if strings.EqualFold(name, "Indigo") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Amber") {
				incomp = append(incomp, other.SampleTypeID)
			}
		}
	} else if strings.EqualFold(name, "Amber") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Indigo") {
				incomp = append(incomp, other.SampleTypeID)
			}
		}
	}
	incomp = sortStringsUnique(incomp)
	if incomp == nil {
		incomp = []string{}
	}

	stID := NewUUID()
	st := &SampleType{
		SampleTypeID:               stID,
		Name:                       name,
		QualifiedCollectorRequired: qualReq,
		RequiredQualification:      reqQual,
		ContainerType:              container,
		TemperatureMinC:            minC,
		TemperatureMaxC:            maxC,
		IncompatibleSampleTypes:    incomp,
		RequiresCooledRoute:        cooled,
		BatchingAllowed:            batchAllowed,
	}
	srv.store.state.SampleTypes[stID] = st
	// Maintain symmetry for Amber/Indigo
	if strings.EqualFold(name, "Indigo") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Amber") {
				other.IncompatibleSampleTypes = sortStringsUnique(append(other.IncompatibleSampleTypes, stID))
			}
		}
	} else if strings.EqualFold(name, "Amber") {
		for _, other := range srv.store.state.SampleTypes {
			if strings.EqualFold(other.Name, "Indigo") {
				other.IncompatibleSampleTypes = sortStringsUnique(append(other.IncompatibleSampleTypes, stID))
			}
		}
	}

	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "create_sample_type", "sample_type", stID, true, map[string]any{"name": name})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusCreated, st)
}

