		return
	}

	st.ContainerType = container
	st.TemperatureMinC = minC
	st.TemperatureMaxC = maxC
	if req.IncompatibleSampleTypes != nil {
		st.IncompatibleSampleTypes = req.IncompatibleSampleTypes
	}
