		cooledUnits = *req.CooledCapacityUnits
	}
	if !isValidUUID(resID) || capUnits < 0 || cooledUnits < 0 {
		writeError(w, http.StatusBadRequest, "invalid_capacity", "invalid capacity values")
		return
	}

	if ac.role == "node_handler" || ac.role == "laboratory_team" {
		if ac.user.AssignedLocationID != resID {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "configure_capacity", "capacity", resID, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "worker can only configure capacity for their assigned location")
			return
		}
	}

	if loc, ok := srv.store.state.Locations[resID]; ok && loc != nil {
		if capUnits < loc.Capacity.ReservedUnits || cooledUnits < loc.Capacity.CooledReservedUnits {
			writeError(w, http.StatusConflict, "capacity_reserved", "cannot reduce capacity below currently reserved units")
			return
		}
		loc.CapacityConfigured = true
		loc.Capacity.CapacityUnits = capUnits
		loc.Capacity.CooledCapacityUnits = cooledUnits
		srv.store.recomputeServiceabilityLocked(true)
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "configure_capacity", "location", resID, true, map[string]any{
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		_ = srv.store.saveLocked(r.Context())
		writeData(w, http.StatusOK, map[string]any{
			"resourceId":          resID,
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		return
	}

	if conn, ok := srv.store.state.Connections[resID]; ok && conn != nil {
		if ac.role != "administrator" {
			writeError(w, http.StatusForbidden, "forbidden", "only administrator can configure connection capacity")
			return
		}
		if capUnits < conn.Capacity.ReservedUnits || cooledUnits < conn.Capacity.CooledReservedUnits {
			writeError(w, http.StatusConflict, "capacity_reserved", "cannot reduce capacity below currently reserved units")
			return
		}
		conn.CapacityConfigured = true
		conn.Capacity.CapacityUnits = capUnits
		conn.Capacity.CooledCapacityUnits = cooledUnits
		srv.store.recomputeServiceabilityLocked(true)
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "configure_capacity", "connection", resID, true, map[string]any{
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		_ = srv.store.saveLocked(r.Context())
		writeData(w, http.StatusOK, map[string]any{
			"resourceId":          resID,
			"capacityUnits":       capUnits,
			"cooledCapacityUnits": cooledUnits,
		})
		return
	}

	writeError(w, http.StatusBadRequest, "invalid_capacity", "resource not found")
}

func (srv *Server) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		LaboratoryID *string `json:"laboratoryId"`
		SampleTypeID *string `json:"sampleTypeId"`
		Accepts      *bool   `json:"accepts"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.LaboratoryID == nil || req.SampleTypeID == nil || req.Accepts == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "configure_laboratory_acceptance", "laboratory", *req.LaboratoryID, true, "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	labID := strings.TrimSpace(*req.LaboratoryID)
	stID := strings.TrimSpace(*req.SampleTypeID)
	loc := srv.store.state.Locations[labID]
	st := srv.store.state.SampleTypes[stID]
	if loc == nil || st == nil || !loc.Functions.Laboratory {
		writeError(w, http.StatusBadRequest, "invalid_acceptance", "invalid laboratoryId or sampleTypeId")
		return
	}

	if srv.store.state.LabAcceptances[labID] == nil {
		srv.store.state.LabAcceptances[labID] = make(map[string]string)
	}
	accID := srv.store.state.LabAcceptances[labID][stID]
	if accID == "" {
		accID = NewUUID()
	}
	if *req.Accepts {
		srv.store.state.LabAcceptances[labID][stID] = accID
	} else {
		delete(srv.store.state.LabAcceptances[labID], stID)
	}

	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "configure_laboratory_acceptance", "laboratory", labID, true, map[string]any{
		"sampleTypeId": stID,
		"accepts":      *req.Accepts,
	})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusOK, map[string]any{
		"acceptanceId": accID,
		"accepts":      *req.Accepts,
	})
}

func (srv *Server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		WorkerID      *string `json:"workerId"`
		Available     *bool   `json:"available"`
		CapacityUnits *int    `json:"capacityUnits"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.WorkerID == nil || req.Available == nil || req.CapacityUnits == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "set_worker_availability", "worker", *req.WorkerID, true)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if ac.role != "administrator" && ac.role != "dispatcher" && ac.user.UserID != *req.WorkerID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "set_worker_availability", "worker", *req.WorkerID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "not permitted to update worker availability")
		return
	}

	if *req.CapacityUnits < 0 {
		writeError(w, http.StatusBadRequest, "invalid_capacity", "capacityUnits must be >= 0")
		return
	}

	u, ok := srv.store.state.Users[*req.WorkerID]
	if !ok || u == nil {
		writeError(w, http.StatusNotFound, "not_found", "worker not found")
		return
	}

	if *req.CapacityUnits < u.ReservedUnits {
		writeError(w, http.StatusConflict, "capacity_reserved", "cannot reduce worker capacity below active reserved assignments")
		return
	}

	u.AvailabilityConfigured = true
	u.Available = *req.Available && u.Active
	u.CapacityUnits = *req.CapacityUnits

	if u.Available && u.CapacityUnits > u.ReservedUnits {
		srv.offerPendingAssignmentsLocked(ac.user.UserID, ac.role)
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "set_worker_availability", "worker", u.UserID, true, map[string]any{
		"available":     u.Available,
		"capacityUnits": u.CapacityUnits,
	})
	_ = srv.store.saveLocked(r.Context())

	writeData(w, http.StatusOK, map[string]any{
		"workerId":      u.UserID,
		"available":     u.Available,
		"capacityUnits": u.CapacityUnits,
	})
}

