				"receiverConfirmed": ho.ReceiverConfirmed,
				"status":            ho.Status,
			}
		}
	}
	writeData(w, http.StatusOK, lc)
}

func (srv *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	if len(strings.TrimSpace(string(raw))) > 0 {
		if err := decodeStrictJSON(raw, &req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
			return
		}
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	srv.store.expireStaleOffersLocked(time.Now().UTC())

	ac, authErr := srv.requireRoleLocked(r, "list_role_work", "work", "", true)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	role := ac.role
	if req.Role != nil && *req.Role != "" {
		rReq := strings.TrimSpace(*req.Role)
		if !isValidRole(rReq) {
			writeError(w, http.StatusBadRequest, "invalid_role", "invalid role")
			return
		}
		if rReq != ac.role {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "list_role_work", "work", rReq, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "cannot list work for a role other than activeRole")
			return
		}
		role = rReq
	}

	rw := RoleWork{
		Pending:    []any{},
		InProgress: []any{},
		Completed:  []any{},
	}

	switch role {
	case "requester":
		ids := make([]string, 0, len(srv.store.state.Samples))
		for id := range srv.store.state.Samples {
			ids = append(ids, id)
		}
		sort.Strings(ids)
		for _, id := range ids {
			smp := srv.store.state.Samples[id]
			if smp.RequesterID != ac.user.UserID {
				continue
			}
			srv.refreshSampleStaleLocked(smp)
			item := SampleWorkItem{
				Kind:                 "sample",
				SampleID:             smp.SampleID,
				SampleIDSnake:        smp.SampleID,
				RequestID:            smp.RequestID,
				Status:               smp.Status,
				Serviceability:       smp.Serviceability,
				RequestedAt:          smp.RequestedAt,
				DeliveryDeadline:     smp.DeliveryDeadline,
				EarliestCollectionAt: smp.EarliestCollectionAt,
				LatestCollectionAt:   smp.LatestCollectionAt,
				JourneyID:            smp.ActiveJourneyID,
				ActiveJourneyID:      smp.ActiveJourneyID,
				LaboratoryID:         smp.TargetLaboratoryID,
				CurrentHolderID:      smp.CurrentHolderID,
				RequesterID:          smp.RequesterID,
				History:              smp.Timeline,
				LocationRecordedAt:   smp.LocationRecordedAt,
				LocationStale:        smp.LocationStale,
			}
			if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
				rw.Completed = append(rw.Completed, item)
			} else if smp.Sealed || smp.Status == "in_transit" {
				rw.InProgress = append(rw.InProgress, item)
			} else {
				rw.Pending = append(rw.Pending, item)
			}
		}

	case "dispatcher", "administrator":
		jIDs := make([]string, 0, len(srv.store.state.Journeys))
		for id := range srv.store.state.Journeys {
			jIDs = append(jIDs, id)
		}
		sort.Strings(jIDs)
		for _, id := range jIDs {
			jp := srv.store.state.Journeys[id]
			assignCount := len(jp.Legs) + len(jp.CollectionAssignmentIDs) + len(jp.NodeAssignmentIDs) + len(jp.LaboratoryAssignmentIDs)
			item := JourneyWorkItem{
				Kind:                "journey",
				JourneyID:           jp.JourneyID,
				JourneyIDSnake:      jp.JourneyID,
				Status:              jp.Status,
				RouteMode:           jp.RouteMode,
				PlanVersion:         jp.PlanVersion,
				SampleIDs:           jp.SampleIDs,
				EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
				AssignmentCount:     assignCount,
				History:             jp.History,
			}
			if jp.Status == "completed" || jp.Status == "cancelled" || jp.Status == "replaced" {
				rw.Completed = append(rw.Completed, item)
			} else if jp.Status == "in_progress" {
				rw.InProgress = append(rw.InProgress, item)
			} else {
				rw.Pending = append(rw.Pending, item)
			}
		}

	default:
		wantKind := ""
		switch role {
		case "collection_professional":
			wantKind = "collection"
		case "delivery_partner":
			wantKind = "transport"
		case "node_handler":
			wantKind = "node"
		case "laboratory_team":
			wantKind = "laboratory"
		}
		aIDs := make([]string, 0, len(srv.store.state.Assignments))
		for id := range srv.store.state.Assignments {
			aIDs = append(aIDs, id)
		}
		sort.Strings(aIDs)
		for _, id := range aIDs {
			a := srv.store.state.Assignments[id]
			if a.Kind != wantKind {
				continue
			}
			isMine := a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID
			if !isMine {
				for _, h := range a.History {
					if h.ActorID == ac.user.UserID {
						isMine = true
						break
					}
				}
			}
			if !isMine {
				continue
			}
			var destCap *Capacity
			if a.ToLocationID != "" {
				if loc := srv.store.state.Locations[a.ToLocationID]; loc != nil {
					c := srv.store.getLocationCapacityLocked(loc)
					destCap = &c
				}
			}
			item := AssignmentWorkItem{
				Kind:                   a.Kind,
				AssignmentID:           a.AssignmentID,
				AssignmentIDSnake:      a.AssignmentID,
				SampleID:               a.SampleID,
				SampleIDSnake:          a.SampleID,
				Status:                 a.Status,
				JourneyID:              a.JourneyID,
				FromLocationID:         a.FromLocationID,
				ToLocationID:           a.ToLocationID,
				Sequence:               a.Sequence,
				OfferExpiresAt:         a.OfferExpiresAt,
				DestinationCapacity:    destCap,
				NodeID:                 a.NodeID,
				IncomingFromLocationID: a.IncomingFromLocationID,
				OutgoingToLocationID:   a.OutgoingToLocationID,
				LaboratoryID:           a.LaboratoryID,
				ExpectedSampleTypeID:   a.ExpectedSampleTypeID,
				History:                a.History,
			}
			switch a.Status {
			case "pending", "offered":
				rw.Pending = append(rw.Pending, item)
			case "accepted", "at_pickup", "picked_up", "in_transit", "arrived", "in_progress":
				rw.InProgress = append(rw.InProgress, item)
			case "completed", "delivered", "cancelled", "declined":
				rw.Completed = append(rw.Completed, item)
			}
		}
	}

	writeData(w, http.StatusOK, rw)
}
