}

func (srv *Server) handleCreateCollectionRequest(w http.ResponseWriter, r *http.Request) {
	srv.handleCreateOrIngestSample(w, r, false)
}

func (srv *Server) handleIngestPresealedSample(w http.ResponseWriter, r *http.Request) {
	srv.handleCreateOrIngestSample(w, r, true)
}

func (srv *Server) handleCreateOrIngestSample(w http.ResponseWriter, r *http.Request, presealed bool) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		RequesterID             string      `json:"requesterId"`
		Origin                  *Coordinate `json:"origin"`
		OriginType              *string     `json:"originType"`
		OriginNodeID            string      `json:"originNodeId"`
		RequestedAt             *string     `json:"requestedAt"`
		DeliveryDeadline        *string     `json:"deliveryDeadline"`
		EarliestCollectionAt    *string     `json:"earliestCollectionAt"`
		LatestCollectionAt      *string     `json:"latestCollectionAt"`
		SampleTypeID            *string     `json:"sampleTypeId"`
		ContainerType           *string     `json:"containerType"`
		TemperatureMinC         *float64    `json:"temperatureMinC"`
		TemperatureMaxC         *float64    `json:"temperatureMaxC"`
		IncompatibleSampleTypes []string    `json:"incompatibleSampleTypes"`
		IdempotencyKey          string      `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.Origin == nil || req.RequestedAt == nil || req.DeliveryDeadline == nil || req.SampleTypeID == nil || req.ContainerType == nil || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	opID := "create_collection_request"
	if presealed {
		opID = "ingest_presealed_sample"
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	var allowedRoles []string
	if presealed {
		allowedRoles = []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team", "administrator"}
	} else {
		allowedRoles = []string{"requester", "administrator", "dispatcher"}
	}

	ac, authErr := srv.requireRoleLocked(r, opID, "sample", "", true, allowedRoles...)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if strings.TrimSpace(req.IdempotencyKey) != "" {
		rec, idempErr := srv.checkIdempotencyLocked(opID, req.IdempotencyKey, raw)
		if idempErr != nil {
			writeError(w, idempErr.status, idempErr.code, idempErr.msg)
			return
		}
		if rec != nil {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(rec.StatusCode)
			_, _ = w.Write(rec.Response)
			return
		}
	}

	if req.Origin.Latitude < -90 || req.Origin.Latitude > 90 || req.Origin.Longitude < -180 || req.Origin.Longitude > 180 {
		writeError(w, http.StatusBadRequest, "invalid_origin", "origin coordinate out of bounds")
		return
	}

	originType := "home"
	if presealed {
		originType = "node"
	}
	if req.OriginType != nil {
		originType = strings.TrimSpace(*req.OriginType)
	}
	if presealed {
		if originType != "clinic" && originType != "node" {
			writeError(w, http.StatusBadRequest, "invalid_origin_type", "pre-sealed sample origin must be clinic or node")
			return
		}
	} else {
		if originType != "home" && originType != "clinic" && originType != "node" {
			writeError(w, http.StatusBadRequest, "invalid_origin_type", "invalid originType")
			return
		}
	}

	if req.OriginNodeID != "" {
		if !isValidUUID(req.OriginNodeID) {
			writeError(w, http.StatusBadRequest, "invalid_origin", "invalid originNodeId")
			return
		}
		loc := srv.store.state.Locations[req.OriginNodeID]
		if loc == nil {
			writeError(w, http.StatusNotFound, "not_found", "originNodeId not found")
			return
		}
		if !loc.Active || (!loc.Functions.CollectionPoint && !loc.Functions.TransferPoint && !loc.Functions.Hub) {
			writeError(w, http.StatusBadRequest, "invalid_origin_state", "origin node is inactive")
			return
		}
		if presealed && (ac.role == "node_handler" || ac.role == "laboratory_team") {
			if ac.user.AssignedLocationID != "" && ac.user.AssignedLocationID != req.OriginNodeID {
				writeError(w, http.StatusBadRequest, "invalid_holder", "handler is not assigned to the specified origin node")
				return
			}
		}
	}

	reqAt, ok1 := parseTimeRFC3339(*req.RequestedAt)
	deadline, ok2 := parseTimeRFC3339(*req.DeliveryDeadline)
	if !ok1 || !ok2 {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid requestedAt or deliveryDeadline")
		return
	}
	if !deadline.After(reqAt) {
		writeError(w, http.StatusBadRequest, "invalid_deadline", "deliveryDeadline must be after requestedAt")
		return
	}

	earliest := reqAt
	latest := deadline
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		t, ok := parseTimeRFC3339(*req.EarliestCollectionAt)
		if !ok {
			writeError(w, http.StatusBadRequest, "invalid_time", "invalid earliestCollectionAt")
			return
		}
		earliest = t
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		t, ok := parseTimeRFC3339(*req.LatestCollectionAt)
		if !ok {
			writeError(w, http.StatusBadRequest, "invalid_time", "invalid latestCollectionAt")
			return
		}
		latest = t
	}
	if latest.Before(earliest) || earliest.After(deadline) || latest.Before(reqAt) {
		writeError(w, http.StatusBadRequest, "invalid_collection_window", "invalid collection window")
		return
	}

	st := srv.store.state.SampleTypes[*req.SampleTypeID]
	if st == nil {
		writeError(w, http.StatusNotFound, "not_found", "sampleTypeId not found")
		return
	}

	container := strings.TrimSpace(*req.ContainerType)
	minC := *req.TemperatureMinC
	maxC := *req.TemperatureMaxC
	if container == "" || container != st.ContainerType || math.IsNaN(minC) || math.IsNaN(maxC) || minC > maxC || minC < st.TemperatureMinC || maxC > st.TemperatureMaxC {
		writeError(w, http.StatusBadRequest, "handling_mismatch", "request container or temperature range does not match sample type rules")
		return
	}

	startAt := reqAt
	if earliest.After(startAt) {
		startAt = earliest
	}

	fixedStartNode := ""
	if presealed && req.OriginNodeID != "" {
		fixedStartNode = req.OriginNodeID
	}

	srvOK, srvReason, rc := srv.store.evaluateServiceabilityLocked(
		*req.Origin,
		originType,
		req.OriginNodeID,
		st,
		startAt,
		deadline,
		1,
		fixedStartNode,
	)

	if !srvOK || rc == nil {
		switch srvReason {
		case "insufficient_capacity":
			if srv.store.sampleNeedsCooledLocked(st) {
				writeError(w, http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity for sample journey")
				return
			}
			writeError(w, http.StatusConflict, "capacity_exhausted", "insufficient regular capacity for sample journey")
			return
		case "deadline_unreachable":
			writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "sample cannot reach laboratory before delivery deadline")
			return
		case "no_route", "handling_rules_unsatisfiable":
			writeError(w, http.StatusConflict, "no_valid_route", "no valid route satisfies sample requirements")
			return
		}
	}

	requesterID := ac.user.UserID
	if req.RequesterID != "" {
		if ac.role != "administrator" && ac.role != "dispatcher" && !presealed && req.RequesterID != ac.user.UserID {
			writeError(w, http.StatusForbidden, "forbidden", "requester can only create requests for themselves")
			return
		}
		requesterID = req.RequesterID
	}

	requestID := NewUUID()
	sampleID := NewUUID()
	incomp := req.IncompatibleSampleTypes
	if incomp == nil {
		incomp = append([]string{}, st.IncompatibleSampleTypes...)
	}

	serviceabilityStr := "unserviceable"
	statusStr := "unserviceable"
	if srvOK && rc != nil {
		serviceabilityStr = "serviceable"
		statusStr = "scheduled"
		if presealed {
			statusStr = "sealed"
		}
	}

	nowStr := time.Now().UTC().Format(time.RFC3339)
	origCoord := *req.Origin
	smp := &Sample{
		SampleID:                 sampleID,
		RequestID:                requestID,
		RequesterID:              requesterID,
		Origin:                   origCoord,
		OriginType:               originType,
		OriginNodeID:             req.OriginNodeID,
		RequestedAt:              reqAt.Format(time.RFC3339),
		DeliveryDeadline:         deadline.Format(time.RFC3339),
		EarliestCollectionAt:     earliest.Format(time.RFC3339),
		LatestCollectionAt:       latest.Format(time.RFC3339),
		SampleTypeID:             st.SampleTypeID,
		ContainerType:            container,
		TemperatureMinC:          minC,
		TemperatureMaxC:          maxC,
		IncompatibleSampleTypes:  incomp,
		Serviceability:           serviceabilityStr,
		ServiceabilityReason:     srvReason,
		ActiveAssignmentIDs:      []string{},
		Status:                   statusStr,
		Sealed:                   presealed,
		HandlingCompliant:        true,
		CompletedLegIDs:          []string{},
		ActiveReplacementPlanIDs: []string{},
		Timeline:                 []TimelineEntry{},
		LatestLocation:           &origCoord,
		LocationRecordedAt:       nowStr,
		LocationStale:            false,
	}
	if presealed {
		smp.SealedAt = reqAt.Format(time.RFC3339)
		smp.CurrentHolderID = ac.user.UserID
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, opID, "sample", sampleID, true, nowStr, map[string]any{
		"requestId":      requestID,
		"serviceability": serviceabilityStr,
		"reason":         srvReason,
		"originType":     originType,
		"alreadySealed":  presealed,
	})
	smp.Timeline = append(smp.Timeline, tl)
	srv.store.state.Samples[sampleID] = smp

	var jp *JourneyPlan
	if srvOK && rc != nil {
		jp = srv.store.buildJourneyPlanForSampleLocked(smp, rc, startAt, presealed, ac.user.UserID, ac.role)
	}

	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, opID, "sample", sampleID, true, map[string]any{
		"requestId":      requestID,
		"serviceability": serviceabilityStr,
		"reason":         srvReason,
	})
	srv.store.publishRealtimeLocked("sample.created", "sample", sampleID, map[string]any{
		"sampleId":       sampleID,
		"requestId":      requestID,
		"status":         smp.Status,
		"serviceability": serviceabilityStr,
	})

	respData := map[string]any{
		"requestId":            requestID,
		"sampleId":             sampleID,
		"serviceability":       serviceabilityStr,
		"serviceabilityReason": srvReason,
		"activeAssignmentIds":  smp.ActiveAssignmentIDs,
		"earliestCollectionAt": smp.EarliestCollectionAt,
		"latestCollectionAt":   smp.LatestCollectionAt,
		"alreadySealed":        presealed,
		"originType":           originType,
	}
	if jp != nil {
		respData["journeyId"] = jp.JourneyID
		respData["targetLaboratoryId"] = smp.TargetLaboratoryID
	}

	if req.IdempotencyKey != "" {
		srv.saveIdempotencyLocked(opID, req.IdempotencyKey, raw, http.StatusCreated, respData)
	}
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) canActorAccessSampleLocked(ac *authContext, smp *Sample) bool {
	switch ac.role {
	case "administrator", "dispatcher":
		return true
	case "requester":
		return smp.RequesterID == ac.user.UserID
	default:
		if smp.CurrentHolderID == ac.user.UserID {
			return true
		}
		for _, a := range srv.store.state.Assignments {
			if a.SampleID == smp.SampleID && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				return true
			}
		}
		if ac.user.AssignedLocationID != "" && ac.user.AssignedLocationID == smp.TargetLaboratoryID {
			return true
		}
		return false
	}
}

func (srv *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request, sampleID string) {
	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	smp := srv.store.state.Samples[sampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}

	if !srv.canActorAccessSampleLocked(ac, smp) {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_sample_state", "sample", sampleID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "access denied to sample")
		return
	}

	srv.refreshSampleStaleLocked(smp)
	st := SampleState{
		SampleID:                smp.SampleID,
		RequestID:               smp.RequestID,
		RequesterID:             smp.RequesterID,
		Origin:                  smp.Origin,
		OriginType:              smp.OriginType,
		RequestedAt:             smp.RequestedAt,
		DeliveryDeadline:        smp.DeliveryDeadline,
		SampleTypeID:            smp.SampleTypeID,
		ContainerType:           smp.ContainerType,
		TemperatureMinC:         smp.TemperatureMinC,
		TemperatureMaxC:         smp.TemperatureMaxC,
		IncompatibleSampleTypes: smp.IncompatibleSampleTypes,
		Serviceability:          smp.Serviceability,
		ActiveAssignmentIDs:     smp.ActiveAssignmentIDs,
		State:                   SampleStateStatus{Status: smp.Status},
		Timeline:                smp.Timeline,
		ActiveJourneyID:         smp.ActiveJourneyID,
		TargetLaboratoryID:      smp.TargetLaboratoryID,
		LatestLocation:          smp.LatestLocation,
		LocationRecordedAt:      smp.LocationRecordedAt,
		LocationStale:           smp.LocationStale,
	}
	writeData(w, http.StatusOK, st)
}

func (srv *Server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleID *string `json:"sampleId"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleID == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	smp := srv.store.state.Samples[*req.SampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}

	if !srv.canActorAccessSampleLocked(ac, smp) {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_sample_lifecycle", "sample", smp.SampleID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "access denied to sample lifecycle")
		return
	}

	srv.refreshSampleStaleLocked(smp)
	lc := SampleLifecycle{
		SampleID:                 smp.SampleID,
		Status:                   smp.Status,
		Sealed:                   smp.Sealed,
		CompletedLegIDs:          smp.CompletedLegIDs,
		ActiveReplacementPlanIDs: smp.ActiveReplacementPlanIDs,
		Timeline:                 smp.Timeline,
		ActiveJourneyID:          smp.ActiveJourneyID,
		CurrentHolderID:          smp.CurrentHolderID,
		ReceivedLaboratoryID:     smp.ReceivedLaboratoryID,
		Exception:                smp.Exception,
		PendingHandoffID:         smp.PendingHandoffID,
		LatestLocation:           smp.LatestLocation,
		LocationRecordedAt:       smp.LocationRecordedAt,
		LocationStale:            smp.LocationStale,
	}
	if smp.PendingHandoffID != "" {
		if ho := srv.store.state.Handoffs[smp.PendingHandoffID]; ho != nil && ho.Status == "pending" {
			lc.PendingHandoff = map[string]any{
				"handoffId":         ho.HandoffID,
				"senderId":          ho.SenderID,
				"receiverId":        ho.ReceiverID,
				"senderConfirmed":   ho.SenderConfirmed,
				"receiverConfirmed": ho.ReceiverConfirmed,
				"status":            ho.Status,
			}
		}
	}
	writeData(w, http.StatusOK, lc)
}

func (srv *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	if len(strings.TrimSpace(string(raw))) > 0 {
		if err := decodeStrictJSON(raw, &req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
			return
		}
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	srv.store.expireStaleOffersLocked(time.Now().UTC())

	ac, authErr := srv.requireRoleLocked(r, "list_role_work", "work", "", true)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	role := ac.role
	if req.Role != nil && *req.Role != "" {
		rReq := strings.TrimSpace(*req.Role)
		if !isValidRole(rReq) {
			writeError(w, http.StatusBadRequest, "invalid_role", "invalid role")
			return
		}
		if rReq != ac.role {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "list_role_work", "work", rReq, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "cannot list work for a role other than activeRole")
			return
		}
		role = rReq
	}

	rw := RoleWork{
		Pending:    []any{},
		InProgress: []any{},
		Completed:  []any{},
	}

	switch role {
	case "requester":
		ids := make([]string, 0, len(srv.store.state.Samples))
		for id := range srv.store.state.Samples {
			ids = append(ids, id)
		}
		sort.Strings(ids)
		for _, id := range ids {
			smp := srv.store.state.Samples[id]
			if smp.RequesterID != ac.user.UserID {
				continue
			}
			srv.refreshSampleStaleLocked(smp)
			item := SampleWorkItem{
				Kind:                 "sample",
				SampleID:             smp.SampleID,
				SampleIDSnake:        smp.SampleID,
				RequestID:            smp.RequestID,
				Status:               smp.Status,
				Serviceability:       smp.Serviceability,
				RequestedAt:          smp.RequestedAt,
				DeliveryDeadline:     smp.DeliveryDeadline,
				EarliestCollectionAt: smp.EarliestCollectionAt,
				LatestCollectionAt:   smp.LatestCollectionAt,
				JourneyID:            smp.ActiveJourneyID,
				ActiveJourneyID:      smp.ActiveJourneyID,
				LaboratoryID:         smp.TargetLaboratoryID,
				CurrentHolderID:      smp.CurrentHolderID,
				RequesterID:          smp.RequesterID,
				History:              smp.Timeline,
				LocationRecordedAt:   smp.LocationRecordedAt,
				LocationStale:        smp.LocationStale,
			}
			if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
				rw.Completed = append(rw.Completed, item)
			} else if smp.Sealed || smp.Status == "in_transit" {
				rw.InProgress = append(rw.InProgress, item)
			} else {
				rw.Pending = append(rw.Pending, item)
			}
		}

	case "dispatcher", "administrator":
		jIDs := make([]string, 0, len(srv.store.state.Journeys))
		for id := range srv.store.state.Journeys {
			jIDs = append(jIDs, id)
		}
		sort.Strings(jIDs)
		for _, id := range jIDs {
			jp := srv.store.state.Journeys[id]
			assignCount := len(jp.Legs) + len(jp.CollectionAssignmentIDs) + len(jp.NodeAssignmentIDs) + len(jp.LaboratoryAssignmentIDs)
			item := JourneyWorkItem{
				Kind:                "journey",
				JourneyID:           jp.JourneyID,
				JourneyIDSnake:      jp.JourneyID,
				Status:              jp.Status,
				RouteMode:           jp.RouteMode,
				PlanVersion:         jp.PlanVersion,
				SampleIDs:           jp.SampleIDs,
				EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
				AssignmentCount:     assignCount,
				History:             jp.History,
			}
			if jp.Status == "completed" || jp.Status == "cancelled" || jp.Status == "replaced" {
				rw.Completed = append(rw.Completed, item)
			} else if jp.Status == "in_progress" {
				rw.InProgress = append(rw.InProgress, item)
			} else {
				rw.Pending = append(rw.Pending, item)
			}
		}

	default:
		wantKind := ""
		switch role {
		case "collection_professional":
			wantKind = "collection"
		case "delivery_partner":
			wantKind = "transport"
		case "node_handler":
			wantKind = "node"
		case "laboratory_team":
			wantKind = "laboratory"
		}
		aIDs := make([]string, 0, len(srv.store.state.Assignments))
		for id := range srv.store.state.Assignments {
			aIDs = append(aIDs, id)
		}
		sort.Strings(aIDs)
		for _, id := range aIDs {
			a := srv.store.state.Assignments[id]
			if a.Kind != wantKind {
				continue
			}
			isMine := a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID
			if !isMine {
				for _, h := range a.History {
					if h.ActorID == ac.user.UserID {
						isMine = true
						break
					}
				}
			}
			if !isMine {
				continue
			}
			var destCap *Capacity
			if a.ToLocationID != "" {
				if loc := srv.store.state.Locations[a.ToLocationID]; loc != nil {
					c := srv.store.getLocationCapacityLocked(loc)
					destCap = &c
				}
			}
			item := AssignmentWorkItem{
				Kind:                   a.Kind,
				AssignmentID:           a.AssignmentID,
				AssignmentIDSnake:      a.AssignmentID,
				SampleID:               a.SampleID,
				SampleIDSnake:          a.SampleID,
				Status:                 a.Status,
				JourneyID:              a.JourneyID,
				FromLocationID:         a.FromLocationID,
				ToLocationID:           a.ToLocationID,
				Sequence:               a.Sequence,
				OfferExpiresAt:         a.OfferExpiresAt,
				DestinationCapacity:    destCap,
				NodeID:                 a.NodeID,
				IncomingFromLocationID: a.IncomingFromLocationID,
				OutgoingToLocationID:   a.OutgoingToLocationID,
				LaboratoryID:           a.LaboratoryID,
				ExpectedSampleTypeID:   a.ExpectedSampleTypeID,
				History:                a.History,
			}
			switch a.Status {
			case "pending", "offered":
				rw.Pending = append(rw.Pending, item)
			case "accepted", "at_pickup", "picked_up", "in_transit", "arrived", "in_progress":
				rw.InProgress = append(rw.InProgress, item)
			case "completed", "delivered", "cancelled", "declined":
				rw.Completed = append(rw.Completed, item)
			}
		}
	}

	writeData(w, http.StatusOK, rw)
}

action.new_str:
	writeData(w, http.StatusOK, rw)
}

func (srv *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.AssignmentID == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	srv.store.expireStaleOffersLocked(time.Now().UTC())

	ac, authErr := srv.requireRoleLocked(r, "accept_assignment", "assignment", *req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("accept_assignment", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	a := srv.store.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}

	elig, certOK := srv.store.isWorkerEligibleForAssignmentLocked(ac.user, a, time.Now().UTC())
	if !elig || !certOK {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "accept_assignment", "assignment", a.AssignmentID, false, map[string]any{"error": "ineligible_worker"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "ineligible_worker", "worker is not eligible for this assignment")
		return
	}

	if a.Status == "cancelled" || a.Status == "completed" || a.Status == "delivered" {
		writeError(w, http.StatusConflict, "assignment_inactive", "assignment is no longer active")
		return
	}
	if a.Status == "accepted" || isAssignmentInProgress(a.Status) {
		if a.WorkerID != ac.user.UserID {
			writeError(w, http.StatusConflict, "assignment_taken", "assignment already accepted by another worker")
			return
		}
	}
	if a.OfferedToWorkerID == "" {
		writeError(w, http.StatusConflict, "offer_not_offered", "assignment has not been offered")
		return
	}
	if a.OfferedToWorkerID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "accept_assignment", "assignment", a.AssignmentID, false, map[string]any{"error": "offer_not_available", "offeredTo": a.OfferedToWorkerID})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusConflict, "offer_not_available", "assignment was not offered to this worker")
		return
	}
	if !ac.user.Available || ac.user.ReservedUnits >= ac.user.CapacityUnits {
		writeError(w, http.StatusConflict, "worker_unavailable", "worker is currently unavailable or at capacity")
		return
	}

	nowStr := time.Now().UTC().Format(time.RFC3339)
	if a.Status != "accepted" {
		a.Status = "accepted"
		a.WorkerID = ac.user.UserID
		ac.user.ReservedUnits++
		ac.user.AssignmentCount++
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "accept_assignment", "assignment", a.AssignmentID, true, nowStr, map[string]any{
		"workerId": ac.user.UserID,
		"status":   "accepted",
	})
	a.History = append(a.History, tl)
	if smp := srv.store.state.Samples[a.SampleID]; smp != nil {
		smp.Timeline = append(smp.Timeline, tl)
	}
	if jp := srv.store.state.Journeys[a.JourneyID]; jp != nil {
		srv.store.syncJourneyAssignmentsLocked(jp)
		jp.History = append(jp.History, tl)
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "accept_assignment", "assignment", a.AssignmentID, true, map[string]any{"workerId": ac.user.UserID})
	srv.store.publishRealtimeLocked("assignment.accepted", "assignment", a.AssignmentID, map[string]any{
		"assignmentId": a.AssignmentID,
		"workerId":     ac.user.UserID,
		"status":       "accepted",
	})

	respData := map[string]any{
		"assignmentId": a.AssignmentID,
		"workerId":     ac.user.UserID,
		"status":       "accepted",
	}
	srv.saveIdempotencyLocked("accept_assignment", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		Reason         string  `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.AssignmentID == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "decline_assignment", "assignment", *req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("decline_assignment", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	declinedAt := time.Now().UTC()
	if req.DeclinedAt != nil && *req.DeclinedAt != "" {
		t, ok := parseTimeRFC3339(*req.DeclinedAt)
		if !ok {
			writeError(w, http.StatusBadRequest, "invalid_time", "invalid declinedAt")
			return
		}
		declinedAt = t
	}
	declinedAtStr := declinedAt.Format(time.RFC3339)

	a := srv.store.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}

	if a.OfferedToWorkerID != ac.user.UserID || (a.Status != "offered" && a.Status != "pending") {
		writeError(w, http.StatusConflict, "offer_not_available", "assignment is not currently offered to this worker")
		return
	}

	if a.DeclinedByWorkerIDs == nil {
		a.DeclinedByWorkerIDs = make(map[string]bool)
	}
	a.DeclinedByWorkerIDs[ac.user.UserID] = true
	ac.user.DeclineCount++
	ac.user.LastDeclinedAt = declinedAtStr

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "decline_assignment", "assignment", a.AssignmentID, true, declinedAtStr, map[string]any{
		"declinedBy": ac.user.UserID,
		"reason":     req.Reason,
	})
	a.History = append(a.History, tl)
	if smp := srv.store.state.Samples[a.SampleID]; smp != nil {
		smp.Timeline = append(smp.Timeline, tl)
	}

	nextW := srv.store.offerAssignmentLocked(a, declinedAt, ac.user.UserID, ac.role)
	if jp := srv.store.state.Journeys[a.JourneyID]; jp != nil {
		srv.store.syncJourneyAssignmentsLocked(jp)
	}
	if nextW == nil {
		if smp := srv.store.state.Samples[a.SampleID]; smp != nil && smp.Status != "received" && smp.Status != "cancelled" && smp.Status != "expired" {
			smp.Status = "exception"
			smp.Exception = map[string]any{
				"reason":       "no_qualified_worker_available",
				"code":         "no_qualified_worker",
				"assignmentId": a.AssignmentID,
				"kind":         a.Kind,
			}
		}
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "decline_assignment", "assignment", a.AssignmentID, true, map[string]any{
		"declinedBy": ac.user.UserID,
		"reason":     req.Reason,
	})

	respData := map[string]any{
		"assignmentId": a.AssignmentID,
		"status":       "pending",
		"declinedBy":   ac.user.UserID,
		"declinedAt":   declinedAtStr,
	}
	if nextW != nil {
		respData["reofferedTo"] = nextW.UserID
	}
	srv.saveIdempotencyLocked("decline_assignment", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		CollectedAt          *string  `json:"collectedAt"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey       *string  `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleID == nil || req.AssignmentID == nil || req.CollectedAt == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "collect_and_seal_sample", "sample", *req.SampleID, true, "collection_professional")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("collect_and_seal_sample", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	collectedAt, ok := parseTimeRFC3339(*req.CollectedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid collectedAt")
		return
	}

	smp := srv.store.state.Samples[*req.SampleID]
	a := srv.store.state.Assignments[*req.AssignmentID]
	if smp == nil || a == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample or assignment not found")
		return
	}
	if a.SampleID != smp.SampleID || a.Kind != "collection" || a.WorkerID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "collect_and_seal_sample", "sample", smp.SampleID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "not assigned collector for this sample")
		return
	}

	st := srv.store.state.SampleTypes[smp.SampleTypeID]
	qual, certActive := srv.store.isCollectorQualifiedAndActiveLocked(ac.user, st, collectedAt)
	if !qual {
		writeError(w, http.StatusForbidden, "forbidden", "collector lacks required qualification")
		return
	}
	if !certActive {
		writeError(w, http.StatusConflict, "certification_inactive", "collector certification is inactive or expired")
		return
	}

	if a.Status == "cancelled" || a.Status == "completed" {
		writeError(w, http.StatusConflict, "assignment_inactive", "collection assignment is inactive")
		return
	}
	if a.Status != "accepted" && a.Status != "in_progress" && a.Status != "at_pickup" {
		writeError(w, http.StatusConflict, "collection_not_ready", "collection assignment must be accepted before collecting")
		return
	}
	if smp.Sealed || smp.Status == "cancelled" || smp.Status == "received" {
		writeError(w, http.StatusConflict, "invalid_sample_state", "sample is already sealed or terminal")
		return
	}

	earliest, okE := parseTimeRFC3339(smp.EarliestCollectionAt)
	latest, okL := parseTimeRFC3339(smp.LatestCollectionAt)
	if okE && okL {
		if collectedAt.Before(earliest) || collectedAt.After(latest) {
			writeError(w, http.StatusConflict, "outside_collection_window", "collection time is outside the allowed collection window")
			return
		}
	}

	obsTemp := *req.ObservedTemperatureC
	if strings.TrimSpace(*req.ContainerType) != smp.ContainerType || math.IsNaN(obsTemp) || obsTemp < smp.TemperatureMinC || obsTemp > smp.TemperatureMaxC {
		smp.Status = "exception"
		smp.HandlingCompliant = false
		smp.Exception = map[string]any{
			"reason":               "handling_noncompliant",
			"containerType":        *req.ContainerType,
			"observedTemperatureC": obsTemp,
		}
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "collect_and_seal_sample", "sample", smp.SampleID, false, map[string]any{"error": "handling_noncompliant"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusBadRequest, "handling_noncompliant", "observed container or temperature violates sample handling rules")
		return
	}

	collectedStr := collectedAt.Format(time.RFC3339)
	smp.Sealed = true
	smp.SealedAt = collectedStr
	smp.Status = "sealed"
	smp.CurrentHolderID = ac.user.UserID
	smp.HandlingCompliant = true
	a.Status = "completed"
	a.LastProgressAt = collectedStr
	if ac.user.ReservedUnits > 0 {
		ac.user.ReservedUnits--
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "collect_and_seal_sample", "sample", smp.SampleID, true, collectedStr, map[string]any{
		"assignmentId":         a.AssignmentID,
		"collectorId":          ac.user.UserID,
		"containerType":        *req.ContainerType,
		"observedTemperatureC": obsTemp,
	})
	smp.Timeline = append(smp.Timeline, tl)
	a.History = append(a.History, tl)
	if jp := srv.store.state.Journeys[smp.ActiveJourneyID]; jp != nil {
		if jp.Status == "planned" {
			jp.Status = "in_progress"
		}
		if len(jp.OrderedStops) > 0 && jp.OrderedStops[0].CompletedAt == "" {
			jp.OrderedStops[0].CompletedAt = collectedStr
		}
		jp.History = append(jp.History, tl)
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "collect_and_seal_sample", "sample", smp.SampleID, true, map[string]any{
		"assignmentId":    a.AssignmentID,
		"currentHolderId": ac.user.UserID,
	})
	srv.store.publishRealtimeLocked("sample.sealed", "sample", smp.SampleID, map[string]any{
		"sampleId":        smp.SampleID,
		"status":          "sealed",
		"currentHolderId": ac.user.UserID,
	})

	respData := map[string]any{
		"sampleId":          smp.SampleID,
		"status":            "sealed",
		"currentHolderId":   ac.user.UserID,
		"sealedAt":          collectedStr,
		"handlingCompliant": true,
	}
	srv.saveIdempotencyLocked("collect_and_seal_sample", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		AssignmentID   *string `json:"assignmentId"`
		Status         *string `json:"status"`
		OccurredAt     *string `json:"occurredAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.AssignmentID == nil || req.Status == nil || req.OccurredAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "update_assignment_progress", "assignment", *req.AssignmentID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("update_assignment_progress", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	occAt, ok := parseTimeRFC3339(*req.OccurredAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}
	status := strings.TrimSpace(*req.Status)
	switch status {
	case "at_pickup", "picked_up", "in_transit", "arrived", "delivered", "in_progress", "completed":
	default:
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid status")
		return
	}

	a := srv.store.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.WorkerID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "update_assignment_progress", "assignment", a.AssignmentID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "not the assigned worker for this assignment")
		return
	}
	if a.Status == "cancelled" || a.Status == "completed" {
		writeError(w, http.StatusConflict, "assignment_inactive", "assignment is inactive")
		return
	}
	if a.Status == "pending" || a.Status == "offered" {
		writeError(w, http.StatusConflict, "assignment_not_ready", "assignment must be accepted before recording progress")
		return
	}

	smp := srv.store.state.Samples[a.SampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}

	if a.Kind == "transport" {
		if !smp.Sealed {
			writeError(w, http.StatusConflict, "collection_required", "sample must be collected and sealed before transport")
			return
		}
		// Check prior transport legs completed
		if jp := srv.store.state.Journeys[a.JourneyID]; jp != nil {
			for _, leg := range jp.Legs {
				if leg.Sequence < a.Sequence {
					prevA := srv.store.state.Assignments[leg.AssignmentID]
					if prevA != nil && !isAssignmentCompleted(prevA.Status) {
						writeError(w, http.StatusConflict, "prior_leg_incomplete", "prior transport leg is not yet completed")
						return
					}
				}
			}
		}
		// Delivery cannot happen before pickup
		if status == "delivered" || status == "arrived" || status == "in_transit" {
			if smp.CurrentHolderID != ac.user.UserID {
				writeError(w, http.StatusConflict, "custody_required", "worker must hold confirmed custody of the sample before transit or delivery")
				return
			}
		}
		if status == "delivered" {
			if a.Status != "picked_up" && a.Status != "in_transit" && a.Status != "arrived" && a.Status != "in_progress" {
				writeError(w, http.StatusConflict, "invalid_transition", "pickup must happen before delivery")
				return
			}
		}
	}

	if a.LastProgressAt != "" {
		if prevT, ok := parseTimeRFC3339(a.LastProgressAt); ok && occAt.Before(prevT) {
			writeError(w, http.StatusConflict, "invalid_progress_time", "occurredAt cannot be earlier than previous progress update")
			return
		}
	}
	if dl, ok := parseTimeRFC3339(smp.DeliveryDeadline); ok && occAt.After(dl) {
		writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "progress time exceeds delivery deadline")
		return
	}

	occStr := occAt.Format(time.RFC3339)
	a.Status = status
	a.LastProgressAt = occStr

	if status == "picked_up" || status == "in_transit" {
		smp.Status = "in_transit"
	} else if status == "delivered" || status == "completed" {
		if a.Kind == "transport" {
			has := false
			for _, id := range smp.CompletedLegIDs {
				if id == a.AssignmentID {
					has = true
					break
				}
			}
			if !has {
				smp.CompletedLegIDs = append(smp.CompletedLegIDs, a.AssignmentID)
			}
		}
		if status == "completed" && ac.user.ReservedUnits > 0 {
			ac.user.ReservedUnits--
		}
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "update_assignment_progress", "assignment", a.AssignmentID, true, occStr, map[string]any{
		"status":   status,
		"sampleId": smp.SampleID,
	})
	a.History = append(a.History, tl)
	smp.Timeline = append(smp.Timeline, tl)
	if jp := srv.store.state.Journeys[a.JourneyID]; jp != nil {
		if jp.Status == "planned" {
			jp.Status = "in_progress"
		}
		srv.store.syncJourneyAssignmentsLocked(jp)
		jp.History = append(jp.History, tl)
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{
		"status":   status,
		"sampleId": smp.SampleID,
	})
	srv.store.publishRealtimeLocked("assignment.progress", "assignment", a.AssignmentID, map[string]any{
		"assignmentId": a.AssignmentID,
		"sampleId":     smp.SampleID,
		"status":       status,
	})

	respData := map[string]any{
		"assignmentId": a.AssignmentID,
		"sampleId":     smp.SampleID,
		"status":       status,
	}
	srv.saveIdempotencyLocked("update_assignment_progress", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		AssignmentID *string     `json:"assignmentId"`
		Coordinate   *Coordinate `json:"coordinate"`
		Sequence     *int        `json:"sequence"`
		RecordedAt   *string     `json:"recordedAt"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.AssignmentID == nil || req.Coordinate == nil || req.Sequence == nil || req.RecordedAt == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "record_worker_location", "assignment", *req.AssignmentID, true, "collection_professional", "delivery_partner")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeError(w, http.StatusBadRequest, "invalid_coordinate", "coordinate out of bounds")
		return
	}
	if *req.Sequence < 1 {
		writeError(w, http.StatusBadRequest, "invalid_sequence", "sequence must be >= 1")
		return
	}
	recAt, ok := parseTimeRFC3339(*req.RecordedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}

	a := srv.store.state.Assignments[*req.AssignmentID]
	if a == nil {
		writeError(w, http.StatusNotFound, "not_found", "assignment not found")
		return
	}
	if a.WorkerID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "record_worker_location", "assignment", a.AssignmentID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "not assigned worker for this assignment")
		return
	}

	if *req.Sequence <= a.LastLocationSeq {
		writeError(w, http.StatusConflict, "stale_location", "location sequence is older than or equal to latest recorded sequence")
		return
	}
	if ac.user.LocationRecordedAt != "" {
		if prevT, ok := parseTimeRFC3339(ac.user.LocationRecordedAt); ok && recAt.Before(prevT) {
			writeError(w, http.StatusConflict, "stale_location", "recordedAt is older than latest recorded location")
			return
		}
	}

	recStr := recAt.Format(time.RFC3339)
	coordCopy := *req.Coordinate
	a.LastLocationSeq = *req.Sequence
	ac.user.LatestLocation = &coordCopy
	ac.user.LocationRecordedAt = recStr

	// Update sample location if worker currently holds it or is collecting it
	if smp := srv.store.state.Samples[a.SampleID]; smp != nil {
		if smp.CurrentHolderID == ac.user.UserID || (!smp.Sealed && a.Kind == "collection") {
			cCopy := *req.Coordinate
			smp.LatestLocation = &cCopy
			smp.LocationRecordedAt = recStr
			srv.refreshSampleStaleLocked(smp)
		}
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "record_worker_location", "assignment", a.AssignmentID, true, recStr, map[string]any{
		"coordinate": coordCopy,
		"sequence":   *req.Sequence,
	})
	a.History = append(a.History, tl)

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "record_worker_location", "assignment", a.AssignmentID, true, map[string]any{
		"coordinate": coordCopy,
		"sequence":   *req.Sequence,
	})
	srv.store.publishRealtimeLocked("worker.location", "worker", ac.user.UserID, map[string]any{
		"workerId":     ac.user.UserID,
		"assignmentId": a.AssignmentID,
		"coordinate":   coordCopy,
		"sequence":     *req.Sequence,
		"recordedAt":   recStr,
	})

	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, map[string]any{
		"assignmentId": a.AssignmentID,
		"coordinate":   coordCopy,
		"sequence":     *req.Sequence,
		"recordedAt":   recStr,
	})
}

func (srv *Server) validateHandoffAdjacencyLocked(jp *JourneyPlan, fromA, toA *Assignment) (string, bool) {
	if fromA.SampleID != toA.SampleID || fromA.JourneyID != toA.JourneyID {
		return "invalid_handoff_route", false
	}
	switch fromA.Kind {
	case "collection":
		if toA.Kind == "node" && toA.NodeID == fromA.ToLocationID {
			return "", true
		}
		if toA.Kind == "transport" && toA.Sequence == 1 {
			return "", true
		}
		return "nonadjacent_handoff", false
	case "node":
		if toA.Kind == "transport" {
			if toA.FromLocationID == fromA.NodeID {
				return "", true
			}
			return "node_assignment_mismatch", false
		}
		if toA.Kind == "laboratory" && toA.LaboratoryID == fromA.NodeID {
			return "", true
		}
		return "nonadjacent_handoff", false
	case "transport":
		if toA.Kind == "node" {
			if toA.NodeID == fromA.ToLocationID {
				return "", true
			}
			return "node_assignment_mismatch", false
		}
		if toA.Kind == "transport" {
			if toA.Sequence == fromA.Sequence+1 && toA.FromLocationID == fromA.ToLocationID {
				return "", true
			}
			return "nonadjacent_handoff", false
		}
		if toA.Kind == "laboratory" {
			if jp != nil && fromA.Sequence == len(jp.Legs) && toA.LaboratoryID == fromA.ToLocationID {
				return "", true
			}
			return "nonadjacent_handoff", false
		}
	}
	return "invalid_handoff_route", false
}

func (srv *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleID         *string `json:"sampleId"`
		FromAssignmentID *string `json:"fromAssignmentId"`
		ToAssignmentID   *string `json:"toAssignmentId"`
		ReceiverID       *string `json:"receiverId"`
		InitiatedAt      *string `json:"initiatedAt"`
		IdempotencyKey   *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleID == nil || req.FromAssignmentID == nil || req.ToAssignmentID == nil || req.ReceiverID == nil || req.InitiatedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "initiate_handoff", "sample", *req.SampleID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("initiate_handoff", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	initAt, ok := parseTimeRFC3339(*req.InitiatedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid initiatedAt")
		return
	}
	if !isValidUUID(*req.ReceiverID) {
		writeError(w, http.StatusBadRequest, "invalid_receiver", "invalid receiverId")
		return
	}

	smp := srv.store.state.Samples[*req.SampleID]
	fromA := srv.store.state.Assignments[*req.FromAssignmentID]
	toA := srv.store.state.Assignments[*req.ToAssignmentID]
	receiver := srv.store.state.Users[*req.ReceiverID]
	if smp == nil || fromA == nil || toA == nil || receiver == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample, assignment, or receiver not found")
		return
	}

	if fromA.WorkerID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "initiate_handoff", "sample", smp.SampleID, false, map[string]any{"error": "sender_assignment_mismatch"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "sender_assignment_mismatch", "caller is not the worker for fromAssignmentId")
		return
	}
	if smp.CurrentHolderID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "initiate_handoff", "sample", smp.SampleID, false, map[string]any{"error": "not_current_holder"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusConflict, "not_current_holder", "only current holder of the sample can initiate handoff")
		return
	}
	if smp.PendingHandoffID != "" {
		if existing := srv.store.state.Handoffs[smp.PendingHandoffID]; existing != nil && existing.Status == "pending" {
			writeError(w, http.StatusConflict, "pending_handoff_exists", "a pending handoff already exists for this sample")
			return
		}
	}
	if !receiver.Active || !receiver.Available {
		writeError(w, http.StatusConflict, "receiver_unavailable", "receiver is unavailable")
		return
	}
	if toA.WorkerID != receiver.UserID {
		if toA.OfferedToWorkerID == receiver.UserID && (toA.Status == "offered" || toA.Status == "pending") {
			writeError(w, http.StatusConflict, "offer_not_available", "receiver has not yet accepted toAssignmentId")
			return
		}
		writeError(w, http.StatusConflict, "receiver_assignment_mismatch", "receiver does not match toAssignmentId worker")
		return
	}
	if toA.Status == "cancelled" || toA.Status == "completed" || fromA.Status == "cancelled" {
		writeError(w, http.StatusConflict, "invalid_assignment_state", "assignment is not in a valid state for handoff")
		return
	}

	jp := srv.store.state.Journeys[smp.ActiveJourneyID]
	if errCode, okAdj := srv.validateHandoffAdjacencyLocked(jp, fromA, toA); !okAdj {
		writeError(w, http.StatusConflict, errCode, "assignments are not adjacent on the journey route")
		return
	}

	if fromA.Kind == "transport" {
		if fromA.Status != "arrived" && fromA.Status != "delivered" && fromA.Status != "completed" && fromA.Status != "in_transit" && fromA.Status != "picked_up" {
			writeError(w, http.StatusConflict, "transport_leg_incomplete", "transport leg must be picked up before handoff")
			return
		}
	}

	if smp.SealedAt != "" {
		if st, ok := parseTimeRFC3339(smp.SealedAt); ok && initAt.Before(st) {
			writeError(w, http.StatusConflict, "invalid_handoff_time", "initiatedAt cannot be before sample sealedAt")
			return
		}
	}

	hoID := NewUUID()
	initStr := initAt.Format(time.RFC3339)
	ho := &Handoff{
		HandoffID:         hoID,
		SampleID:          smp.SampleID,
		FromAssignmentID:  fromA.AssignmentID,
		ToAssignmentID:    toA.AssignmentID,
		SenderID:          ac.user.UserID,
		ReceiverID:        receiver.UserID,
		CurrentHolderID:   smp.CurrentHolderID,
		Status:            "pending",
		SenderConfirmed:   false,
		ReceiverConfirmed: false,
		InitiatedAt:       initStr,
	}
	srv.store.state.Handoffs[hoID] = ho
	smp.PendingHandoffID = hoID

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "initiate_handoff", "sample", smp.SampleID, true, initStr, map[string]any{
		"handoffId":        hoID,
		"senderId":         ac.user.UserID,
		"receiverId":       receiver.UserID,
		"fromAssignmentId": fromA.AssignmentID,
		"toAssignmentId":   toA.AssignmentID,
	})
	smp.Timeline = append(smp.Timeline, tl)
	fromA.History = append(fromA.History, tl)
	toA.History = append(toA.History, tl)

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "initiate_handoff", "handoff", hoID, true, map[string]any{
		"sampleId":   smp.SampleID,
		"senderId":   ac.user.UserID,
		"receiverId": receiver.UserID,
	})
	srv.store.publishRealtimeLocked("handoff.initiated", "handoff", hoID, map[string]any{
		"handoffId":       hoID,
		"sampleId":        smp.SampleID,
		"currentHolderId": smp.CurrentHolderID,
		"status":          "pending",
	})

	respData := map[string]any{
		"handoffId":       hoID,
		"senderId":        ho.SenderID,
		"receiverId":      ho.ReceiverID,
		"currentHolderId": ho.CurrentHolderID,
		"status":          "pending",
	}
	srv.saveIdempotencyLocked("initiate_handoff", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		HandoffID        *string `json:"handoffId"`
		ConfirmationSide *string `json:"confirmationSide"`
		ConfirmedAt      *string `json:"confirmedAt"`
		IdempotencyKey   *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.HandoffID == nil || req.ConfirmationSide == nil || req.ConfirmedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "confirm_handoff", "handoff", *req.HandoffID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("confirm_handoff", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	side := strings.TrimSpace(*req.ConfirmationSide)
	if side != "sender" && side != "receiver" {
		writeError(w, http.StatusBadRequest, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		return
	}
	confAt, ok := parseTimeRFC3339(*req.ConfirmedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid confirmedAt")
		return
	}

	ho := srv.store.state.Handoffs[*req.HandoffID]
	if ho == nil {
		writeError(w, http.StatusNotFound, "not_found", "handoff not found")
		return
	}
	if ho.Status == "cancelled" {
		writeError(w, http.StatusConflict, "handoff_inactive", "handoff is cancelled")
		return
	}

	if (side == "sender" && ac.user.UserID != ho.SenderID) || (side == "receiver" && ac.user.UserID != ho.ReceiverID) {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "confirm_handoff", "handoff", ho.HandoffID, false, map[string]any{"error": "forbidden", "side": side})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "user is not the specified party on this handoff")
		return
	}

	if initT, ok := parseTimeRFC3339(ho.InitiatedAt); ok && confAt.Before(initT) {
		writeError(w, http.StatusConflict, "invalid_confirmation_time", "confirmedAt cannot be before initiatedAt")
		return
	}

	smp := srv.store.state.Samples[ho.SampleID]
	if smp == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample not found")
		return
	}

	confStr := confAt.Format(time.RFC3339)
	alreadyConfirmed := ho.Status == "confirmed"

	if !alreadyConfirmed {
		if smp.CurrentHolderID != ho.SenderID {
			writeError(w, http.StatusConflict, "custody_conflict", "sender no longer holds sample custody")
			return
		}
		if side == "sender" {
			ho.SenderConfirmed = true
		} else {
			ho.ReceiverConfirmed = true
		}

		if ho.SenderConfirmed && ho.ReceiverConfirmed {
			ho.Status = "confirmed"
			ho.ConfirmedAt = confStr
			ho.CurrentHolderID = ho.ReceiverID
			smp.CurrentHolderID = ho.ReceiverID
			smp.PendingHandoffID = ""

			fromA := srv.store.state.Assignments[ho.FromAssignmentID]
			toA := srv.store.state.Assignments[ho.ToAssignmentID]
			if fromA != nil {
				if fromA.Status != "completed" {
					fromA.Status = "completed"
					fromA.LastProgressAt = confStr
					if senderUser := srv.store.state.Users[ho.SenderID]; senderUser != nil && senderUser.ReservedUnits > 0 {
						senderUser.ReservedUnits--
					}
				}
				if fromA.Kind == "transport" {
					has := false
					for _, id := range smp.CompletedLegIDs {
						if id == fromA.AssignmentID {
							has = true
							break
						}
					}
					if !has {
						smp.CompletedLegIDs = append(smp.CompletedLegIDs, fromA.AssignmentID)
					}
				}
			}
			if toA != nil {
				if toA.Kind == "transport" {
					toA.Status = "picked_up"
					toA.LastProgressAt = confStr
					smp.Status = "in_transit"
				} else if toA.Kind == "node" || toA.Kind == "laboratory" {
					toA.Status = "in_progress"
					toA.LastProgressAt = confStr
				}
				if toA.FromLocationID != "" {
					if loc := srv.store.state.Locations[toA.FromLocationID]; loc != nil {
						cCopy := loc.Coordinate
						smp.LatestLocation = &cCopy
						smp.LocationRecordedAt = confStr
						srv.refreshSampleStaleLocked(smp)
					}
				}
			}
			if jp := srv.store.state.Journeys[smp.ActiveJourneyID]; jp != nil {
				srv.store.syncJourneyAssignmentsLocked(jp)
				if fromA != nil && fromA.ToLocationID != "" {
					for idx := range jp.OrderedStops {
						if jp.OrderedStops[idx].LocationID == fromA.ToLocationID && jp.OrderedStops[idx].CompletedAt == "" {
							jp.OrderedStops[idx].CompletedAt = confStr
							break
						}
					}
				}
			}

			custodyTL := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "custody_transferred", "sample", smp.SampleID, true, confStr, map[string]any{
				"handoffId":       ho.HandoffID,
				"fromHolderId":    ho.SenderID,
				"currentHolderId": ho.ReceiverID,
			})
			smp.Timeline = append(smp.Timeline, custodyTL)
			if fromA != nil {
				fromA.History = append(fromA.History, custodyTL)
			}
			if toA != nil {
				toA.History = append(toA.History, custodyTL)
			}
		} else {
			partialTL := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "confirm_handoff_"+side, "sample", smp.SampleID, true, confStr, map[string]any{
				"handoffId":       ho.HandoffID,
				"side":            side,
				"currentHolderId": smp.CurrentHolderID,
			})
			smp.Timeline = append(smp.Timeline, partialTL)
		}
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "confirm_handoff", "handoff", ho.HandoffID, true, map[string]any{
		"sampleId":          smp.SampleID,
		"side":              side,
		"status":            ho.Status,
		"senderConfirmed":   ho.SenderConfirmed,
		"receiverConfirmed": ho.ReceiverConfirmed,
		"currentHolderId":   smp.CurrentHolderID,
	})
	srv.store.publishRealtimeLocked("handoff.confirmed", "handoff", ho.HandoffID, map[string]any{
		"handoffId":       ho.HandoffID,
		"sampleId":        smp.SampleID,
		"status":          ho.Status,
		"currentHolderId": smp.CurrentHolderID,
	})

	respData := map[string]any{
		"handoffId":         ho.HandoffID,
		"status":            ho.Status,
		"senderConfirmed":   ho.SenderConfirmed,
		"receiverConfirmed": ho.ReceiverConfirmed,
		"currentHolderId":   smp.CurrentHolderID,
	}
	srv.saveIdempotencyLocked("confirm_handoff", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleID             *string  `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		LocationID           string   `json:"locationId"`
		ContainerType        *string  `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           *string  `json:"recordedAt"`
		IdempotencyKey       *string  `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleID == nil || req.AssignmentID == nil || req.ContainerType == nil || req.ObservedTemperatureC == nil || req.RecordedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "record_handling_checkpoint", "sample", *req.SampleID, true, "collection_professional", "delivery_partner", "node_handler", "laboratory_team")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("record_handling_checkpoint", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	recAt, ok := parseTimeRFC3339(*req.RecordedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid recordedAt")
		return
	}

	smp := srv.store.state.Samples[*req.SampleID]
	a := srv.store.state.Assignments[*req.AssignmentID]
	if smp == nil || a == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample or assignment not found")
		return
	}
	if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
		writeError(w, http.StatusConflict, "terminal_sample", "cannot record checkpoint on a terminal sample")
		return
	}
	if a.Status == "cancelled" {
		writeError(w, http.StatusConflict, "assignment_inactive", "assignment is cancelled")
		return
	}
	if a.WorkerID != ac.user.UserID || smp.CurrentHolderID != ac.user.UserID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "record_handling_checkpoint", "sample", smp.SampleID, false, map[string]any{"error": "forbidden"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "forbidden", "only the current holder of the sample can record a handling checkpoint")
		return
	}
	if smp.SealedAt != "" {
		if st, ok := parseTimeRFC3339(smp.SealedAt); ok && recAt.Before(st) {
			writeError(w, http.StatusConflict, "invalid_checkpoint_time", "recordedAt cannot be before sample sealedAt")
			return
		}
	}

	obsTemp := *req.ObservedTemperatureC
	compliant := strings.TrimSpace(*req.ContainerType) == smp.ContainerType && !math.IsNaN(obsTemp) && obsTemp >= smp.TemperatureMinC && obsTemp <= smp.TemperatureMaxC

	cpID := NewUUID()
	recStr := recAt.Format(time.RFC3339)
	if !compliant {
		smp.Status = "exception"
		smp.HandlingCompliant = false
		smp.Exception = map[string]any{
			"checkpointId":         cpID,
			"reason":               "handling_noncompliant",
			"containerType":        *req.ContainerType,
			"observedTemperatureC": obsTemp,
			"recordedAt":           recStr,
		}
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "record_handling_checkpoint", "sample", smp.SampleID, true, recStr, map[string]any{
		"checkpointId":         cpID,
		"compliant":            compliant,
		"containerType":        *req.ContainerType,
		"observedTemperatureC": obsTemp,
	})
	smp.Timeline = append(smp.Timeline, tl)
	a.History = append(a.History, tl)

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "record_handling_checkpoint", "sample", smp.SampleID, true, map[string]any{
		"checkpointId": cpID,
		"compliant":    compliant,
		"sampleStatus": smp.Status,
	})
	srv.store.publishRealtimeLocked("sample.checkpoint", "sample", smp.SampleID, map[string]any{
		"checkpointId": cpID,
		"sampleId":     smp.SampleID,
		"compliant":    compliant,
		"sampleStatus": smp.Status,
	})

	respData := map[string]any{
		"checkpointId": cpID,
		"sampleId":     smp.SampleID,
		"compliant":    compliant,
		"sampleStatus": smp.Status,
	}
	srv.saveIdempotencyLocked("record_handling_checkpoint", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleID       *string `json:"sampleId"`
		LaboratoryID   *string `json:"laboratoryId"`
		ReceivedAt     *string `json:"receivedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleID == nil || req.LaboratoryID == nil || req.ReceivedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "confirm_laboratory_receipt", "sample", *req.SampleID, true, "laboratory_team", "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("confirm_laboratory_receipt", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	recAt, ok := parseTimeRFC3339(*req.ReceivedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid receivedAt")
		return
	}

	smp := srv.store.state.Samples[*req.SampleID]
	lab := srv.store.state.Locations[*req.LaboratoryID]
	if smp == nil || lab == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample or laboratory not found")
		return
	}

	if ac.role == "laboratory_team" && ac.user.AssignedLocationID != lab.LocationID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "confirm_laboratory_receipt", "sample", smp.SampleID, false, map[string]any{"error": "wrong_laboratory_operator"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "wrong_laboratory_operator", "operator is not assigned to this laboratory")
		return
	}

	if !lab.Active || !lab.Functions.Laboratory || !srv.store.labAcceptsSampleTypeLocked(lab.LocationID, smp.SampleTypeID) {
		writeError(w, http.StatusConflict, "laboratory_unavailable", "laboratory is inactive or does not accept this sample type")
		return
	}

	if smp.PendingHandoffID != "" {
		if ho := srv.store.state.Handoffs[smp.PendingHandoffID]; ho != nil && ho.Status == "pending" {
			writeError(w, http.StatusConflict, "pending_handoff_exists", "cannot confirm laboratory receipt while a handoff is still pending")
			return
		}
	}

	if !smp.Sealed {
		writeError(w, http.StatusConflict, "receipt_not_ready", "sample has not been collected and sealed")
		return
	}

	// Verify transport legs are complete and custody is with lab operator
	jp := srv.store.state.Journeys[smp.ActiveJourneyID]
	if jp != nil {
		for _, leg := range jp.Legs {
			a := srv.store.state.Assignments[leg.AssignmentID]
			if a != nil && !isAssignmentCompleted(a.Status) {
				writeError(w, http.StatusConflict, "receipt_not_ready", "transport legs are not yet completed")
				return
			}
		}
	}
	if smp.CurrentHolderID != ac.user.UserID && ac.role != "administrator" {
		writeError(w, http.StatusConflict, "custody_conflict", "laboratory operator must hold confirmed custody of the sample before confirming receipt")
		return
	}

	if smp.SealedAt != "" {
		if st, ok := parseTimeRFC3339(smp.SealedAt); ok && recAt.Before(st) {
			writeError(w, http.StatusConflict, "invalid_receipt_time", "receivedAt cannot be before sample sealedAt")
			return
		}
	}
	if dl, ok := parseTimeRFC3339(smp.DeliveryDeadline); ok && recAt.After(dl) {
		writeError(w, http.StatusConflict, "delivery_deadline_exceeded", "receivedAt is after sample deliveryDeadline")
		return
	}

	recStr := recAt.Format(time.RFC3339)
	smp.Status = "received"
	smp.ReceivedLaboratoryID = lab.LocationID
	smp.ReceivedAt = recStr
	cCopy := lab.Coordinate
	smp.LatestLocation = &cCopy
	smp.LocationRecordedAt = recStr
	smp.LocationStale = false

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "confirm_laboratory_receipt", "sample", smp.SampleID, true, recStr, map[string]any{
		"laboratoryId": lab.LocationID,
		"receivedAt":   recStr,
	})
	smp.Timeline = append(smp.Timeline, tl)

	if jp != nil {
		for _, lid := range jp.LaboratoryAssignmentIDs {
			if la := srv.store.state.Assignments[lid]; la != nil {
				if la.Status != "completed" {
					la.Status = "completed"
					la.LastProgressAt = recStr
					if la.WorkerID != "" {
						if u := srv.store.state.Users[la.WorkerID]; u != nil && u.ReservedUnits > 0 {
							u.ReservedUnits--
						}
					}
				}
				la.History = append(la.History, tl)
			}
		}
		if len(jp.OrderedStops) > 0 {
			jp.OrderedStops[len(jp.OrderedStops)-1].CompletedAt = recStr
		}
		allReceived := true
		for _, sid := range jp.SampleIDs {
			if sOther := srv.store.state.Samples[sid]; sOther != nil && sOther.Status != "received" {
				allReceived = false
				break
			}
		}
		if allReceived {
			jp.Status = "completed"
			srv.store.releaseJourneyCapacityLocked(jp)
		}
		jp.History = append(jp.History, tl)
	}

	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "confirm_laboratory_receipt", "sample", smp.SampleID, true, map[string]any{
		"laboratoryId": lab.LocationID,
		"receivedAt":   recStr,
	})
	srv.store.publishRealtimeLocked("sample.received", "sample", smp.SampleID, map[string]any{
		"sampleId":     smp.SampleID,
		"laboratoryId": lab.LocationID,
		"status":       "received",
		"receivedAt":   recStr,
	})

	respData := map[string]any{
		"sampleId":     smp.SampleID,
		"laboratoryId": lab.LocationID,
		"status":       "received",
		"receivedAt":   recStr,
	}
	srv.saveIdempotencyLocked("confirm_laboratory_receipt", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		SampleID       *string `json:"sampleId"`
		LaboratoryID   *string `json:"laboratoryId"`
		Reason         *string `json:"reason"`
		ObservedAt     *string `json:"observedAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.SampleID == nil || req.LaboratoryID == nil || req.Reason == nil || req.ObservedAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "record_laboratory_exception", "sample", *req.SampleID, true, "laboratory_team", "administrator")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("record_laboratory_exception", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	obsAt, ok := parseTimeRFC3339(*req.ObservedAt)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid observedAt")
		return
	}
	if strings.TrimSpace(*req.Reason) == "" {
		writeError(w, http.StatusBadRequest, "invalid_json", "reason is required")
		return
	}

	smp := srv.store.state.Samples[*req.SampleID]
	lab := srv.store.state.Locations[*req.LaboratoryID]
	if smp == nil || lab == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample or laboratory not found")
		return
	}

	if ac.role == "laboratory_team" && ac.user.AssignedLocationID != lab.LocationID {
		srv.store.recordAuditLocked(ac.user.UserID, ac.role, "record_laboratory_exception", "sample", smp.SampleID, false, map[string]any{"error": "wrong_laboratory_operator"})
		_ = srv.store.saveLocked(r.Context())
		writeError(w, http.StatusForbidden, "wrong_laboratory_operator", "operator is not assigned to this laboratory")
		return
	}
	if smp.TargetLaboratoryID != "" && smp.TargetLaboratoryID != lab.LocationID {
		writeError(w, http.StatusConflict, "wrong_laboratory", "sample is not destined for this laboratory")
		return
	}
	if smp.SealedAt != "" {
		if st, ok := parseTimeRFC3339(smp.SealedAt); ok && obsAt.Before(st) {
			writeError(w, http.StatusConflict, "invalid_exception_time", "observedAt cannot be before sample sealedAt")
			return
		}
	}

	excID := NewUUID()
	obsStr := obsAt.Format(time.RFC3339)
	smp.Status = "exception"
	smp.Exception = map[string]any{
		"exceptionId":  excID,
		"laboratoryId": lab.LocationID,
		"reason":       *req.Reason,
		"observedAt":   obsStr,
	}

	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "record_laboratory_exception", "sample", smp.SampleID, true, obsStr, map[string]any{
		"exceptionId":  excID,
		"laboratoryId": lab.LocationID,
		"reason":       *req.Reason,
	})
	smp.Timeline = append(smp.Timeline, tl)
	if jp := srv.store.state.Journeys[smp.ActiveJourneyID]; jp != nil {
		jp.History = append(jp.History, tl)
	}

	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "record_laboratory_exception", "sample", smp.SampleID, true, map[string]any{
		"exceptionId":  excID,
		"laboratoryId": lab.LocationID,
		"reason":       *req.Reason,
	})
	srv.store.publishRealtimeLocked("sample.exception", "sample", smp.SampleID, map[string]any{
		"exceptionId": excID,
		"sampleId":    smp.SampleID,
		"status":      "exception",
		"reason":      *req.Reason,
	})

	respData := map[string]any{
		"exceptionId": excID,
		"sampleId":    smp.SampleID,
		"status":      "exception",
		"reason":      *req.Reason,
	}
	srv.saveIdempotencyLocked("record_laboratory_exception", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

