package internal

import (
	"encoding/json"
	"net/http"
	"sort"
	"strings"
	"time"
)

func (srv *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		JourneyID *string `json:"journeyId"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.JourneyID == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "read_journey_plan", "journey", *req.JourneyID, true)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	jp := srv.store.state.Journeys[*req.JourneyID]
	if jp == nil {
		writeError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	srv.store.syncJourneyAssignmentsLocked(jp)

	switch ac.role {
	case "administrator", "dispatcher":
		writeData(w, http.StatusOK, jp)
		return

	case "requester":
		owns := false
		for _, sid := range jp.SampleIDs {
			if smp := srv.store.state.Samples[sid]; smp != nil && smp.RequesterID == ac.user.UserID {
				owns = true
				break
			}
		}
		if !owns {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_journey_plan", "journey", jp.JourneyID, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "requester does not own any sample in this journey")
			return
		}
		reqLegs := make([]map[string]any, 0, len(jp.Legs))
		for _, leg := range jp.Legs {
			reqLegs = append(reqLegs, map[string]any{
				"sequence":       leg.Sequence,
				"status":         leg.Status,
				"fromLocationId": leg.FromLocationID,
				"toLocationId":   leg.ToLocationID,
			})
		}
		rjp := RequesterJourneyPlan{
			JourneyID:           jp.JourneyID,
			ParentJourneyID:     jp.ParentJourneyID,
			PlanVersion:         jp.PlanVersion,
			RouteMode:           jp.RouteMode,
			Status:              jp.Status,
			EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
			TotalCostUnits:      jp.TotalCostUnits,
			SampleIDs:           jp.SampleIDs,
			OrderedStops:        jp.OrderedStops,
			Legs:                reqLegs,
		}
		writeData(w, http.StatusOK, rjp)
		return

	default:
		var myAssignIDs []string
		var myLegs []JourneyLeg
		stopLocSet := map[string]bool{}
		var myColIDs, myNodeIDs, myLabIDs []string

		for _, cid := range jp.CollectionAssignmentIDs {
			if a := srv.store.state.Assignments[cid]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, cid)
				myColIDs = append(myColIDs, cid)
				stopLocSet[a.ToLocationID] = true
			}
		}
		for _, leg := range jp.Legs {
			if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, leg.AssignmentID)
				myLegs = append(myLegs, leg)
				stopLocSet[leg.FromLocationID] = true
				stopLocSet[leg.ToLocationID] = true
			}
		}
		for _, nid := range jp.NodeAssignmentIDs {
			if a := srv.store.state.Assignments[nid]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, nid)
				myNodeIDs = append(myNodeIDs, nid)
				stopLocSet[a.NodeID] = true
			}
		}
		for _, lid := range jp.LaboratoryAssignmentIDs {
			if a := srv.store.state.Assignments[lid]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, lid)
				myLabIDs = append(myLabIDs, lid)
				stopLocSet[a.LaboratoryID] = true
			}
		}

		if len(myAssignIDs) == 0 {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_journey_plan", "journey", jp.JourneyID, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "worker has no assignments on this journey")
			return
		}
		if myLegs == nil {
			myLegs = []JourneyLeg{}
		}
		var myStops []JourneyStop
		for _, st := range jp.OrderedStops {
			if stopLocSet[st.LocationID] {
				myStops = append(myStops, st)
			}
		}
		if myStops == nil {
			myStops = []JourneyStop{}
		}

		wjp := WorkerJourneyPlan{
			JourneyID:               jp.JourneyID,
			ParentJourneyID:         jp.ParentJourneyID,
			PlanVersion:             jp.PlanVersion,
			RouteMode:               jp.RouteMode,
			Status:                  jp.Status,
			EstimatedDeliveryAt:     jp.EstimatedDeliveryAt,
			Scope:                   "assigned_legs",
			AssignmentIDs:           myAssignIDs,
			SampleIDs:               jp.SampleIDs,
			Legs:                    myLegs,
			OrderedStops:            myStops,
			CollectionAssignmentIDs: myColIDs,
			NodeAssignmentIDs:       myNodeIDs,
			LaboratoryAssignmentIDs: myLabIDs,
			AssignedWorkerIDs:       []string{ac.user.UserID},
		}
		writeData(w, http.StatusOK, wjp)
	}
}

func (srv *Server) buildOperationsStateLocked(filterSampleTypeID string) OperationsState {
	samples := []OperationsSample{}
	sIDs := make([]string, 0, len(srv.store.state.Samples))
	for id := range srv.store.state.Samples {
		sIDs = append(sIDs, id)
	}
	sort.Strings(sIDs)
	for _, id := range sIDs {
		smp := srv.store.state.Samples[id]
		if filterSampleTypeID != "" && smp.SampleTypeID != filterSampleTypeID {
			continue
		}
		srv.refreshSampleStaleLocked(smp)
		orig := smp.Origin
		samples = append(samples, OperationsSample{
			SampleID:           smp.SampleID,
			SampleIDSnake:      smp.SampleID,
			Status:             smp.Status,
			RequestID:          smp.RequestID,
			Origin:             &orig,
			DeliveryDeadline:   smp.DeliveryDeadline,
			CurrentHolderID:    smp.CurrentHolderID,
			ActiveJourneyID:    smp.ActiveJourneyID,
			LatestLocation:     smp.LatestLocation,
			LocationRecordedAt: smp.LocationRecordedAt,
			LocationStale:      smp.LocationStale,
		})
	}

	workers := []OperationsWorker{}
	uIDs := make([]string, 0, len(srv.store.state.Users))
	for id := range srv.store.state.Users {
		uIDs = append(uIDs, id)
	}
	sort.Strings(uIDs)
	minAssign := -1
	maxAssign := -1
	for _, id := range uIDs {
		u := srv.store.state.Users[id]
		isWorker := false
		for _, rName := range u.Roles {
			if rName == "collection_professional" || rName == "delivery_partner" || rName == "node_handler" || rName == "laboratory_team" {
				isWorker = true
				break
			}
		}
		if !isWorker {
			continue
		}
		stStr := "unavailable"
		if u.Available && u.Active {
			stStr = "available"
		}
		locStale := false
		if u.LocationRecordedAt != "" {
			if t, ok := parseTimeRFC3339(u.LocationRecordedAt); ok {
				locStale = time.Since(t) > StaleLocationMinutes
			}
		}
		workers = append(workers, OperationsWorker{
			WorkerID:           u.UserID,
			WorkerIDSnake:      u.UserID,
			FullName:           u.FullName,
			Roles:              u.Roles,
			Available:          u.Available && u.Active,
			Status:             stStr,
			CapacityUnits:      u.CapacityUnits,
			AssignmentCount:    u.AssignmentCount,
			LatestLocation:     u.LatestLocation,
			LatestLocSnake:     u.LatestLocation,
			LocationRecordedAt: u.LocationRecordedAt,
			LocationStale:      locStale,
		})
		if u.Available && u.Active {
			if minAssign == -1 || u.AssignmentCount < minAssign {
				minAssign = u.AssignmentCount
			}
			if maxAssign == -1 || u.AssignmentCount > maxAssign {
				maxAssign = u.AssignmentCount
			}
		}
	}
	spread := 0
	if minAssign >= 0 && maxAssign >= minAssign {
		spread = maxAssign - minAssign
	}

	locations := []OperationsLocation{}
	locIDs := make([]string, 0, len(srv.store.state.Locations))
	for id := range srv.store.state.Locations {
		locIDs = append(locIDs, id)
	}
	sort.Strings(locIDs)
	for _, id := range locIDs {
		loc := srv.store.state.Locations[id]
		c := srv.store.getLocationCapacityLocked(loc)
		var accTypes []string
		for stID := range srv.store.state.LabAcceptances[id] {
			accTypes = append(accTypes, stID)
		}
		sort.Strings(accTypes)
		if accTypes == nil {
			accTypes = []string{}
		}
		locations = append(locations, OperationsLocation{
			ID:                    loc.LocationID,
			LocationID:            loc.LocationID,
			Name:                  loc.Name,
			Coordinate:            loc.Coordinate,
			Active:                loc.Active,
			CoverageKm:            loc.CoverageKm,
			HandlingMinutes:       loc.HandlingMinutes,
			Functions:             loc.Functions,
			Capacity:              &c,
			AcceptedSampleTypeIDs: accTypes,
		})
	}

	connections := []OperationsConnection{}
	cIDs := make([]string, 0, len(srv.store.state.Connections))
	for id := range srv.store.state.Connections {
		cIDs = append(cIDs, id)
	}
	sort.Strings(cIDs)
	for _, id := range cIDs {
		conn := srv.store.state.Connections[id]
		c := srv.store.getConnectionCapacityLocked(conn)
		connections = append(connections, OperationsConnection{
			ID:             conn.ConnectionID,
			ConnectionID:   conn.ConnectionID,
			FromLocationID: conn.FromLocationID,
			ToLocationID:   conn.ToLocationID,
			TravelMinutes:  conn.TravelMinutes,
			CostUnits:      conn.CostUnits,
			Cooled:         conn.Cooled,
			Active:         conn.Active,
			Capacity:       &c,
		})
	}

	routes := []map[string]any{}
	delays := []map[string]any{}
	jIDs := make([]string, 0, len(srv.store.state.Journeys))
	for id := range srv.store.state.Journeys {
		jIDs = append(jIDs, id)
	}
	sort.Strings(jIDs)
	for _, id := range jIDs {
		jp := srv.store.state.Journeys[id]
		if filterSampleTypeID != "" {
			matched := false
			for _, sid := range jp.SampleIDs {
				if smp := srv.store.state.Samples[sid]; smp != nil && smp.SampleTypeID == filterSampleTypeID {
					matched = true
					break
				}
			}
			if !matched {
				continue
			}
		}
		routes = append(routes, map[string]any{
			"journeyId":           jp.JourneyID,
			"status":              jp.Status,
			"routeMode":           jp.RouteMode,
			"planVersion":         jp.PlanVersion,
			"sampleIds":           jp.SampleIDs,
			"orderedStops":        jp.OrderedStops,
			"legs":                jp.Legs,
			"estimatedDeliveryAt": jp.EstimatedDeliveryAt,
		})
	}

	handoffs := []map[string]any{}
	for _, ho := range srv.store.state.Handoffs {
		handoffs = append(handoffs, map[string]any{
			"handoffId":         ho.HandoffID,
			"sampleId":          ho.SampleID,
			"senderId":          ho.SenderID,
			"receiverId":        ho.ReceiverID,
			"currentHolderId":   ho.CurrentHolderID,
			"status":            ho.Status,
			"senderConfirmed":   ho.SenderConfirmed,
			"receiverConfirmed": ho.ReceiverConfirmed,
		})
	}

	exceptions := []map[string]any{}
	for _, id := range sIDs {
		smp := srv.store.state.Samples[id]
		if filterSampleTypeID != "" && smp.SampleTypeID != filterSampleTypeID {
			continue
		}
		if smp.Status == "exception" || smp.Status == "expired" || smp.Exception != nil {
			excObj := map[string]any{
				"sampleId": smp.SampleID,
				"status":   smp.Status,
			}
			for k, v := range smp.Exception {
				excObj[k] = v
			}
			exceptions = append(exceptions, excObj)
		}
	}

	return OperationsState{
		Samples:                   samples,
		Workers:                   workers,
		Locations:                 locations,
		Connections:               connections,
		Routes:                    routes,
		Handoffs:                  handoffs,
		Delays:                    delays,
		Exceptions:                exceptions,
		AssignmentCountSpread:     spread,
		IneligibleAssignmentCount: 0,
	}
}

func (srv *Server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Filters *struct {
			SampleTypeID      string `json:"sampleTypeId"`
			SampleTypeIDSnake string `json:"sample_type_id"`
		} `json:"filters"`
	}
	if len(strings.TrimSpace(string(raw))) > 0 {
		if err := decodeStrictJSON(raw, &req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
			return
		}
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	_, authErr := srv.requireRoleLocked(r, "read_operations_state", "operations", "state", true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	filterST := ""
	if req.Filters != nil {
		if req.Filters.SampleTypeID != "" {
			filterST = req.Filters.SampleTypeID
		} else if req.Filters.SampleTypeIDSnake != "" {
			filterST = req.Filters.SampleTypeIDSnake
		}
	}

	ops := srv.buildOperationsStateLocked(filterST)
	writeData(w, http.StatusOK, ops)
}

