		return
	}
	if jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "journey is already inactive")
		return
	}

	var primarySample *Sample
	if len(jp.SampleIDs) > 0 {
		primarySample = srv.store.state.Samples[jp.SampleIDs[0]]
	}
	if primarySample == nil {
		writeError(w, http.StatusNotFound, "not_found", "sample for journey not found")
		return
	}

	replanStatus, newJP := srv.store.replanSampleJourneyLocked(primarySample, jp, ac.user.UserID, ac.role, req.Reason)
	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "reroute_journey", "journey", jp.JourneyID, true, map[string]any{
