	})

	respData := map[string]any{
		"journeyId":    jp.JourneyID,
		"replanStatus": replanStatus,
	}
	if newJP != nil {
		respData["replacementPlanId"] = newJP.JourneyID
		respData["replacementJourney"] = newJP
	}

	srv.saveIdempotencyLocked("reroute_journey", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		ResourceType   *string `json:"resourceType"`
		ResourceID     *string `json:"resourceId"`
		Reason         string  `json:"reason"`
		OccurredAt     *string `json:"occurredAt"`
		IdempotencyKey *string `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.ResourceType == nil || req.ResourceID == nil || req.OccurredAt == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "report_disruption", "disruption", *req.ResourceID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("report_disruption", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	if _, ok := parseTimeRFC3339(*req.OccurredAt); !ok {
		writeError(w, http.StatusBadRequest, "invalid_time", "invalid occurredAt")
		return
	}

	resType := strings.TrimSpace(*req.ResourceType)
	resID := strings.TrimSpace(*req.ResourceID)
	switch resType {
	case "location", "node", "laboratory":
		loc := srv.store.state.Locations[resID]
		if loc == nil {
			writeError(w, http.StatusNotFound, "not_found", "location not found")
			return
		}
		if resType == "laboratory" {
			loc.Functions.Laboratory = false
		} else {
			loc.Active = false
		}
	case "connection", "route":
		conn := srv.store.state.Connections[resID]
		if conn == nil {
			writeError(w, http.StatusNotFound, "not_found", "connection not found")
			return
		}
		conn.Active = false
	case "worker":
		u := srv.store.state.Users[resID]
		if u == nil {
			writeError(w, http.StatusNotFound, "not_found", "worker not found")
			return
		}
		u.Available = false
	case "capacity":
		if loc := srv.store.state.Locations[resID]; loc != nil {
			loc.CapacityConfigured = true
			loc.Capacity.CapacityUnits = loc.Capacity.ReservedUnits
			loc.Capacity.CooledCapacityUnits = loc.Capacity.CooledReservedUnits
		} else if conn := srv.store.state.Connections[resID]; conn != nil {
			conn.CapacityConfigured = true
			conn.Capacity.CapacityUnits = conn.Capacity.ReservedUnits
			conn.Capacity.CooledCapacityUnits = conn.Capacity.CooledReservedUnits
		} else {
			writeError(w, http.StatusNotFound, "not_found", "capacity resource not found")
			return
		}
	default:
		writeError(w, http.StatusBadRequest, "invalid_resource_type", "invalid resourceType")
		return
	}

	affectedSamples := []string{}
	replacementPlans := []string{}
	overallStatus := "not_required"

	jIDs := make([]string, 0, len(srv.store.state.Journeys))
	for id := range srv.store.state.Journeys {
		jIDs = append(jIDs, id)
	}
	sort.Strings(jIDs)

	for _, jid := range jIDs {
		jp := srv.store.state.Journeys[jid]
		if jp == nil || jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
			continue
		}
		affected := false
		switch resType {
		case "location", "node", "laboratory", "capacity":
			for _, leg := range jp.Legs {
				a := srv.store.state.Assignments[leg.AssignmentID]
				if a != nil && !isAssignmentCompleted(a.Status) {
					if leg.FromLocationID == resID || leg.ToLocationID == resID {
						affected = true
						break
					}
				}
			}
			for _, st := range jp.OrderedStops {
				if st.CompletedAt == "" && st.LocationID == resID {
					affected = true
					break
				}
			}
		case "connection", "route":
			for _, leg := range jp.Legs {
				a := srv.store.state.Assignments[leg.AssignmentID]
				if a != nil && !isAssignmentCompleted(a.Status) && leg.ConnectionID == resID {
					affected = true
					break
				}
			}
		case "worker":
			for _, aid := range append(append(append([]string{}, jp.CollectionAssignmentIDs...), jp.NodeAssignmentIDs...), jp.LaboratoryAssignmentIDs...) {
				if a := srv.store.state.Assignments[aid]; a != nil && !isAssignmentCompleted(a.Status) && (a.WorkerID == resID || a.OfferedToWorkerID == resID) {
					affected = true
					break
				}
			}
			for _, leg := range jp.Legs {
				if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && !isAssignmentCompleted(a.Status) && (a.WorkerID == resID || a.OfferedToWorkerID == resID) {
					affected = true
					break
				}
			}
		}

		if !affected {
			continue
		}

		for _, sid := range jp.SampleIDs {
			smp := srv.store.state.Samples[sid]
			if smp == nil || smp.Status == "received" || smp.Status == "cancelled" {
				continue
			}
			affectedSamples = append(affectedSamples, sid)
			st, newJP := srv.store.replanSampleJourneyLocked(smp, jp, ac.user.UserID, ac.role, req.Reason)
			if newJP != nil {
				replacementPlans = append(replacementPlans, newJP.JourneyID)
			}
			if st == "expired" {
				overallStatus = "expired"
			} else if st == "exception" && overallStatus != "expired" {
				overallStatus = "exception"
			} else if st == "replaced" && overallStatus == "not_required" {
				overallStatus = "replaced"
			}
		}
	}

	disruptionID := NewUUID()
	srv.store.recomputeServiceabilityLocked(true)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "report_disruption", resType, resID, true, map[string]any{
		"disruptionId":      disruptionID,
		"affectedSampleIds": affectedSamples,
		"replanStatus":      overallStatus,
	})
	srv.store.publishRealtimeLocked("disruption.reported", "disruption", disruptionID, map[string]any{
		"disruptionId":      disruptionID,
		"resourceType":      resType,
		"resourceId":        resID,
		"affectedSampleIds": affectedSamples,
		"replanStatus":      overallStatus,
	})

	respData := map[string]any{
		"disruptionId":       disruptionID,
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementPlans,
		"replanStatus":       overallStatus,
	}
	srv.saveIdempotencyLocked("report_disruption", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		TargetJourneyID     *string  `json:"targetJourneyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.TargetJourneyID == nil || req.ExpectedPlanVersion == nil || req.SourceJourneyIDs == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "merge_journeys", "journey", *req.TargetJourneyID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("merge_journeys", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	if len(req.SourceJourneyIDs) == 0 {
		writeError(w, http.StatusConflict, "invalid_merge", "sourceJourneyIds cannot be empty")
		return
	}

	targetJP := srv.store.state.Journeys[*req.TargetJourneyID]
	if targetJP == nil {
		writeError(w, http.StatusNotFound, "not_found", "target journey not found")
		return
	}
	if targetJP.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "target journey planVersion does not match expectedPlanVersion")
		return
	}
	if targetJP.Status == "cancelled" || targetJP.Status == "completed" || targetJP.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "target journey is inactive")
		return
	}

	for _, leg := range targetJP.Legs {
		if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && (isAssignmentCompleted(a.Status) || isAssignmentInProgress(a.Status)) {
			writeError(w, http.StatusConflict, "completed_work_immutable", "cannot merge journey with in-progress or completed transport legs")
			return
		}
	}

	mergedSampleIDs := append([]string{}, targetJP.SampleIDs...)
	var sourceJPs []*JourneyPlan
	for _, srcID := range req.SourceJourneyIDs {
		if srcID == targetJP.JourneyID {
			writeError(w, http.StatusConflict, "invalid_merge", "cannot merge journey into itself")
			return
		}
		sjp := srv.store.state.Journeys[srcID]
		if sjp == nil {
			writeError(w, http.StatusNotFound, "not_found", "source journey not found")
			return
		}
		if sjp.Status == "cancelled" || sjp.Status == "completed" || sjp.Status == "replaced" {
			writeError(w, http.StatusConflict, "inactive_plan", "source journey is inactive")
			return
		}
		for _, leg := range sjp.Legs {
			if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && (isAssignmentCompleted(a.Status) || isAssignmentInProgress(a.Status)) {
				writeError(w, http.StatusConflict, "partial_journey_merge", "cannot merge source journey that already has completed or in-progress transport work")
				return
			}
		}
		sourceJPs = append(sourceJPs, sjp)
		mergedSampleIDs = append(mergedSampleIDs, sjp.SampleIDs...)
	}

	// Temporarily release source journey capacities to test if merged target journey fits
	for _, sjp := range sourceJPs {
		srv.store.releaseJourneyCapacityLocked(sjp)
	}

	origSamples := append([]string{}, targetJP.SampleIDs...)
	targetJP.SampleIDs = mergedSampleIDs

	if valErr := srv.store.recalculateStopsAndValidatePlanLocked(targetJP); valErr != nil {
		// Restore original state
		targetJP.SampleIDs = origSamples
		for _, sjp := range sourceJPs {
			needsCooled := false
			for _, sid := range sjp.SampleIDs {
				if smp := srv.store.state.Samples[sid]; smp != nil {
					if srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID]) {
						needsCooled = true
					}
				}
			}
			srv.store.reserveJourneyCapacityLocked(sjp, needsCooled, len(sjp.SampleIDs))
		}
		writeError(w, valErr.status, valErr.code, valErr.msg)
		return
	}

	// Commit merge: update capacity reservation on targetJP and cancel source journeys
	srv.store.releaseJourneyCapacityLocked(targetJP)
	needsCooled := false
	for _, sid := range targetJP.SampleIDs {
		if smp := srv.store.state.Samples[sid]; smp != nil {
			if srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID]) {
				needsCooled = true
			}
		}
	}
	srv.store.reserveJourneyCapacityLocked(targetJP, needsCooled, len(targetJP.SampleIDs))

	for _, sjp := range sourceJPs {
		_, _ = srv.store.cancelUnfinishedAssignmentsLocked(sjp)
		sjp.Status = "replaced"
		for _, sid := range sjp.SampleIDs {
			if smp := srv.store.state.Samples[sid]; smp != nil {
				smp.ActiveJourneyID = targetJP.JourneyID
			}
		}
	}

	targetJP.RouteMode = "batched"
	targetJP.PlanVersion++
	validTrue := true
	targetJP.Valid = &validTrue

	nowStr := time.Now().UTC().Format(time.RFC3339)
	tl := srv.store.newTimelineEntryLocked(ac.user.UserID, ac.role, "merge_journeys", "journey", targetJP.JourneyID, true, nowStr, map[string]any{
		"sourceJourneyIds": req.SourceJourneyIDs,
		"sampleIds":        targetJP.SampleIDs,
	})
	targetJP.History = append(targetJP.History, tl)

	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "merge_journeys", "journey", targetJP.JourneyID, true, map[string]any{
		"sourceJourneyIds": req.SourceJourneyIDs,
		"sampleIds":        targetJP.SampleIDs,
	})

	srv.saveIdempotencyLocked("merge_journeys", *req.IdempotencyKey, raw, http.StatusCreated, targetJP)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, targetJP)
}

func (srv *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		JourneyID           *string  `json:"journeyId"`
		ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      *string  `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.SampleIDs == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "split_journey", "journey", *req.JourneyID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("split_journey", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	jp := srv.store.state.Journeys[*req.JourneyID]
	if jp == nil {
		writeError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if jp.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "journey planVersion does not match expectedPlanVersion")
		return
	}
	if jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "journey is inactive")
		return
	}

	splitJP, apiErr := srv.performSplitLocked(jp, req.SampleIDs, ac.user.UserID, ac.role)
	if apiErr != nil {
		writeError(w, apiErr.status, apiErr.code, apiErr.msg)
		return
	}

	respData := map[string]any{
		"journey":      jp,
		"splitJourney": splitJP,
	}
	srv.saveIdempotencyLocked("split_journey", *req.IdempotencyKey, raw, http.StatusCreated, respData)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, respData)
}

func (srv *Server) performSplitLocked(jp *JourneyPlan, splitSampleIDs []string, actorID, role string) (*JourneyPlan, *apiError) {
	if len(splitSampleIDs) == 0 || len(splitSampleIDs) >= len(jp.SampleIDs) {
		return nil, newErr(http.StatusConflict, "invalid_split", "split sampleIds must be a non-empty proper subset of journey sampleIds")
	}
	inJourney := map[string]bool{}
	for _, sid := range jp.SampleIDs {
		inJourney[sid] = true
	}
	splitSet := map[string]bool{}
	for _, sid := range splitSampleIDs {
		if !inJourney[sid] {
			return nil, newErr(http.StatusConflict, "invalid_split", "sampleId does not belong to journey")
		}
		splitSet[sid] = true
	}

	for _, leg := range jp.Legs {
		if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && isAssignmentInProgress(a.Status) {
			return nil, newErr(http.StatusConflict, "split_in_progress", "cannot split a leg currently in progress")
		}
	}

	var remaining []string
	for _, sid := range jp.SampleIDs {
		if !splitSet[sid] {
			remaining = append(remaining, sid)
		}
	}

	// Release capacity on parent and rebuild for remaining + split
	srv.store.releaseJourneyCapacityLocked(jp)
	jp.SampleIDs = remaining
	jp.CapacityUsed = len(remaining)
	if len(remaining) == 1 {
		if len(jp.Legs) > 1 {
			jp.RouteMode = "multi_stop"
		} else {
			jp.RouteMode = "direct"
		}
	}
	jp.PlanVersion++

	needsCooledRem := false
	for _, sid := range remaining {
		if smp := srv.store.state.Samples[sid]; smp != nil {
			if srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID]) {
				needsCooledRem = true
			}
		}
	}
	srv.store.reserveJourneyCapacityLocked(jp, needsCooledRem, len(remaining))

	// Create splitJourney for the split samples
	firstSplitSample := srv.store.state.Samples[splitSampleIDs[0]]
	startLocID, baseTime := srv.store.findCurrentLocationOfSampleLocked(firstSplitSample, jp)
	dl, _ := time.Parse(time.RFC3339, firstSplitSample.DeliveryDeadline)
	st := srv.store.state.SampleTypes[firstSplitSample.SampleTypeID]

	ok, _, rc := srv.store.evaluateServiceabilityLocked(
		firstSplitSample.Origin,
		firstSplitSample.OriginType,
		firstSplitSample.OriginNodeID,
		st,
		baseTime,
		dl,
		len(splitSampleIDs),
		startLocID,
	)
	if !ok || rc == nil {
		return nil, newErr(http.StatusConflict, "no_valid_route", "unable to route split journey")
	}

	splitJP := srv.store.buildJourneyPlanForSampleLocked(firstSplitSample, rc, baseTime, firstSplitSample.Sealed, actorID, role)
	splitJP.ParentJourneyID = jp.JourneyID
	splitJP.SampleIDs = append([]string{}, splitSampleIDs...)
	splitJP.CapacityUsed = len(splitSampleIDs)
	if len(splitSampleIDs) > 1 {
		splitJP.RouteMode = "batched"
	}
	for _, sid := range splitSampleIDs {
		if smp := srv.store.state.Samples[sid]; smp != nil {
			smp.ActiveJourneyID = splitJP.JourneyID
		}
	}
	jp.SplitJourney = splitJP

	srv.store.recordAuditLocked(actorID, role, "split_journey", "journey", jp.JourneyID, true, map[string]any{
		"splitJourneyId": splitJP.JourneyID,
		"splitSampleIds": splitSampleIDs,
	})
	return splitJP, nil
}

func (srv *Server) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		JourneyID           *string        `json:"journeyId"`
		ExpectedPlanVersion *int           `json:"expectedPlanVersion"`
		ChangeType          *string        `json:"changeType"`
		Changes             map[string]any `json:"changes"`
		IdempotencyKey      *string        `json:"idempotencyKey"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.JourneyID == nil || req.ExpectedPlanVersion == nil || req.ChangeType == nil || req.Changes == nil || req.IdempotencyKey == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "edit_active_plan", "journey", *req.JourneyID, true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	if *req.ExpectedPlanVersion < 1 {
		writeError(w, http.StatusBadRequest, "invalid_plan_version", "expectedPlanVersion must be >= 1")
		return
	}

	rec, idempErr := srv.checkIdempotencyLocked("edit_active_plan", *req.IdempotencyKey, raw)
	if idempErr != nil {
		writeError(w, idempErr.status, idempErr.code, idempErr.msg)
		return
	}
	if rec != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.StatusCode)
		_, _ = w.Write(rec.Response)
		return
	}

	changeType := strings.TrimSpace(*req.ChangeType)
	switch changeType {
	case "add_stop", "remove_stop", "reorder_stops", "replace_worker", "reassign_worker", "merge_samples", "split_samples", "split_batch", "cancel_work", "reroute", "replace_route":
	default:
		writeError(w, http.StatusBadRequest, "invalid_change_type", "unsupported changeType")
		return
	}

	jp := srv.store.state.Journeys[*req.JourneyID]
	if jp == nil {
		writeError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	if jp.PlanVersion != *req.ExpectedPlanVersion {
		writeError(w, http.StatusConflict, "stale_plan", "journey planVersion does not match expectedPlanVersion")
		return
	}
	if jp.Status == "cancelled" || jp.Status == "completed" || jp.Status == "replaced" {
		writeError(w, http.StatusConflict, "inactive_plan", "journey is inactive")
		return
	}

	// Snapshot current stops in case validation fails
	origStopsBytes, _ := json.Marshal(jp.OrderedStops)
	var origStops []JourneyStop
	_ = json.Unmarshal(origStopsBytes, &origStops)

	switch changeType {
	case "replace_worker", "reassign_worker":
		assignID, _ := req.Changes["assignmentId"].(string)
		workerID, _ := req.Changes["workerId"].(string)
		if workerID == "" {
			workerID, _ = req.Changes["newWorkerId"].(string)
		}
		if !isValidUUID(assignID) || !isValidUUID(workerID) {
			writeError(w, http.StatusBadRequest, "invalid_worker", "invalid assignmentId or workerId")
			return
		}
		a := srv.store.state.Assignments[assignID]
		u := srv.store.state.Users[workerID]
		if a == nil || u == nil {
			writeError(w, http.StatusNotFound, "not_found", "assignment or worker not found")
			return
		}
		if isAssignmentCompleted(a.Status) {
			writeError(w, http.StatusConflict, "completed_work_immutable", "cannot reassign a completed assignment")
			return
		}
		elig, certOK := srv.store.isWorkerEligibleForAssignmentLocked(u, a, time.Now().UTC())
		if !elig || !certOK {
			writeError(w, http.StatusConflict, "ineligible_worker", "replacement worker is not eligible for assignment")
			return
		}
		if !u.Available || u.ReservedUnits >= u.CapacityUnits {
			writeError(w, http.StatusConflict, "worker_unavailable", "replacement worker is unavailable or at capacity")
			return
		}
		if a.WorkerID != "" && a.Status == "accepted" {
			if oldU := srv.store.state.Users[a.WorkerID]; oldU != nil && oldU.ReservedUnits > 0 {
				oldU.ReservedUnits--
			}
		}
		a.OfferedToWorkerID = u.UserID
		a.WorkerID = u.UserID
		a.Status = "offered"
		a.OfferExpiresAt = time.Now().UTC().Add(OfferExpiryDuration).Format(time.RFC3339)
		srv.store.syncJourneyAssignmentsLocked(jp)
		jp.PlanVersion++

	case "add_stop":
		locID, _ := req.Changes["locationId"].(string)
		stopType, _ := req.Changes["stopType"].(string)
		if stopType == "" {
			stopType = "handoff"
		}
		dwell := 0
		if dVal, ok := req.Changes["dwellMinutes"].(float64); ok {
			dwell = int(dVal)
		}
		if dwell < 0 {
			writeError(w, http.StatusBadRequest, "invalid_dwell", "dwellMinutes cannot be negative")
			return
		}
		seq := len(jp.OrderedStops) // default insert before delivery stop
		if sVal, ok := req.Changes["sequence"].(float64); ok {
			seq = int(sVal)
		}
		if seq < 1 || seq > len(jp.OrderedStops)+1 {
			writeError(w, http.StatusConflict, "invalid_stop_order", "invalid sequence for add_stop")
			return
		}
		// Check if inserting before a completed stop
		for _, existing := range jp.OrderedStops {
			if existing.CompletedAt != "" && seq <= existing.Sequence {
				writeError(w, http.StatusConflict, "completed_work_immutable", "cannot insert stop before completed stop")
				return
			}
		}
		newStop := JourneyStop{
			StopID:          NewUUID(),
			LocationID:      locID,
			LocationIDSnake: locID,
			StopType:        stopType,
			StopTypeSnake:   stopType,
			Sequence:        seq,
			DwellMinutes:    dwell,
		}
		idx := seq - 1
		updated := make([]JourneyStop, 0, len(jp.OrderedStops)+1)
		updated = append(updated, jp.OrderedStops[:idx]...)
		updated = append(updated, newStop)
		updated = append(updated, jp.OrderedStops[idx:]...)
		jp.OrderedStops = updated
		if valErr := srv.store.recalculateStopsAndValidatePlanLocked(jp); valErr != nil {
			jp.OrderedStops = origStops
			writeError(w, valErr.status, valErr.code, valErr.msg)
			return
		}
		srv.rebuildUnfinishedLegsFromStopsLocked(jp, ac.user.UserID, ac.role)
		jp.PlanVersion++

	case "remove_stop":
		stopID, _ := req.Changes["stopId"].(string)
		locID, _ := req.Changes["locationId"].(string)
		var updated []JourneyStop
		found := false
		for _, st := range jp.OrderedStops {
			if (stopID != "" && st.StopID == stopID) || (locID != "" && st.LocationID == locID) {
				if st.CompletedAt != "" {
					writeError(w, http.StatusConflict, "completed_work_immutable", "cannot remove a completed stop")
					return
				}
				found = true
				continue
			}
			updated = append(updated, st)
		}
		if !found {
			writeError(w, http.StatusConflict, "invalid_stop", "stop to remove not found")
			return
		}
		jp.OrderedStops = updated
		if valErr := srv.store.recalculateStopsAndValidatePlanLocked(jp); valErr != nil {
			jp.OrderedStops = origStops
			writeError(w, valErr.status, valErr.code, valErr.msg)
			return
		}
		srv.rebuildUnfinishedLegsFromStopsLocked(jp, ac.user.UserID, ac.role)
		jp.PlanVersion++

	case "reorder_stops", "reroute", "replace_route":
		var newLocIDs []string
		if rawLocs, ok := req.Changes["locationIds"].([]any); ok {
			for _, v := range rawLocs {
				if s, ok := v.(string); ok {
					newLocIDs = append(newLocIDs, s)
				}
			}
		} else if rawStops, ok := req.Changes["stopIds"].([]any); ok {
			stopMap := map[string]JourneyStop{}
			for _, st := range jp.OrderedStops {
				stopMap[st.StopID] = st
			}
			for _, v := range rawStops {
				if sid, ok := v.(string); ok {
					if st, exists := stopMap[sid]; exists {
						newLocIDs = append(newLocIDs, st.LocationID)
					} else if _, locExists := srv.store.state.Locations[sid]; locExists {
						newLocIDs = append(newLocIDs, sid)
					} else {
						writeError(w, http.StatusConflict, "invalid_stop", "stopId not found in journey")
						return
					}
				}
			}
		} else if rawStopsObjs, ok := req.Changes["orderedStops"].([]any); ok {
			for _, v := range rawStopsObjs {
				if m, ok := v.(map[string]any); ok {
					if lid, ok := m["locationId"].(string); ok {
						newLocIDs = append(newLocIDs, lid)
					}
				}
			}
		}
		if len(newLocIDs) == 0 {
			// Fallback to automatic reroute
			if len(jp.SampleIDs) > 0 {
				if smp := srv.store.state.Samples[jp.SampleIDs[0]]; smp != nil {
					_, newJP := srv.store.replanSampleJourneyLocked(smp, jp, ac.user.UserID, ac.role, "edit_active_plan")
					if newJP != nil {
						jp = newJP
					}
				}
			}
		} else {
			// Verify completed stops remain in place
			for idx, st := range jp.OrderedStops {
				if st.CompletedAt != "" {
					if idx >= len(newLocIDs) || newLocIDs[idx] != st.LocationID {
						writeError(w, http.StatusConflict, "completed_work_immutable", "cannot reorder or replace completed stops")
						return
					}
				}
			}
			var updated []JourneyStop
			for idx, lid := range newLocIDs {
				sType := "handoff"
				if idx == 0 {
					sType = "pickup"
				} else if idx == len(newLocIDs)-1 {
					sType = "delivery"
				}
				updated = append(updated, JourneyStop{
					StopID:          NewUUID(),
					LocationID:      lid,
					LocationIDSnake: lid,
					StopType:        sType,
					StopTypeSnake:   sType,
					Sequence:        idx + 1,
				})
			}
			jp.OrderedStops = updated
			if valErr := srv.store.recalculateStopsAndValidatePlanLocked(jp); valErr != nil {
				jp.OrderedStops = origStops
				writeError(w, valErr.status, valErr.code, valErr.msg)
				return
			}
			srv.rebuildUnfinishedLegsFromStopsLocked(jp, ac.user.UserID, ac.role)
			jp.PlanVersion++
		}

	case "split_samples", "split_batch":
		var splitIDs []string
		if rawIDs, ok := req.Changes["sampleIds"].([]any); ok {
			for _, v := range rawIDs {
				if s, ok := v.(string); ok {
					splitIDs = append(splitIDs, s)
				}
			}
		}
		_, apiErr := srv.performSplitLocked(jp, splitIDs, ac.user.UserID, ac.role)
		if apiErr != nil {
			writeError(w, apiErr.status, apiErr.code, apiErr.msg)
			return
		}

	case "merge_samples":
		var addSampleIDs []string
		if rawIDs, ok := req.Changes["sampleIds"].([]any); ok {
			for _, v := range rawIDs {
				if s, ok := v.(string); ok {
					addSampleIDs = append(addSampleIDs, s)
				}
			}
		}
		if len(addSampleIDs) == 0 {
			writeError(w, http.StatusConflict, "invalid_batch", "sampleIds required for merge_samples")
			return
		}
		origSamples := append([]string{}, jp.SampleIDs...)
		jp.SampleIDs = sortStringsUnique(append(jp.SampleIDs, addSampleIDs...))
		if valErr := srv.store.recalculateStopsAndValidatePlanLocked(jp); valErr != nil {
			jp.SampleIDs = origSamples
			writeError(w, valErr.status, valErr.code, valErr.msg)
			return
		}
		jp.RouteMode = "batched"
		jp.PlanVersion++

	case "cancel_work":
		_, _ = srv.store.cancelUnfinishedAssignmentsLocked(jp)
		srv.store.releaseJourneyCapacityLocked(jp)
		jp.Status = "cancelled"
		jp.PlanVersion++
		for _, sid := range jp.SampleIDs {
			if smp := srv.store.state.Samples[sid]; smp != nil && smp.Status != "received" {
				smp.Status = "cancelled"
			}
		}
	}

	validTrue := true
	jp.Valid = &validTrue

	srv.store.recomputeServiceabilityLocked(false)
	srv.store.recordAuditLocked(ac.user.UserID, ac.role, "edit_active_plan", "journey", jp.JourneyID, true, map[string]any{
		"changeType":  changeType,
		"planVersion": jp.PlanVersion,
	})
	srv.saveIdempotencyLocked("edit_active_plan", *req.IdempotencyKey, raw, http.StatusCreated, jp)
	_ = srv.store.saveLocked(r.Context())
	writeData(w, http.StatusCreated, jp)
}

func (srv *Server) rebuildUnfinishedLegsFromStopsLocked(jp *JourneyPlan, actorID, role string) {
	completedLegs, _ := srv.store.cancelUnfinishedAssignmentsLocked(jp)
	srv.store.releaseJourneyCapacityLocked(jp)

	primarySampleID := ""
	needsCooled := false
	if len(jp.SampleIDs) > 0 {
		primarySampleID = jp.SampleIDs[0]
		if smp := srv.store.state.Samples[primarySampleID]; smp != nil {
			needsCooled = srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID])
		}
	}

	now := time.Now().UTC()
	var newLegs []JourneyLeg
	newLegs = append(newLegs, completedLegs...)

	startIdx := len(completedLegs)
	for i := startIdx; i < len(jp.OrderedStops)-1; i++ {
		fromID := jp.OrderedStops[i].LocationID
		toID := jp.OrderedStops[i+1].LocationID
		var matchedConn *Connection
		for _, c := range srv.store.state.Connections {
			if c.Active && c.FromLocationID == fromID && c.ToLocationID == toID {
				if needsCooled && !c.Cooled {
					continue
				}
				matchedConn = c
				break
			}
		}
		cid := ""
		if matchedConn != nil {
			cid = matchedConn.ConnectionID
		}
		taID := NewUUID()
		ta := &Assignment{
			AssignmentID:        taID,
			Kind:                "transport",
			SampleID:            primarySampleID,
			SampleIDs:           append([]string{}, jp.SampleIDs...),
			JourneyID:           jp.JourneyID,
			Status:              "pending",
			FromLocationID:      fromID,
			ToLocationID:        toID,
			ConnectionID:        cid,
			Sequence:            i + 1,
			DeclinedByWorkerIDs: make(map[string]bool),
			History:             []TimelineEntry{},
		}
		srv.store.state.Assignments[taID] = ta
		w := srv.store.offerAssignmentLocked(ta, now, actorID, role)
		wID := ""
		if w != nil {
			wID = w.UserID
		}
		newLegs = append(newLegs, JourneyLeg{
			AssignmentID:    taID,
			AssignmentSnake: taID,
			Sequence:        i + 1,
			Status:          ta.Status,
			FromLocationID:  fromID,
			FromLocSnake:    fromID,
			ToLocationID:    toID,
			ToLocSnake:      toID,
			WorkerID:        wID,
			WorkerSnake:     wID,
			SampleID:        primarySampleID,
			ConnectionID:    cid,
		})
	}
	jp.Legs = newLegs
	if len(jp.SampleIDs) > 1 {
		jp.RouteMode = "batched"
	} else if len(jp.Legs) > 1 {
		jp.RouteMode = "multi_stop"
	} else {
		jp.RouteMode = "direct"
	}
	srv.store.syncJourneyAssignmentsLocked(jp)
	srv.store.reserveJourneyCapacityLocked(jp, needsCooled, len(jp.SampleIDs))
}

func (srv *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		Query      string  `json:"query"`
		ActorID    string  `json:"actorId"`
		EntityType string  `json:"entityType"`
		EntityID   string  `json:"entityId"`
		Action     string  `json:"action"`
		Role       string  `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   string  `json:"fromTime"`
		ToTime     string  `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      *string `json:"order"`
	}
	if len(strings.TrimSpace(string(raw))) > 0 {
		if err := decodeStrictJSON(raw, &req); err != nil {
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
			return
		}
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	_, authErr := srv.requireRoleLocked(r, "search_audit_trail", "audit", "search", true, "administrator", "dispatcher")
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	limit := 500
	if req.Limit != nil {
		if *req.Limit < 1 || *req.Limit > 5000 {
			writeError(w, http.StatusBadRequest, "invalid_limit", "limit must be between 1 and 5000")
			return
		}
		limit = *req.Limit
	}
	offset := 0
	if req.Offset != nil {
		if *req.Offset < 0 {
			writeError(w, http.StatusBadRequest, "invalid_offset", "offset must be >= 0")
			return
		}
		offset = *req.Offset
	}
	order := "newest_first"
	if req.Order != nil && *req.Order != "" {
		if *req.Order != "newest_first" && *req.Order != "oldest_first" {
			writeError(w, http.StatusBadRequest, "invalid_order", "order must be newest_first or oldest_first")
			return
		}
		order = *req.Order
	}

	var fromT, toT time.Time
	hasFrom, hasTo := false, false
	if req.FromTime != "" {
		t, ok := parseTimeRFC3339(req.FromTime)
		if !ok {
			writeError(w, http.StatusBadRequest, "invalid_time", "invalid fromTime")
			return
		}
		fromT = t
		hasFrom = true
	}
	if req.ToTime != "" {
		t, ok := parseTimeRFC3339(req.ToTime)
		if !ok {
			writeError(w, http.StatusBadRequest, "invalid_time", "invalid toTime")
			return
		}
		toT = t
		hasTo = true
	}

	qLower := strings.ToLower(strings.TrimSpace(req.Query))
	var matched []AuditEntry

	for _, entry := range srv.store.state.AuditEntries {
		if req.ActorID != "" && entry.ActorID != req.ActorID {
			continue
		}
		if req.EntityType != "" && !strings.EqualFold(entry.EntityType, req.EntityType) {
			continue
		}
		if req.EntityID != "" {
			if entry.EntityID != req.EntityID {
				// Also check if entityId appears inside details (e.g. sampleId or requestId)
				rawDet, _ := json.Marshal(entry.Details)
				if !strings.Contains(string(rawDet), req.EntityID) {
					continue
				}
			}
		}
		if req.Action != "" && !strings.EqualFold(entry.Action, req.Action) {
			continue
		}
		if req.Role != "" && !strings.EqualFold(entry.Role, req.Role) {
			continue
		}
		if req.Success != nil && entry.Success != *req.Success {
			continue
		}
		if hasFrom || hasTo {
			occT, ok := parseTimeRFC3339(entry.OccurredAt)
			if ok {
				if hasFrom && occT.Before(fromT) {
					continue
				}
				if hasTo && occT.After(toT) {
					continue
				}
			}
		}
		if qLower != "" {
			rawEntry, _ := json.Marshal(entry)
			if !strings.Contains(strings.ToLower(string(rawEntry)), qLower) {
				continue
			}
		}
		matched = append(matched, entry)
	}

	if order == "newest_first" {
		for i, j := 0, len(matched)-1; i < j; i, j = i+1, j-1 {
			matched[i], matched[j] = matched[j], matched[i]
		}
	}

	total := len(matched)
	var page []AuditEntry
	if offset < total {
		end := offset + limit
		if end > total {
			end = total
		}
		page = matched[offset:end]
	} else {
		page = []AuditEntry{}
	}

	hasMore := offset+len(page) < total
	var nextOffset *int
	if hasMore {
		no := offset + len(page)
		nextOffset = &no
	}

	res := AuditSearchResult{
		Entries:    page,
		Total:      total,
		Returned:   len(page),
		Offset:     offset,
		Limit:      limit,
		Order:      order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}
	writeData(w, http.StatusOK, res)
}

