func (srv *Server) performSplitLocked(jp *JourneyPlan, splitSampleIDs []string, actorID, role string) (*JourneyPlan, *apiError) {
	if len(splitSampleIDs) == 0 || len(splitSampleIDs) >= len(jp.SampleIDs) {
		return nil, newErr(http.StatusConflict, "invalid_split", "split sampleIds must be a non-empty proper subset of journey sampleIds")
	}
	inJourney := map[string]bool{}
	for _, sid := range jp.SampleIDs {
		inJourney[sid] = true
	}
	splitSet := map[string]bool{}
	for _, sid := range splitSampleIDs {
		if !inJourney[sid] {
			return nil, newErr(http.StatusConflict, "invalid_split", "sampleId does not belong to journey")
		}
		splitSet[sid] = true
	}

	for _, leg := range jp.Legs {
		if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && isAssignmentInProgress(a.Status) {
			return nil, newErr(http.StatusConflict, "split_in_progress", "cannot split a leg currently in progress")
		}
	}

	var remaining []string
	for _, sid := range jp.SampleIDs {
		if !splitSet[sid] {
			remaining = append(remaining, sid)
		}
	}

	// Release capacity on parent and rebuild for remaining + split
	srv.store.releaseJourneyCapacityLocked(jp)
	jp.SampleIDs = remaining
	jp.CapacityUsed = len(remaining)
	if len(remaining) == 1 {
		if len(jp.Legs) > 1 {
			jp.RouteMode = "multi_stop"
		} else {
			jp.RouteMode = "direct"
		}
	}
	jp.PlanVersion++

	needsCooledRem := false
	for _, sid := range remaining {
		if smp := srv.store.state.Samples[sid]; smp != nil {
			if srv.store.sampleNeedsCooledLocked(srv.store.state.SampleTypes[smp.SampleTypeID]) {
				needsCooledRem = true
			}
		}
	}
	srv.store.reserveJourneyCapacityLocked(jp, needsCooledRem, len(remaining))

	// Create splitJourney for the split samples
	firstSplitSample := srv.store.state.Samples[splitSampleIDs[0]]
	startLocID, baseTime := srv.store.findCurrentLocationOfSampleLocked(firstSplitSample, jp)
	dl, _ := time.Parse(time.RFC3339, firstSplitSample.DeliveryDeadline)
	st := srv.store.state.SampleTypes[firstSplitSample.SampleTypeID]

	ok, _, rc := srv.store.evaluateServiceabilityLocked(
		firstSplitSample.Origin,
		firstSplitSample.OriginType,
		firstSplitSample.OriginNodeID,
		st,
		baseTime,
		dl,
		len(splitSampleIDs),
		startLocID,
	)
	if !ok || rc == nil {
		return nil, newErr(http.StatusConflict, "no_valid_route", "unable to route split journey")
	}

	splitJP := srv.store.buildJourneyPlanForSampleLocked(firstSplitSample, rc, baseTime, firstSplitSample.Sealed, actorID, role)
	splitJP.ParentJourneyID = jp.JourneyID
	splitJP.SampleIDs = append([]string{}, splitSampleIDs...)
	splitJP.CapacityUsed = len(splitSampleIDs)
	if len(splitSampleIDs) > 1 {
		splitJP.RouteMode = "batched"
	}
	for _, sid := range splitSampleIDs {
		if smp := srv.store.state.Samples[sid]; smp != nil {
			smp.ActiveJourneyID = splitJP.JourneyID
		}
	}
	jp.SplitJourney = splitJP

	srv.store.recordAuditLocked(actorID, role, "split_journey", "journey", jp.JourneyID, true, map[string]any{
		"splitJourneyId": splitJP.JourneyID,
		"splitSampleIds": splitSampleIDs,
	})
	return splitJP, nil
}

