package internal

import (
	"encoding/json"
	"net/http"
	"sort"
	"strings"
	"time"
)

func (srv *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	raw, err := readBodyBytes(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "unable to read body")
		return
	}
	var req struct {
		JourneyID *string `json:"journeyId"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.JourneyID == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "read_journey_plan", "journey", *req.JourneyID, true)
	if authErr != nil {
		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	jp := srv.store.state.Journeys[*req.JourneyID]
	if jp == nil {
		writeError(w, http.StatusNotFound, "not_found", "journey not found")
		return
	}
	srv.store.syncJourneyAssignmentsLocked(jp)

	switch ac.role {
	case "administrator", "dispatcher":
		writeData(w, http.StatusOK, jp)
		return

	case "requester":
		owns := false
		for _, sid := range jp.SampleIDs {
			if smp := srv.store.state.Samples[sid]; smp != nil && smp.RequesterID == ac.user.UserID {
				owns = true
				break
			}
		}
		if !owns {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_journey_plan", "journey", jp.JourneyID, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "requester does not own any sample in this journey")
			return
		}
		reqLegs := make([]map[string]any, 0, len(jp.Legs))
		for _, leg := range jp.Legs {
			reqLegs = append(reqLegs, map[string]any{
				"sequence":       leg.Sequence,
				"status":         leg.Status,
				"fromLocationId": leg.FromLocationID,
				"toLocationId":   leg.ToLocationID,
			})
		}
		rjp := RequesterJourneyPlan{
			JourneyID:           jp.JourneyID,
			ParentJourneyID:     jp.ParentJourneyID,
			PlanVersion:         jp.PlanVersion,
			RouteMode:           jp.RouteMode,
			Status:              jp.Status,
			EstimatedDeliveryAt: jp.EstimatedDeliveryAt,
			TotalCostUnits:      jp.TotalCostUnits,
			SampleIDs:           jp.SampleIDs,
			OrderedStops:        jp.OrderedStops,
			Legs:                reqLegs,
		}
		writeData(w, http.StatusOK, rjp)
		return

	default:
		var myAssignIDs []string
		var myLegs []JourneyLeg
		stopLocSet := map[string]bool{}
		var myColIDs, myNodeIDs, myLabIDs []string

		for _, cid := range jp.CollectionAssignmentIDs {
			if a := srv.store.state.Assignments[cid]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, cid)
				myColIDs = append(myColIDs, cid)
				stopLocSet[a.ToLocationID] = true
			}
		}
		for _, leg := range jp.Legs {
			if a := srv.store.state.Assignments[leg.AssignmentID]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, leg.AssignmentID)
				myLegs = append(myLegs, leg)
				stopLocSet[leg.FromLocationID] = true
				stopLocSet[leg.ToLocationID] = true
			}
		}
		for _, nid := range jp.NodeAssignmentIDs {
			if a := srv.store.state.Assignments[nid]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, nid)
				myNodeIDs = append(myNodeIDs, nid)
				stopLocSet[a.NodeID] = true
			}
		}
		for _, lid := range jp.LaboratoryAssignmentIDs {
			if a := srv.store.state.Assignments[lid]; a != nil && (a.WorkerID == ac.user.UserID || a.OfferedToWorkerID == ac.user.UserID) {
				myAssignIDs = append(myAssignIDs, lid)
				myLabIDs = append(myLabIDs, lid)
				stopLocSet[a.LaboratoryID] = true
			}
		}

		if len(myAssignIDs) == 0 {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, "read_journey_plan", "journey", jp.JourneyID, false, map[string]any{"error": "forbidden"})
			_ = srv.store.saveLocked(r.Context())
			writeError(w, http.StatusForbidden, "forbidden", "worker has no assignments on this journey")
			return
		}
		if myLegs == nil {
			myLegs = []JourneyLeg{}
		}
		var myStops []JourneyStop
		for _, st := range jp.OrderedStops {
			if stopLocSet[st.LocationID] {
				myStops = append(myStops, st)
			}
		}
		if myStops == nil {
			myStops = []JourneyStop{}
		}

		wjp := WorkerJourneyPlan{
			JourneyID:               jp.JourneyID,
			ParentJourneyID:         jp.ParentJourneyID,
			PlanVersion:             jp.PlanVersion,
			RouteMode:               jp.RouteMode,
			Status:                  jp.Status,
			EstimatedDeliveryAt:     jp.EstimatedDeliveryAt,
			Scope:                   "assigned_legs",
			AssignmentIDs:           myAssignIDs,
			SampleIDs:               jp.SampleIDs,
			Legs:                    myLegs,
			OrderedStops:            myStops,
			CollectionAssignmentIDs: myColIDs,
			NodeAssignmentIDs:       myNodeIDs,
			LaboratoryAssignmentIDs: myLabIDs,
			AssignedWorkerIDs:       []string{ac.user.UserID},
		}
		writeData(w, http.StatusOK, wjp)
	}
}

