package internal

import (
	"net/http"
	"sort"
	"time"
)

type apiError struct {
	status int
	code   string
	msg    string
}

func (e *apiError) Error() string {
	return e.msg
}

func newErr(status int, code, msg string) *apiError {
	return &apiError{status: status, code: code, msg: msg}
}

func isAssignmentCompleted(status string) bool {
	return status == "completed" || status == "delivered"
}

func isAssignmentInProgress(status string) bool {
	return status == "at_pickup" || status == "picked_up" || status == "in_transit" || status == "arrived" || status == "in_progress"
}

func (s *Store) findCurrentLocationOfSampleLocked(smp *Sample, jp *JourneyPlan) (string, time.Time) {
	now := time.Now().UTC()
	baseTime := now
	if t, err := time.Parse(time.RFC3339, smp.RequestedAt); err == nil {
		baseTime = t
	}
	if t, err := time.Parse(time.RFC3339, smp.EarliestCollectionAt); err == nil && t.After(baseTime) {
		baseTime = t
	}
	if smp.SealedAt != "" {
		if t, err := time.Parse(time.RFC3339, smp.SealedAt); err == nil && t.After(baseTime) {
			baseTime = t
		}
	}
	if jp == nil || len(jp.OrderedStops) == 0 {
		return smp.OriginNodeID, baseTime
	}
	currLoc := jp.OrderedStops[0].LocationID
	for _, leg := range jp.Legs {
		a := s.state.Assignments[leg.AssignmentID]
		if a == nil {
			continue
		}
		if isAssignmentCompleted(a.Status) {
			currLoc = leg.ToLocationID
			if a.LastProgressAt != "" {
				if t, err := time.Parse(time.RFC3339, a.LastProgressAt); err == nil && t.After(baseTime) {
					baseTime = t
				}
			}
		} else {
			break
		}
	}
	return currLoc, baseTime
}

func (s *Store) cancelUnfinishedAssignmentsLocked(jp *JourneyPlan) (completedLegs []JourneyLeg, completedStops []JourneyStop) {
	completedStopLocs := map[string]bool{}
	for _, leg := range jp.Legs {
		a := s.state.Assignments[leg.AssignmentID]
		if a != nil && isAssignmentCompleted(a.Status) {
			completedLegs = append(completedLegs, leg)
			completedStopLocs[leg.FromLocationID] = true
			completedStopLocs[leg.ToLocationID] = true
		} else if a != nil && a.Status != "cancelled" {
			if a.WorkerID != "" {
				if u := s.state.Users[a.WorkerID]; u != nil && u.ReservedUnits > 0 {
					u.ReservedUnits--
				}
			}
			a.Status = "cancelled"
		}
	}
	for _, st := range jp.OrderedStops {
		if st.CompletedAt != "" || completedStopLocs[st.LocationID] {
			if len(completedLegs) > 0 {
				completedStops = append(completedStops, st)
			}
		}
	}
	for _, cid := range jp.CollectionAssignmentIDs {
		if a := s.state.Assignments[cid]; a != nil && !isAssignmentCompleted(a.Status) && a.Status != "cancelled" {
			if a.WorkerID != "" {
				if u := s.state.Users[a.WorkerID]; u != nil && u.ReservedUnits > 0 {
					u.ReservedUnits--
				}
			}
			a.Status = "cancelled"
		}
	}
	for _, nid := range jp.NodeAssignmentIDs {
		if a := s.state.Assignments[nid]; a != nil && !isAssignmentCompleted(a.Status) && a.Status != "cancelled" {
			if a.WorkerID != "" {
				if u := s.state.Users[a.WorkerID]; u != nil && u.ReservedUnits > 0 {
					u.ReservedUnits--
				}
			}
			a.Status = "cancelled"
		}
	}
	for _, lid := range jp.LaboratoryAssignmentIDs {
		if a := s.state.Assignments[lid]; a != nil && !isAssignmentCompleted(a.Status) && a.Status != "cancelled" {
			if a.WorkerID != "" {
				if u := s.state.Users[a.WorkerID]; u != nil && u.ReservedUnits > 0 {
					u.ReservedUnits--
				}
			}
			a.Status = "cancelled"
		}
	}
	return completedLegs, completedStops
}

func (s *Store) replanSampleJourneyLocked(smp *Sample, oldJP *JourneyPlan, actorID, role, reason string) (string, *JourneyPlan) {
	if smp.Status == "received" || smp.Status == "cancelled" || smp.Status == "expired" {
		return "not_required", nil
	}
	startLocID, baseTime := s.findCurrentLocationOfSampleLocked(smp, oldJP)
	deadline, _ := time.Parse(time.RFC3339, smp.DeliveryDeadline)
	st := s.state.SampleTypes[smp.SampleTypeID]

	// Release old journey capacity before checking replacement route
	if oldJP != nil {
		s.releaseJourneyCapacityLocked(oldJP)
	}

	var completedLegs []JourneyLeg
	var completedStops []JourneyStop
	if oldJP != nil {
		completedLegs, completedStops = s.cancelUnfinishedAssignmentsLocked(oldJP)
		oldJP.Status = "replaced"
	}

	ok, srvReason, rc := s.evaluateServiceabilityLocked(
		smp.Origin,
		smp.OriginType,
		smp.OriginNodeID,
		st,
		baseTime,
		deadline,
		1,
		startLocID,
	)
	if !ok || rc == nil {
		if srvReason == "deadline_unreachable" {
			smp.Status = "expired"
			smp.Exception = map[string]any{
				"reason": "delivery_deadline_exceeded",
				"code":   "expired",
			}
			tl := s.newTimelineEntryLocked(actorID, role, "sample_expired", "sample", smp.SampleID, true, time.Now().UTC().Format(time.RFC3339), map[string]any{
				"reason": srvReason,
			})
			smp.Timeline = append(smp.Timeline, tl)
			return "expired", nil
		}
		smp.Status = "exception"
		smp.Exception = map[string]any{
			"reason": srvReason,
			"code":   "replan_exception",
		}
		tl := s.newTimelineEntryLocked(actorID, role, "sample_exception", "sample", smp.SampleID, true, time.Now().UTC().Format(time.RFC3339), map[string]any{
			"reason": srvReason,
		})
		smp.Timeline = append(smp.Timeline, tl)
		return "exception", nil
	}

	// Build replacement journey preserving completed stops & legs and current holder
	holderBefore := smp.CurrentHolderID
	newJP := s.buildJourneyPlanForSampleLocked(smp, rc, baseTime, smp.Sealed, actorID, role)
	if oldJP != nil {
		newJP.ParentJourneyID = oldJP.JourneyID
		newJP.PlanVersion = oldJP.PlanVersion + 1
	}
	newJP.ReplanStatus = "replaced"
	if len(completedLegs) > 0 {
		// Prepend completed legs and re-sequence unfinished legs
		allLegs := make([]JourneyLeg, 0, len(completedLegs)+len(newJP.Legs))
		for idx, cl := range completedLegs {
			cl.Sequence = idx + 1
			allLegs = append(allLegs, cl)
		}
		for idx, nl := range newJP.Legs {
			nl.Sequence = len(completedLegs) + idx + 1
			if a := s.state.Assignments[nl.AssignmentID]; a != nil {
				a.Sequence = nl.Sequence
			}
			allLegs = append(allLegs, nl)
		}
		newJP.Legs = allLegs
		if len(allLegs) > 1 && newJP.RouteMode == "direct" {
			newJP.RouteMode = "multi_stop"
		}
	}
	if len(completedStops) > 0 {
		allStops := make([]JourneyStop, 0, len(completedStops)+len(newJP.OrderedStops))
		seenLoc := map[string]bool{}
		for _, cs := range completedStops {
			seenLoc[cs.LocationID] = true
			allStops = append(allStops, cs)
		}
		for _, ns := range newJP.OrderedStops {
			if seenLoc[ns.LocationID] {
				continue
			}
			allStops = append(allStops, ns)
		}
		for idx := range allStops {
			allStops[idx].Sequence = idx + 1
			if idx == 0 {
				allStops[idx].StopType = "pickup"
				allStops[idx].StopTypeSnake = "pickup"
			} else if idx == len(allStops)-1 {
				allStops[idx].StopType = "delivery"
				allStops[idx].StopTypeSnake = "delivery"
			} else {
				allStops[idx].StopType = "handoff"
				allStops[idx].StopTypeSnake = "handoff"
			}
		}
		newJP.OrderedStops = allStops
	}
	// Preserve completed collection assignment if sample already sealed
	if smp.Sealed && oldJP != nil && len(oldJP.CollectionAssignmentIDs) > 0 {
		newJP.CollectionAssignmentID = oldJP.CollectionAssignmentID
		newJP.CollectionAssignmentIDs = append([]string{}, oldJP.CollectionAssignmentIDs...)
	}
	smp.CurrentHolderID = holderBefore
	// Allow only one active replacement plan
	smp.ActiveReplacementPlanIDs = []string{newJP.JourneyID}
	if oldJP != nil {
		oldJP.ReplacementJourney = newJP
		oldJP.ReplanStatus = "replaced"
	}

	tl := s.newTimelineEntryLocked(actorID, role, "replan_journey", "sample", smp.SampleID, true, time.Now().UTC().Format(time.RFC3339), map[string]any{
		"replacementJourneyId": newJP.JourneyID,
		"reason":               reason,
	})
	smp.Timeline = append(smp.Timeline, tl)
	return "replaced", newJP
}

func (s *Store) recalculateStopsAndValidatePlanLocked(jp *JourneyPlan) *apiError {
	if len(jp.OrderedStops) < 2 {
		return newErr(http.StatusConflict, "invalid_stop", "journey must have at least pickup and delivery stops")
	}
	// Check stop order and uniqueness/validity
	for idx, st := range jp.OrderedStops {
		loc := s.state.Locations[st.LocationID]
		if loc == nil || !loc.Active {
			return newErr(http.StatusConflict, "invalid_stop", "stop location is missing or inactive")
		}
		if st.DwellMinutes < 0 {
			return newErr(http.StatusBadRequest, "invalid_dwell", "negative dwell minutes")
		}
		if idx == 0 && st.StopType != "pickup" {
			return newErr(http.StatusConflict, "invalid_stop_order", "first stop must be pickup")
		}
		if idx == len(jp.OrderedStops)-1 {
			if st.StopType != "delivery" {
				return newErr(http.StatusConflict, "invalid_stop_order", "last stop must be delivery")
			}
			if !loc.Functions.Laboratory {
				return newErr(http.StatusConflict, "invalid_destination", "final stop must be an active laboratory")
			}
		}
		if idx > 0 && idx < len(jp.OrderedStops)-1 && st.StopType == "delivery" {
			return newErr(http.StatusConflict, "invalid_stop_order", "delivery stop cannot precede another stop")
		}
	}

	// Validate samples compatibility and batching rules
	samples := make([]*Sample, 0, len(jp.SampleIDs))
	needsCooled := false
	for _, sid := range jp.SampleIDs {
		smp := s.state.Samples[sid]
		if smp == nil {
			return newErr(http.StatusNotFound, "not_found", "sample not found")
		}
		st := s.state.SampleTypes[smp.SampleTypeID]
		if len(jp.SampleIDs) > 1 && s.sampleDisallowsBatchingLocked(st) {
			return newErr(http.StatusConflict, "pulse_no_batch", "time-critical sample cannot be batched")
		}
		if s.sampleNeedsCooledLocked(st) {
			needsCooled = true
		}
		samples = append(samples, smp)
	}
	for i := 0; i < len(samples); i++ {
		for j := i + 1; j < len(samples); j++ {
			if !s.samplesCompatibleLocked(samples[i], samples[j]) {
				return newErr(http.StatusConflict, "incompatible_batch", "samples are incompatible in the same batch")
			}
		}
	}

	// Verify connections exist between consecutive stops
	finalLocID := jp.OrderedStops[len(jp.OrderedStops)-1].LocationID
	for _, smp := range samples {
		if !s.labAcceptsSampleTypeLocked(finalLocID, smp.SampleTypeID) {
			return newErr(http.StatusConflict, "invalid_destination", "destination laboratory does not accept sample type")
		}
	}

	var connPath []*Connection
	for i := 0; i < len(jp.OrderedStops)-1; i++ {
		fromID := jp.OrderedStops[i].LocationID
		toID := jp.OrderedStops[i+1].LocationID
		var matched *Connection
		for _, c := range s.state.Connections {
			if c.Active && c.FromLocationID == fromID && c.ToLocationID == toID {
				if needsCooled && !c.Cooled {
					continue
				}
				matched = c
				break
			}
		}
		if matched == nil {
			// Check if uncooled connection exists
			for _, c := range s.state.Connections {
				if c.Active && c.FromLocationID == fromID && c.ToLocationID == toID {
					return newErr(http.StatusConflict, "invalid_route", "connection does not support cooled transport")
				}
			}
			return newErr(http.StatusConflict, "no_valid_route", "no active connection between consecutive stops")
		}
		connPath = append(connPath, matched)
	}

	// Calculate timing and check deadlines
	startTime := time.Now().UTC()
	for idx, smp := range samples {
		t, err := time.Parse(time.RFC3339, smp.EarliestCollectionAt)
		if err != nil {
			t, _ = time.Parse(time.RFC3339, smp.RequestedAt)
		}
		if idx == 0 || t.After(startTime) {
			startTime = t
		}
	}
	curr := startTime
	totalCost := 0.0
	for i := range jp.OrderedStops {
		loc := s.state.Locations[jp.OrderedStops[i].LocationID]
		if i > 0 {
			c := connPath[i-1]
			curr = curr.Add(time.Duration(c.TravelMinutes) * time.Minute)
			totalCost += c.CostUnits
		}
		jp.OrderedStops[i].Sequence = i + 1
		estStr := curr.UTC().Format(time.RFC3339)
		jp.OrderedStops[i].EstimatedAt = estStr
		jp.OrderedStops[i].EstimatedSnake = estStr
		dwell := jp.OrderedStops[i].DwellMinutes
		if dwell == 0 && loc != nil {
			dwell = loc.HandlingMinutes
			jp.OrderedStops[i].DwellMinutes = dwell
		}
		curr = curr.Add(time.Duration(dwell) * time.Minute)
	}

	for _, smp := range samples {
		dl, err := time.Parse(time.RFC3339, smp.DeliveryDeadline)
		if err == nil && curr.After(dl) {
			return newErr(http.StatusConflict, "delivery_deadline_exceeded", "updated plan exceeds sample delivery deadline")
		}
		st := s.state.SampleTypes[smp.SampleTypeID]
		if s.sampleDisallowsBatchingLocked(st) {
			for _, stop := range jp.OrderedStops {
				loc := s.state.Locations[stop.LocationID]
				if loc != nil && stop.DwellMinutes > loc.HandlingMinutes {
					return newErr(http.StatusConflict, "pulse_no_wait", "Pulse sample cannot wait for batching delay")
				}
			}
		}
	}

	// Check capacity for new stops/connections (accounting for already reserved resources on jp)
	units := len(samples)
	for _, stop := range jp.OrderedStops {
		loc := s.state.Locations[stop.LocationID]
		capState := s.getLocationCapacityLocked(loc)
		avail := capState.AvailableUnits
		if needsCooled {
			avail = capState.CooledAvailableUnits
		}
		if _, already := jp.ReservedResources[stop.LocationID]; already {
			avail += jp.ReservedUnitsCount
		}
		if avail < units {
			if needsCooled {
				return newErr(http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity at location")
			}
			return newErr(http.StatusConflict, "capacity_exhausted", "insufficient regular capacity at location")
		}
	}
	for _, c := range connPath {
		capState := s.getConnectionCapacityLocked(c)
		avail := capState.AvailableUnits
		if needsCooled {
			avail = capState.CooledAvailableUnits
		}
		if _, already := jp.ReservedResources[c.ConnectionID]; already {
			avail += jp.ReservedUnitsCount
		}
		if avail < units {
			if needsCooled {
				return newErr(http.StatusConflict, "cooled_capacity_exhausted", "insufficient cooled capacity on connection")
			}
			return newErr(http.StatusConflict, "capacity_exhausted", "insufficient regular capacity on connection")
		}
	}

	jp.EstimatedDeliveryAt = curr.UTC().Format(time.RFC3339)
	jp.TotalCostUnits = totalCost
	jp.CapacityUsed = units
	return nil
}

func sortStringsUnique(in []string) []string {
	m := map[string]bool{}
	var out []string
	for _, s := range in {
		if s != "" && !m[s] {
			m[s] = true
			out = append(out, s)
		}
	}
	sort.Strings(out)
	return out
}

