func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, ErrorEnvelope{
		Error: msg,
		Code:  code,
	})
}

func decodeStrictJSON(body []byte, dst any) error {
	if len(bytes.TrimSpace(body)) == 0 {
		return io.EOF
	}
	dec := json.NewDecoder(bytes.NewReader(body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	var extra any
	if err := dec.Decode(&extra); err != io.EOF {
		return io.ErrUnexpectedEOF
	}
	return nil
}

func readBodyBytes(r *http.Request) ([]byte, error) {
	defer r.Body.Close()
	return io.ReadAll(r.Body)
}

type authContext struct {
	session *Session
	user    *User
	role    string
}

func (srv *Server) authenticateRequestLocked(r *http.Request) (*authContext, *apiError) {
	var token string
	authHeader := strings.TrimSpace(r.Header.Get("Authorization"))
	if strings.HasPrefix(strings.ToLower(authHeader), "bearer ") {
		token = strings.TrimSpace(authHeader[7:])
	}
	if token == "" {
		// Check Sec-WebSocket-Protocol or query parameter for WS/events
		proto := strings.TrimSpace(r.Header.Get("Sec-WebSocket-Protocol"))
		if proto != "" {
			parts := strings.Split(proto, ",")
			for _, p := range parts {
				p = strings.TrimSpace(p)
				if strings.HasPrefix(strings.ToLower(p), "bearer.") {
					token = strings.TrimSpace(p[7:])
					break
				}
				if _, ok := srv.store.state.Sessions[p]; ok {
					token = p
					break
				}
			}
		}
		if token == "" {
			token = strings.TrimSpace(r.URL.Query().Get("token"))
		}
	}
	if token == "" {
		return nil, newErr(http.StatusUnauthorized, "unauthorized", "missing or invalid authorization token")
	}
	sess, ok := srv.store.state.Sessions[token]
	if !ok || sess == nil {
		return nil, newErr(http.StatusUnauthorized, "unauthorized", "invalid session token")
	}
	u, ok := srv.store.state.Users[sess.UserID]
	if !ok || u == nil || !u.Active {
		return nil, newErr(http.StatusUnauthorized, "unauthorized", "user inactive or not found")
	}
	return &authContext{
		session: sess,
		user:    u,
		role:    sess.ActiveRole,
	}, nil
}

func (srv *Server) requireRoleLocked(r *http.Request, action, entityType, entityID string, requireSelected bool, allowedRoles ...string) (*authContext, *apiError) {
	ac, err := srv.authenticateRequestLocked(r)
	if err != nil {
		srv.store.recordAuditLocked("anonymous", "unauthenticated", action, entityType, entityID, false, map[string]any{"error": err.code})
		return nil, err
	}
	if requireSelected && (ac.session.RoleSelectionRequired || ac.role == "") {
		srv.store.recordAuditLocked(ac.user.UserID, "unselected", action, entityType, entityID, false, map[string]any{"error": "role_not_selected"})
		return nil, newErr(http.StatusConflict, "role_not_selected", "must explicitly select an active role before performing this action")
	}
	if len(allowedRoles) > 0 {
		allowed := false
		for _, ar := range allowedRoles {
			if ac.role == ar {
				allowed = true
				break
			}
		}
		if !allowed {
			srv.store.recordAuditLocked(ac.user.UserID, ac.role, action, entityType, entityID, false, map[string]any{"error": "forbidden", "requiredRoles": allowedRoles})
			return nil, newErr(http.StatusForbidden, "forbidden", "active role does not permit this operation")
		}
	}
	return ac, nil
}

func (srv *Server) checkIdempotencyLocked(opID, key string, rawBody []byte) (*IdempotencyRecord, *apiError) {
	key = strings.TrimSpace(key)
	if key == "" {
		return nil, newErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
	}
	composite := opID + ":" + key
	pHash := HashPayload(rawBody)
	if rec, ok := srv.store.state.Idempotency[composite]; ok && rec != nil {
		if rec.PayloadHash != pHash {
			return nil, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey already used with different request parameters")
		}
		return rec, nil
	}
	return nil, nil
}

func (srv *Server) saveIdempotencyLocked(opID, key string, rawBody []byte, statusCode int, data any) {
	key = strings.TrimSpace(key)
	if key == "" {
		return
	}
	composite := opID + ":" + key
	respBytes, _ := json.Marshal(map[string]any{"data": data})
	srv.store.state.Idempotency[composite] = &IdempotencyRecord{
		Key:         key,
		OperationID: opID,
		PayloadHash: HashPayload(rawBody),
		StatusCode:  statusCode,
		Response:    respBytes,
	}
}

func (srv *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path

	if path == "/ready" {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}
		if srv.store.Ready(r.Context()) {
			writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
		} else {
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "starting"})
		}
		return
	}

	// Serve offline map assets under /map-assets/
	if strings.HasPrefix(path, "/map-assets/") {
		rel := strings.TrimPrefix(path, "/map-assets/")
		full := filepath.Join(srv.mapAssetDir, filepath.Clean("/"+rel))
		http.ServeFile(w, r, full)
		return
	}

	if strings.HasPrefix(path, "/api/") {
		srv.handleAPI(w, r)
		return
	}

	// Serve frontend SPA
	if srv.frontendDir != "" {
		clean := filepath.Clean(path)
		if clean == "/" {
			clean = "/index.html"
		}
		full := filepath.Join(srv.frontendDir, clean)
		if info, err := os.Stat(full); err == nil && !info.IsDir() {
			http.ServeFile(w, r, full)
			return
		}
		indexFile := filepath.Join(srv.frontendDir, "index.html")
		if _, err := os.Stat(indexFile); err == nil {
			http.ServeFile(w, r, indexFile)
			return
		}
	}
	http.NotFound(w, r)
}

