		return nil, newErr(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
	}
	composite := opID + ":" + key
	pHash := HashPayload(rawBody)
	if rec, ok := srv.store.state.Idempotency[composite]; ok && rec != nil {
		if rec.PayloadHash != pHash {
			return nil, newErr(http.StatusConflict, "idempotency_conflict", "idempotencyKey already used with different request parameters")
		}
		return rec, nil
	}
	return nil, nil
}

func (srv *Server) saveIdempotencyLocked(opID, key string, rawBody []byte, statusCode int, data any) {
	key = strings.TrimSpace(key)
	if key == "" {
		return
	}
	composite := opID + ":" + key
	respBytes, _ := json.Marshal(map[string]any{"data": data})
	srv.store.state.Idempotency[composite] = &IdempotencyRecord{
		Key:         key,
		OperationID: opID,
		PayloadHash: HashPayload(rawBody),
		StatusCode:  statusCode,
		Response:    respBytes,
	}
}

func (srv *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path

	if path == "/ready" {
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}
		if srv.store.Ready(r.Context()) {
			writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
		} else {
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "starting"})
		}
		return
	}

	// Serve offline map assets under /map-assets/
	if strings.HasPrefix(path, "/map-assets/") {
		rel := strings.TrimPrefix(path, "/map-assets/")
		full := filepath.Join(srv.mapAssetDir, filepath.Clean("/"+rel))
		http.ServeFile(w, r, full)
		return
	}

	if strings.HasPrefix(path, "/api/") {
		srv.handleAPI(w, r)
		return
	}

	// Serve frontend SPA
	if srv.frontendDir != "" {
		clean := filepath.Clean(path)
		if clean == "/" {
			clean = "/index.html"
		}
		full := filepath.Join(srv.frontendDir, clean)
		if info, err := os.Stat(full); err == nil && !info.IsDir() {
			http.ServeFile(w, r, full)
			return
		}
		indexFile := filepath.Join(srv.frontendDir, "index.html")
		if _, err := os.Stat(indexFile); err == nil {
			http.ServeFile(w, r, indexFile)
			return
		}
	}
	http.NotFound(w, r)
}

func (srv *Server) handleAPI(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path

	switch {
	case path == "/api/authenticate-user" && r.Method == http.MethodPost:
		srv.handleAuthenticateUser(w, r)
	case path == "/api/select-active-role" && r.Method == http.MethodPost:
		srv.handleSelectActiveRole(w, r)
	case path == "/api/create-user" && r.Method == http.MethodPost:
		srv.handleCreateUser(w, r)
	case path == "/api/update-user-access" && r.Method == http.MethodPost:
		srv.handleUpdateUserAccess(w, r)
	case strings.HasPrefix(path, "/api/read-user/"):
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}
		srv.handleReadUser(w, r, strings.TrimPrefix(path, "/api/read-user/"))
	case path == "/api/create-sample-type" && r.Method == http.MethodPost:
		srv.handleCreateSampleType(w, r)
	case path == "/api/update-sample-type" && r.Method == http.MethodPost:
		srv.handleUpdateSampleType(w, r)
	case path == "/api/create-location" && r.Method == http.MethodPost:
		srv.handleCreateLocation(w, r)
	case path == "/api/update-location" && r.Method == http.MethodPost:
		srv.handleUpdateLocation(w, r)
	case path == "/api/set-location-status" && r.Method == http.MethodPost:
		srv.handleSetLocationStatus(w, r)
	case path == "/api/set-location-function-status" && r.Method == http.MethodPost:
		srv.handleSetLocationFunctionStatus(w, r)
	case path == "/api/create-connection" && r.Method == http.MethodPost:
		srv.handleCreateConnection(w, r)
	case path == "/api/set-connection-status" && r.Method == http.MethodPost:
		srv.handleSetConnectionStatus(w, r)
	case path == "/api/configure-capacity" && r.Method == http.MethodPost:
		srv.handleConfigureCapacity(w, r)
	case path == "/api/configure-laboratory-acceptance" && r.Method == http.MethodPost:
		srv.handleConfigureLaboratoryAcceptance(w, r)
	case path == "/api/set-worker-availability" && r.Method == http.MethodPost:
		srv.handleSetWorkerAvailability(w, r)
	case path == "/api/check-serviceability" && r.Method == http.MethodPost:
		srv.handleCheckServiceability(w, r)
	case path == "/api/read-serviceability-snapshot" && r.Method == http.MethodPost:
		srv.handleReadServiceabilitySnapshot(w, r)
	case path == "/api/create-collection-request" && r.Method == http.MethodPost:
		srv.handleCreateCollectionRequest(w, r)
	case path == "/api/ingest-presealed-sample" && r.Method == http.MethodPost:
		srv.handleIngestPresealedSample(w, r)
	case strings.HasPrefix(path, "/api/read-sample-state/"):
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}
		srv.handleReadSampleState(w, r, strings.TrimPrefix(path, "/api/read-sample-state/"))
	case path == "/api/read-sample-lifecycle" && r.Method == http.MethodPost:
		srv.handleReadSampleLifecycle(w, r)
	case path == "/api/list-role-work" && r.Method == http.MethodPost:
		srv.handleListRoleWork(w, r)
	case path == "/api/accept-assignment" && r.Method == http.MethodPost:
		srv.handleAcceptAssignment(w, r)
	case path == "/api/decline-assignment" && r.Method == http.MethodPost:
		srv.handleDeclineAssignment(w, r)
	case path == "/api/collect-and-seal-sample" && r.Method == http.MethodPost:
		srv.handleCollectAndSealSample(w, r)
	case path == "/api/update-assignment-progress" && r.Method == http.MethodPost:
		srv.handleUpdateAssignmentProgress(w, r)
	case path == "/api/record-worker-location" && r.Method == http.MethodPost:
		srv.handleRecordWorkerLocation(w, r)
	case path == "/api/initiate-handoff" && r.Method == http.MethodPost:
		srv.handleInitiateHandoff(w, r)
	case path == "/api/confirm-handoff" && r.Method == http.MethodPost:
		srv.handleConfirmHandoff(w, r)
	case path == "/api/record-handling-checkpoint" && r.Method == http.MethodPost:
		srv.handleRecordHandlingCheckpoint(w, r)
	case path == "/api/confirm-laboratory-receipt" && r.Method == http.MethodPost:
		srv.handleConfirmLaboratoryReceipt(w, r)
	case path == "/api/record-laboratory-exception" && r.Method == http.MethodPost:
		srv.handleRecordLaboratoryException(w, r)
	case path == "/api/read-journey-plan" && r.Method == http.MethodPost:
		srv.handleReadJourneyPlan(w, r)
	case path == "/api/read-operations-state" && r.Method == http.MethodPost:
		srv.handleReadOperationsState(w, r)
	case path == "/api/edit-active-plan" && r.Method == http.MethodPost:
		srv.handleEditActivePlan(w, r)
	case path == "/api/merge-journeys" && r.Method == http.MethodPost:
		srv.handleMergeJourneys(w, r)
	case path == "/api/split-journey" && r.Method == http.MethodPost:
		srv.handleSplitJourney(w, r)
	case path == "/api/cancel-journey" && r.Method == http.MethodPost:
		srv.handleCancelJourney(w, r)
	case path == "/api/reroute-journey" && r.Method == http.MethodPost:
		srv.handleRerouteJourney(w, r)
	case path == "/api/report-disruption" && r.Method == http.MethodPost:
		srv.handleReportDisruption(w, r)
	case path == "/api/search-audit-trail" && r.Method == http.MethodPost:
		srv.handleSearchAuditTrail(w, r)
	case path == "/api/events":
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}
		srv.handleRealtimeEvents(w, r)
	case path == "/api/ui/bootstrap":
		if r.Method != http.MethodGet {
			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
			return
		}
		srv.handleUIBootstrap(w, r)
	default:
		writeError(w, http.StatusNotFound, "not_found", "endpoint not found")
	}
}

func (srv *Server) handleRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	srv.store.mu.Lock()
	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		srv.store.mu.Unlock()
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}
	_ = ac

	sinceStr := strings.TrimSpace(r.URL.Query().Get("since"))
	var since int64
	if sinceStr != "" {
		val, err := strconv.ParseInt(sinceStr, 10, 64)
		if err != nil || val < 0 {
			srv.store.mu.Unlock()
			writeError(w, http.StatusBadRequest, "invalid_json", "invalid since parameter")
			return
		}
		since = val
	}

	events := []RealtimeEvent{}
	var cursor int64 = since
	for _, ev := range srv.store.state.RealtimeEvents {
		if ev.ID > since {
			events = append(events, ev)
			if ev.ID > cursor {
				cursor = ev.ID
			}
		}
	}
	srv.store.mu.Unlock()

	if websocket.IsWebSocketUpgrade(r) {
		var respHeader http.Header
		if proto := strings.TrimSpace(r.Header.Get("Sec-WebSocket-Protocol")); proto != "" {
			parts := strings.Split(proto, ",")
			respHeader = http.Header{"Sec-WebSocket-Protocol": []string{strings.TrimSpace(parts[0])}}
		}
		conn, err := srv.upgrader.Upgrade(w, r, respHeader)
		if err != nil {
			return
		}
		srv.store.RegisterWS(conn)
		for _, ev := range events {
			if msg, err := json.Marshal(ev); err == nil {
				_ = conn.WriteMessage(websocket.TextMessage, msg)
			}
		}
		go func() {
			defer srv.store.UnregisterWS(conn)
			for {
				if _, _, err := conn.ReadMessage(); err != nil {
					return
				}
			}
		}()
		return
	}

	writeData(w, http.StatusOK, map[string]any{
		"events": events,
		"cursor": cursor,
	})
}

func (srv *Server) handleUIBootstrap(w http.ResponseWriter, r *http.Request) {
	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.authenticateRequestLocked(r)
	if authErr != nil {
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	userObj := map[string]any{
		"userId":                ac.user.UserID,
		"username":              ac.user.Username,
		"roles":                 ac.user.Roles,
		"activeRole":            ac.session.ActiveRole,
		"roleSelectionRequired": ac.session.RoleSelectionRequired,
		"assignedLocationId":    ac.user.AssignedLocationID,
		"qualifications":        ac.user.Qualifications,
	}
	if ac.user.FullName != "" {
		userObj["fullName"] = ac.user.FullName
	}

	var sampleTypesList []*SampleType
	for _, st := range srv.store.state.SampleTypes {
		sampleTypesList = append(sampleTypesList, st)
	}

	var activeNodes []map[string]any
	for _, loc := range srv.store.state.Locations {
		capState := srv.store.getLocationCapacityLocked(loc)
		activeNodes = append(activeNodes, map[string]any{
			"locationId":      loc.LocationID,
			"name":            loc.Name,
			"coordinate":      loc.Coordinate,
			"active":          loc.Active,
			"functions":       loc.Functions,
			"coverageKm":      loc.CoverageKm,
			"handlingMinutes": loc.HandlingMinutes,
			"capacity":        capState,
		})
	}

	resp := map[string]any{
		"user":        userObj,
		"serverTime":  time.Now().UTC().Format(time.RFC3339),
		"sampleTypes": sampleTypesList,
		"locations":   activeNodes,
	}

	if ac.user.AssignedLocationID != "" {
		if loc := srv.store.state.Locations[ac.user.AssignedLocationID]; loc != nil {
			capState := srv.store.getLocationCapacityLocked(loc)
			resp["assignedLocation"] = map[string]any{
				"locationId": loc.LocationID,
				"name":       loc.Name,
				"coordinate": loc.Coordinate,
				"functions":  loc.Functions,
				"capacity":   capState,
			}
		}
	}

	if !ac.session.RoleSelectionRequired && ac.role != "" {
		if ac.role == "requester" {
			var reqSamples []map[string]any
			for _, smp := range srv.store.state.Samples {
				if smp.RequesterID == ac.user.UserID {
					srv.refreshSampleStaleLocked(smp)
					reqSamples = append(reqSamples, map[string]any{
						"sampleId":           smp.SampleID,
						"requestId":          smp.RequestID,
						"status":             smp.Status,
						"serviceability":     smp.Serviceability,
						"origin":             smp.Origin,
						"originType":         smp.OriginType,
						"deliveryDeadline":   smp.DeliveryDeadline,
						"activeJourneyId":    smp.ActiveJourneyID,
						"targetLaboratoryId": smp.TargetLaboratoryID,
						"currentHolderId":    smp.CurrentHolderID,
						"latestLocation":     smp.LatestLocation,
						"locationRecordedAt": smp.LocationRecordedAt,
						"locationStale":      smp.LocationStale,
						"exception":          smp.Exception,
						"timeline":           smp.Timeline,
					})
				}
			}
			if reqSamples == nil {
				reqSamples = []map[string]any{}
			}
			resp["requesterSamples"] = reqSamples
		}
		if ac.role == "administrator" || ac.role == "dispatcher" {
			ops := srv.buildOperationsStateLocked("")
			resp["operations"] = ops
		}
	}

	writeData(w, http.StatusOK, resp)
}

