          const rw = workRes.body.data;
          setRoleWork({
            pending: rw.pending || [],
            inProgress: rw.inProgress || [],
            completed: rw.completed || []
          });
          const allItems = [...(rw.pending || []), ...(rw.inProgress || []), ...(rw.completed || [])];
          allItems.forEach((it: any) => {
            if (it.sampleId) sidsToLoad.push(it.sampleId);
            if (Array.isArray(it.sampleIds)) sidsToLoad.push(...it.sampleIds);
          });
          const firstAssign = [...(rw.inProgress || []), ...(rw.pending || [])].find((it: any) => it.assignmentId);
          if (firstAssign && !locAssignmentId) {
            setLocAssignmentId(firstAssign.assignmentId);
          }
        }
        if (Array.isArray(bData.requesterSamples)) {
          bData.requesterSamples.forEach((s: any) => {
            if (s.sampleId) sidsToLoad.push(s.sampleId);
          });
        }
        if (u.activeRole === 'dispatcher' || u.activeRole === 'administrator') {
          const [opsRes, audRes] = await Promise.all([
            apiFetch('/api/read-operations-state', { method: 'POST', body: JSON.stringify({}) }, activeTok),
            apiFetch('/api/search-audit-trail', { method: 'POST', body: JSON.stringify({ limit: 100 }) }, activeTok)
          ]);
          if (opsRes.ok && opsRes.body?.data) {
            setOperations(opsRes.body.data);
            (opsRes.body.data.samples || []).forEach((s: any) => {
              if (s.sampleId) sidsToLoad.push(s.sampleId);
            });
          }
          if (audRes.ok && audRes.body?.data) {
            setAuditEntries(audRes.body.data.entries || []);
          }
        }
        if (sidsToLoad.length > 0) {
          await loadSampleDetails(sidsToLoad, activeTok);
        }
      }
    },
    [apiFetch, loadSampleDetails, locAssignmentId, selectedSampleTypeId, token]
  );

  useEffect(() => {
    if (token) {
      refreshAll(token);
    }
  }, [token, refreshAll]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (!username.trim() || !password) {
      setAuthError('Username and password are required');
      return;
    }
    const res = await apiFetch(
      '/api/authenticate-user',
      {
        method: 'POST',
        body: JSON.stringify({ username: username.trim(), password })
      },
      ''
    );
    if (!res.ok) {
      const errMsg = res.body?.error || 'Invalid username or password';
      const errCode = res.body?.code || 'invalid_credentials';
      setAuthError(`${errMsg} (${errCode})`);
      return;
    }
    const data = res.body?.data;
    const tok = data.sessionToken;
    localStorage.setItem('sessionToken', tok);
    setToken(tok);
    await refreshAll(tok);
  };

  const handleSignOut = () => {
    localStorage.removeItem('sessionToken');
    setToken('');
    setUser(null);
    setActiveRole('');
    setRoleWork({ pending: [], inProgress: [], completed: [] });
    setOperations(null);
    setAuditEntries([]);
    setAuthError('');
  };

  const handleSelectRole = async (newRole: string) => {
    if (!newRole) return;
    setActionAlert('');
    const res = await apiFetch('/api/select-active-role', {
      method: 'POST',
      body: JSON.stringify({ role: newRole })
    });
    if (!res.ok) {
      setActionAlert(res.body?.error || 'Failed to switch role');
      return;
    }
    setActiveRole(newRole);
    setRoleSelectionRequired(false);
    await refreshAll();
  };

  const handleSampleTypeChange = (stId: string) => {
    setSelectedSampleTypeId(stId);
    const st = sampleTypes.find((s) => s.sampleTypeId === stId);
    if (st) {
      setContainerType(st.containerType || 'amber-vial');
      setTempMin(String(st.temperatureMinC ?? 2));
      setTempMax(String(st.temperatureMaxC ?? 8));
    }
  };

  const handleCheckServiceability = async () => {
    setRequestFormError('');
    setRequestSuccessMsg('');
    setServiceabilityResult(null);

    const lat = Number(originLat);
    const lng = Number(originLng);
    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      setRequestFormError('Invalid origin coordinates (invalid_origin)');
      return;
    }
    if (!selectedSampleTypeId) {
      setRequestFormError('Please select a sample type (invalid_sample_type)');
      return;
    }

    const res = await apiFetch('/api/check-serviceability', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        sampleTypeId: selectedSampleTypeId,
        requestedAt: earliestCol,
        earliestCollectionAt: earliestCol,
        latestCollectionAt: latestCol,
        deliveryDeadline
      })
    });
    if (!res.ok) {
      setRequestFormError(`${res.body?.error || 'Validation error'} (${res.body?.code || 'invalid_request'})`);
      return;
    }
    setServiceabilityResult(res.body?.data);
  };

  const handleCreateRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setRequestFormError('');
    setRequestSuccessMsg('');

    const lat = Number(originLat);
    const lng = Number(originLng);
    const tMin = Number(tempMin);
    const tMax = Number(tempMax);

    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      setRequestFormError('Validation error: Origin coordinates out of bounds (invalid_origin)');
      return;
    }
    if (!containerType.trim() || Number.isNaN(tMin) || Number.isNaN(tMax) || tMin >= tMax) {
      setRequestFormError('Validation error: Invalid container or temperature range (handling_mismatch)');
      return;
    }

    const res = await apiFetch('/api/create-collection-request', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        requestedAt: earliestCol,
        earliestCollectionAt: earliestCol,
        latestCollectionAt: latestCol,
        deliveryDeadline,
        sampleTypeId: selectedSampleTypeId,
        containerType: containerType.trim(),
        temperatureMinC: tMin,
        temperatureMaxC: tMax,
        idempotencyKey: makeIdempKey('req')
      })
    });
    if (!res.ok) {
      setRequestFormError(`${res.body?.error || 'Request validation failed'} (${res.body?.code || 'validation_error'})`);
      return;
    }
    const created = res.body?.data;
    setRequestSuccessMsg(`Created sample ${created.sampleId} (${created.serviceability})`);
    await refreshAll();
  };

  const handleAcceptAssignment = async (assignmentId: string) => {
    setActionAlert('');
    const res = await apiFetch('/api/accept-assignment', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        idempotencyKey: makeIdempKey('accept')
      })
    });
    if (!res.ok) {
      setActionAlert(`${res.body?.error || 'Failed to accept assignment'} (${res.body?.code || 'error'})`);
      return;
    }
    setLocAssignmentId(assignmentId);
    await refreshAll();
  };

  const handleDeclineAssignment = async (assignmentId: string) => {
    setActionAlert('');
    const res = await apiFetch('/api/decline-assignment', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        reason: 'Worker declined via UI',
        declinedAt: new Date().toISOString(),
        idempotencyKey: makeIdempKey('decline')
      })
    });
    if (!res.ok) {
      setActionAlert(`${res.body?.error || 'Failed to decline assignment'} (${res.body?.code || 'error'})`);
      return;
    }
    await refreshAll();
  };

  const handleRecordWorkerLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setWorkerLocError('');
    setWorkerLocMsg('');
    const targetAssignId =
      locAssignmentId ||
      [...roleWork.inProgress, ...roleWork.pending].find((a: any) => a.assignmentId)?.assignmentId ||
      '';
    if (!targetAssignId) {
      setWorkerLocError('No active assignment selected');
      return;
    }
    const res = await apiFetch('/api/record-worker-location', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId: targetAssignId,
        coordinate: {
          latitude: Number(workerLat),
          longitude: Number(workerLng)
        },
        sequence: Number(workerSeq),
        recordedAt: new Date().toISOString()
      })
    });
    if (!res.ok) {
      setWorkerLocError(`${res.body?.error || 'Failed to record location'} (${res.body?.code || 'error'})`);
      return;
    }
    const d = res.body?.data;
    setWorkerLocMsg(
      `Recorded Location: ${d.coordinate.latitude}, ${d.coordinate.longitude} (seq ${d.sequence}) at ${d.recordedAt}`
    );
    setWorkerSeq(String(Number(workerSeq) + 1));
    await refreshAll();
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    setCapMsg('');
    if (!assignedLocation?.locationId) return;
    const res = await apiFetch('/api/configure-capacity', {
      method: 'POST',
      body: JSON.stringify({
        resourceId: assignedLocation.locationId,
        capacityUnits: Number(regCapInput),
        cooledCapacityUnits: Number(cooledCapInput)
      })
    });
    if (!res.ok) {
      setCapMsg(`Error: ${res.body?.error} (${res.body?.code})`);
      return;
    }
    setCapMsg('Capacity updated');
    await refreshAll();
  };

  const handleSearchAudit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const payload: Record<string, any> = { limit: 100 };
    if (auditQuery.trim()) payload.query = auditQuery.trim();
    if (auditActionFilter.trim()) payload.action = auditActionFilter.trim();
    if (auditEntityFilter.trim()) payload.entityId = auditEntityFilter.trim();

    const res = await apiFetch('/api/search-audit-trail', {
      method: 'POST',
      body: JSON.stringify(payload)
    });
    if (res.ok && res.body?.data) {
      setAuditEntries(res.body.data.entries || []);
    }
  };

  if (!token) {
    return (
      <main
        style={{
          maxWidth: '460px',
          margin: '60px auto',
          padding: '24px',
          border: '1px solid #cbd5e1',
          borderRadius: '8px',
          fontFamily: 'system-ui, sans-serif',
          background: '#ffffff'
        }}
      >
        <h1>Lab Sample Pickup &amp; Delivery System</h1>
        <h2>Sign In</h2>
        {authError && (
          <div
            role="alert"
            aria-label="Authentication Error"
            style={{
              padding: '10px',
              marginBottom: '12px',
              background: '#fee2e2',
              color: '#991b1b',
              borderRadius: '6px'
            }}
          >
            {authError}
          </div>
        )}
        <form onSubmit={handleLogin} aria-label="Sign In Form">
          <div style={{ marginBottom: '12px' }}>
            <label htmlFor="username-input" style={{ display: 'block', marginBottom: '4px', fontWeight: 600 }}>
              Username
            </label>
            <input
              id="username-input"
              name="username"
              aria-label="Username"
              type="text"
              placeholder="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            />
          </div>
          <div style={{ marginBottom: '16px' }}>
            <label htmlFor="password-input" style={{ display: 'block', marginBottom: '4px', fontWeight: 600 }}>
              Password
            </label>
            <input
              id="password-input"
              name="password"
              aria-label="Password"
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            />
          </div>
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '10px',
              background: '#0284c7',
              color: '#ffffff',
              border: 'none',
              borderRadius: '6px',
              fontWeight: 600,
              cursor: 'pointer'
            }}
          >
            Sign In
          </button>
        </form>
      </main>
    );
  }

  const allSamplesList = Object.values(sampleDetailsMap);
  const currentWorkItems = [...roleWork.pending, ...roleWork.inProgress];
  const pastWorkItems = roleWork.completed;

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: '16px', maxWidth: '1280px', margin: '0 auto' }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '12px 16px',
          background: '#0f172a',
          color: '#ffffff',
          borderRadius: '8px',
          marginBottom: '16px'
        }}
      >
        <div>
          <h1 style={{ margin: 0, fontSize: '20px' }}>Lab Sample Pickup &amp; Delivery System</h1>
          <div style={{ fontSize: '13px', color: '#cbd5e1', marginTop: '4px' }}>
            Signed in as: <strong>{user?.username}</strong> | Active Role:{' '}
            <strong data-testid="active-role-indicator">{activeRole || 'None selected'}</strong>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <label htmlFor="active-role-select" style={{ fontSize: '14px' }}>
            Active Role
          </label>
          <select
            id="active-role-select"
            aria-label="Active Role"
            value={activeRole}
            onChange={(e) => handleSelectRole(e.target.value)}
            style={{ padding: '6px 10px', borderRadius: '4px' }}
          >
            <option value="">Select Role...</option>
            {(user?.roles || []).map((r: string) => (
              <option key={r} value={r}>
                {r}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={() => handleSelectRole(activeRole)}
            style={{ padding: '6px 10px', borderRadius: '4px', cursor: 'pointer' }}
          >
            Apply Role
          </button>
          <button
            type="button"
            onClick={handleSignOut}
            style={{
              padding: '6px 12px',
              background: '#dc2626',
              color: '#ffffff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Sign Out
          </button>
        </div>
      </header>

      {roleSelectionRequired && (
        <section
          role="region"
          aria-label="Select Role Context"
          style={{
            padding: '16px',
            marginBottom: '16px',
            background: '#fef3c7',
            border: '1px solid #f59e0b',
            borderRadius: '8px'
          }}
        >
          <h2 style={{ marginTop: 0, fontSize: '16px' }}>Select Active Role</h2>
          <p style={{ margin: '4px 0 12px' }}>
            Your account holds multiple roles. Please choose the role you are currently working under:
          </p>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {(user?.roles || []).map((r: string) => (
              <button
                key={r}
                type="button"
                onClick={() => handleSelectRole(r)}
                style={{
                  padding: '8px 14px',
                  background: '#0284c7',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer'
                }}
              >
                Work as {r}
              </button>
            ))}
          </div>
        </section>
      )}

      {actionAlert && (
        <div
          role="alert"
          style={{
            padding: '10px',
            marginBottom: '12px',
            background: '#fee2e2',
            color: '#991b1b',
            borderRadius: '6px'
          }}
        >
          {actionAlert}
        </div>
      )}

      <MapView
        locations={operations?.locations || locations}
        workers={operations?.workers || []}
        samples={operations?.samples || allSamplesList}
        routes={operations?.routes || []}
      />

      {/* Laboratory / Node Capacity Panel for laboratory_team, node_handler, or administrator */}
      {(activeRole === 'laboratory_team' || activeRole === 'node_handler' || assignedLocation) && assignedLocation && (
        <section
          aria-label="Laboratory Capacity"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#f8fafc'
          }}
        >
          <h2 style={{ marginTop: 0 }}>
            Facility Capacity — {assignedLocation.name} ({assignedLocation.locationId})
          </h2>
          <div style={{ display: 'flex', gap: '24px', marginBottom: '12px', flexWrap: 'wrap' }}>
            <div>
              <strong>Regular Capacity:</strong>{' '}
              <span>
                {assignedLocation.capacity?.capacityUnits ?? 0} configured /{' '}
                {assignedLocation.capacity?.reservedUnits ?? 0} reserved /{' '}
                {assignedLocation.capacity?.availableUnits ?? 0} available
              </span>
            </div>
            <div>
              <strong>Cooled Capacity:</strong>{' '}
              <span>
                {assignedLocation.capacity?.cooledCapacityUnits ?? 0} configured /{' '}
                {assignedLocation.capacity?.cooledReservedUnits ?? 0} reserved /{' '}
                {assignedLocation.capacity?.cooledAvailableUnits ?? 0} available
              </span>
            </div>
          </div>
          <form onSubmit={handleUpdateCapacity} style={{ display: 'flex', gap: '12px', alignItems: 'flex-end' }}>
            <div>
              <label htmlFor="reg-cap-input" style={{ display: 'block', fontSize: '13px' }}>
                Regular Capacity Units
              </label>
              <input
                id="reg-cap-input"
                aria-label="Regular Capacity Units"
                type="number"
                value={regCapInput}
                onChange={(e) => setRegCapInput(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <div>
              <label htmlFor="cooled-cap-input" style={{ display: 'block', fontSize: '13px' }}>
                Cooled Capacity Units
              </label>
              <input
                id="cooled-cap-input"
                aria-label="Cooled Capacity Units"
                type="number"
                value={cooledCapInput}
                onChange={(e) => setCooledCapInput(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <button type="submit" style={{ padding: '7px 14px', cursor: 'pointer' }}>
              Update Capacity
            </button>
            {capMsg && <span role="status">{capMsg}</span>}
          </form>
        </section>
      )}

      {/* Worker Location Recording Panel for collection_professional and delivery_partner */}
      {(activeRole === 'collection_professional' || activeRole === 'delivery_partner') && (
        <section
          aria-label="Record Worker Location"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#f8fafc'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Record Worker Location</h2>
          {workerLocError && (
            <div role="alert" style={{ color: '#991b1b', marginBottom: '8px' }}>
              {workerLocError}
            </div>
          )}
          {workerLocMsg && (
            <div role="status" style={{ color: '#166534', marginBottom: '8px', fontWeight: 600 }}>
              {workerLocMsg}
            </div>
          )}
          <form onSubmit={handleRecordWorkerLocation} style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', alignItems: 'flex-end' }}>
            <div>
              <label htmlFor="worker-assign-select" style={{ display: 'block', fontSize: '13px' }}>
                Assignment
              </label>
              <input
                id="worker-assign-select"
                aria-label="Assignment ID"
                type="text"
                value={locAssignmentId}
                onChange={(e) => setLocAssignmentId(e.target.value)}
                placeholder="Assignment ID"
                style={{ padding: '6px', width: '260px' }}
              />
            </div>
            <div>
              <label htmlFor="worker-lat-input" style={{ display: 'block', fontSize: '13px' }}>
                Location Latitude
              </label>
              <input
                id="worker-lat-input"
                aria-label="Location Latitude"
                type="number"
                step="any"
                value={workerLat}
                onChange={(e) => setWorkerLat(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <div>
              <label htmlFor="worker-lng-input" style={{ display: 'block', fontSize: '13px' }}>
                Location Longitude
              </label>
              <input
                id="worker-lng-input"
                aria-label="Location Longitude"
                type="number"
                step="any"
                value={workerLng}
                onChange={(e) => setWorkerLng(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <div>
              <label htmlFor="worker-seq-input" style={{ display: 'block', fontSize: '13px' }}>
                Location Sequence
              </label>
              <input
                id="worker-seq-input"
                aria-label="Location Sequence"
                type="number"
                value={workerSeq}
                onChange={(e) => setWorkerSeq(e.target.value)}
                style={{ padding: '6px', width: '80px' }}
              />
            </div>
            <button
              type="submit"
              style={{
                padding: '8px 14px',
                background: '#0284c7',
                color: '#ffffff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              Record Location
            </button>
          </form>
        </section>
      )}

      {/* Requester / Dispatcher Collection Request & Dry-Run Serviceability Form */}
      {(activeRole === 'requester' || activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section
          aria-label="Collection Request and Serviceability"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Create Collection Request &amp; Check Serviceability</h2>
          {requestFormError && (
            <div
              role="alert"
              aria-label="Request Validation Error"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: '#fee2e2',
                color: '#991b1b',
                borderRadius: '6px'
              }}
            >
              {requestFormError}
            </div>
          )}
          {requestSuccessMsg && (
            <div
              role="status"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: '#dcfce7',
                color: '#166534',
                borderRadius: '6px'
              }}
            >
              {requestSuccessMsg}
            </div>
          )}
          {serviceabilityResult && (
            <div
              role="status"
              aria-label="Serviceability Check Result"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: serviceabilityResult.serviceable ? '#e0f2fe' : '#fef3c7',
                borderRadius: '6px'
              }}
            >
              <strong>Serviceability Check (Dry Run):</strong>{' '}
              {serviceabilityResult.serviceable ? 'Serviceable' : 'Unserviceable'} — Reason:{' '}
              <code>{serviceabilityResult.reason}</code> (Snapshot Version: {serviceabilityResult.serviceabilityVersion})
            </div>
          )}
          <form onSubmit={handleCreateRequest} aria-label="Collection Request Form">
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '12px', marginBottom: '12px' }}>
              <div>
                <label htmlFor="req-origin-type" style={{ display: 'block', fontSize: '13px' }}>
                  Origin Type
                </label>
                <select
                  id="req-origin-type"
                  aria-label="Origin Type"
                  value={originType}
                  onChange={(e) => setOriginType(e.target.value)}
                  style={{ width: '100%', padding: '6px' }}
                >
                  <option value="home">home</option>
                  <option value="clinic">clinic</option>
                  <option value="node">node</option>
                </select>
              </div>
              <div>
                <label htmlFor="req-origin-lat" style={{ display: 'block', fontSize: '13px' }}>
                  Origin Latitude
                </label>
                <input
                  id="req-origin-lat"
                  aria-label="Origin Latitude"
                  type="text"
                  value={originLat}
                  onChange={(e) => setOriginLat(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-origin-lng" style={{ display: 'block', fontSize: '13px' }}>
                  Origin Longitude
                </label>
                <input
                  id="req-origin-lng"
                  aria-label="Origin Longitude"
                  type="text"
                  value={originLng}
                  onChange={(e) => setOriginLng(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-sample-type" style={{ display: 'block', fontSize: '13px' }}>
                  Sample Type
                </label>
                <select
                  id="req-sample-type"
                  aria-label="Sample Type"
                  value={selectedSampleTypeId}
                  onChange={(e) => handleSampleTypeChange(e.target.value)}
                  style={{ width: '100%', padding: '6px' }}
                >
                  {sampleTypes.map((st) => (
                    <option key={st.sampleTypeId} value={st.sampleTypeId}>
                      {st.name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label htmlFor="req-container-type" style={{ display: 'block', fontSize: '13px' }}>
                  Container Type
                </label>
                <input
                  id="req-container-type"
                  aria-label="Container Type"
                  type="text"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-min" style={{ display: 'block', fontSize: '13px' }}>
                  Temperature Min (C)
                </label>
                <input
                  id="req-temp-min"
                  aria-label="Temperature Min (C)"
                  type="text"
                  value={tempMin}
                  onChange={(e) => setTempMin(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-max" style={{ display: 'block', fontSize: '13px' }}>
                  Temperature Max (C)
