import React, { useEffect, useState, useCallback } from 'react';
import { MapView } from './MapView';

function makeIdempKey(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export const App: React.FC = () => {
  const [token, setToken] = useState<string>(() => localStorage.getItem('sessionToken') || '');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [authError, setAuthError] = useState('');

  const [user, setUser] = useState<any>(null);
  const [activeRole, setActiveRole] = useState<string>('');
  const [roleSelectionRequired, setRoleSelectionRequired] = useState<boolean>(false);
  const [sampleTypes, setSampleTypes] = useState<any[]>([]);
  const [locations, setLocations] = useState<any[]>([]);
  const [assignedLocation, setAssignedLocation] = useState<any>(null);

  const [roleWork, setRoleWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: []
  });
  const [sampleDetailsMap, setSampleDetailsMap] = useState<Record<string, any>>({});
  const [operations, setOperations] = useState<any>(null);
  const [auditEntries, setAuditEntries] = useState<any[]>([]);
  const [auditQuery, setAuditQuery] = useState('');
  const [auditActionFilter, setAuditActionFilter] = useState('');
  const [auditEntityFilter, setAuditEntityFilter] = useState('');

  // Request & Serviceability form state
  const [originType, setOriginType] = useState('home');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [selectedSampleTypeId, setSelectedSampleTypeId] = useState('');
  const [containerType, setContainerType] = useState('amber-vial');
  const [tempMin, setTempMin] = useState('2');
  const [tempMax, setTempMax] = useState('8');
  const [earliestCol, setEarliestCol] = useState('2026-10-16T09:00:00Z');
  const [latestCol, setLatestCol] = useState('2026-10-16T11:00:00Z');
  const [deliveryDeadline, setDeliveryDeadline] = useState('2026-10-16T16:00:00Z');
  const [serviceabilityResult, setServiceabilityResult] = useState<any>(null);
  const [requestFormError, setRequestFormError] = useState('');
  const [requestSuccessMsg, setRequestSuccessMsg] = useState('');

  // Worker location form state
  const [locAssignmentId, setLocAssignmentId] = useState('');
  const [workerLat, setWorkerLat] = useState('12.9750');
  const [workerLng, setWorkerLng] = useState('77.6010');
  const [workerSeq, setWorkerSeq] = useState('1');
  const [workerLocMsg, setWorkerLocMsg] = useState('');
  const [workerLocError, setWorkerLocError] = useState('');

  // Capacity configuration state
  const [regCapInput, setRegCapInput] = useState('');
  const [cooledCapInput, setCooledCapInput] = useState('');
  const [capMsg, setCapMsg] = useState('');

  // General action feedback
  const [actionAlert, setActionAlert] = useState('');

  const apiFetch = useCallback(
    async (path: string, options: RequestInit = {}, overrideToken?: string) => {
      const tok = overrideToken !== undefined ? overrideToken : token;
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        ...((options.headers as Record<string, string>) || {})
      };
      if (tok) {
        headers['Authorization'] = `Bearer ${tok}`;
      }
      const res = await fetch(path, { ...options, headers });
      let json: any = null;
      try {
        json = await res.json();
      } catch {
        json = null;
      }
      return { status: res.status, ok: res.ok, body: json };
    },
    [token]
  );

  const loadSampleDetails = useCallback(
    async (sampleIds: string[], tok?: string) => {
      const uniqueIds = Array.from(new Set(sampleIds.filter(Boolean)));
      if (uniqueIds.length === 0) return;

      const updated: Record<string, any> = {};
      for (const sid of uniqueIds) {
        const [stRes, lcRes] = await Promise.all([
          apiFetch(`/api/read-sample-state/${sid}`, { method: 'GET' }, tok),
          apiFetch('/api/read-sample-lifecycle', { method: 'POST', body: JSON.stringify({ sampleId: sid }) }, tok)
        ]);
        const stData = stRes.ok ? stRes.body?.data : null;
        const lcData = lcRes.ok ? lcRes.body?.data : null;
        const jId = stData?.activeJourneyId || lcData?.activeJourneyId;
        let jpData: any = null;
        if (jId) {
          const jpRes = await apiFetch('/api/read-journey-plan', { method: 'POST', body: JSON.stringify({ journeyId: jId }) }, tok);
          if (jpRes.ok) {
            jpData = jpRes.body?.data;
          }
        }
        if (stData || lcData) {
          updated[sid] = {
            ...(stData || {}),
            ...(lcData || {}),
            status: lcData?.status || stData?.state?.status || stData?.status,
            timeline: lcData?.timeline || stData?.timeline || [],
            journey: jpData
          };
        }
      }
      setSampleDetailsMap((prev) => ({ ...prev, ...updated }));
    },
    [apiFetch]
  );

  const refreshAll = useCallback(
    async (tok?: string) => {
      const activeTok = tok !== undefined ? tok : token;
      if (!activeTok) return;

      const bootRes = await apiFetch('/api/ui/bootstrap', { method: 'GET' }, activeTok);
      if (!bootRes.ok) {
        if (bootRes.status === 401) {
          localStorage.removeItem('sessionToken');
          setToken('');
          setUser(null);
        }
        return;
      }
      const bData = bootRes.body?.data || {};
      const u = bData.user || {};
      setUser(u);
      setActiveRole(u.activeRole || '');
      setRoleSelectionRequired(Boolean(u.roleSelectionRequired));
      const sts = bData.sampleTypes || [];
      setSampleTypes(sts);
      if (sts.length > 0 && !selectedSampleTypeId) {
        setSelectedSampleTypeId(sts[0].sampleTypeId);
        setContainerType(sts[0].containerType || 'amber-vial');
        setTempMin(String(sts[0].temperatureMinC ?? 2));
        setTempMax(String(sts[0].temperatureMaxC ?? 8));
      }
      setLocations(bData.locations || []);
      if (bData.assignedLocation) {
        setAssignedLocation(bData.assignedLocation);
        if (bData.assignedLocation.capacity) {
          setRegCapInput(String(bData.assignedLocation.capacity.capacityUnits ?? 10));
          setCooledCapInput(String(bData.assignedLocation.capacity.cooledCapacityUnits ?? 10));
        }
      } else {
        setAssignedLocation(null);
      }

      if (!u.roleSelectionRequired && u.activeRole) {
        const workRes = await apiFetch(
          '/api/list-role-work',
          { method: 'POST', body: JSON.stringify({ role: u.activeRole }) },
          activeTok
        );
        const sidsToLoad: string[] = [];
        if (workRes.ok && workRes.body?.data) {
          const rw = workRes.body.data;
          setRoleWork({
            pending: rw.pending || [],
            inProgress: rw.inProgress || [],
            completed: rw.completed || []
          });
          const allItems = [...(rw.pending || []), ...(rw.inProgress || []), ...(rw.completed || [])];
          allItems.forEach((it: any) => {
            if (it.sampleId) sidsToLoad.push(it.sampleId);
            if (Array.isArray(it.sampleIds)) sidsToLoad.push(...it.sampleIds);
          });
          const firstAssign = [...(rw.inProgress || []), ...(rw.pending || [])].find((it: any) => it.assignmentId);
          if (firstAssign && !locAssignmentId) {
            setLocAssignmentId(firstAssign.assignmentId);
          }
        }
        if (Array.isArray(bData.requesterSamples)) {
          bData.requesterSamples.forEach((s: any) => {
            if (s.sampleId) sidsToLoad.push(s.sampleId);
          });
        }
        if (u.activeRole === 'dispatcher' || u.activeRole === 'administrator') {
          const [opsRes, audRes] = await Promise.all([
            apiFetch('/api/read-operations-state', { method: 'POST', body: JSON.stringify({}) }, activeTok),
            apiFetch('/api/search-audit-trail', { method: 'POST', body: JSON.stringify({ limit: 100 }) }, activeTok)
          ]);
          if (opsRes.ok && opsRes.body?.data) {
            setOperations(opsRes.body.data);
            (opsRes.body.data.samples || []).forEach((s: any) => {
              if (s.sampleId) sidsToLoad.push(s.sampleId);
            });
          }
          if (audRes.ok && audRes.body?.data) {
            setAuditEntries(audRes.body.data.entries || []);
          }
        }
        if (sidsToLoad.length > 0) {
          await loadSampleDetails(sidsToLoad, activeTok);
        }
      }
    },
    [apiFetch, loadSampleDetails, locAssignmentId, selectedSampleTypeId, token]
  );

  useEffect(() => {
    if (token) {
      refreshAll(token);
    }
  }, [token, refreshAll]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (!username.trim() || !password) {
      setAuthError('Username and password are required');
      return;
    }
    const res = await apiFetch(
      '/api/authenticate-user',
      {
        method: 'POST',
        body: JSON.stringify({ username: username.trim(), password })
      },
      ''
    );
    if (!res.ok) {
      const errMsg = res.body?.error || 'Invalid username or password';
      const errCode = res.body?.code || 'invalid_credentials';
      setAuthError(`${errMsg} (${errCode})`);
      return;
    }
    const data = res.body?.data;
    const tok = data.sessionToken;
    localStorage.setItem('sessionToken', tok);
    setToken(tok);
    await refreshAll(tok);
  };

  const handleSignOut = () => {
    localStorage.removeItem('sessionToken');
    setToken('');
    setUser(null);
    setActiveRole('');
    setRoleWork({ pending: [], inProgress: [], completed: [] });
    setOperations(null);
    setAuditEntries([]);
    setAuthError('');
  };

  const handleSelectRole = async (newRole: string) => {
    if (!newRole) return;
    setActionAlert('');
    const res = await apiFetch('/api/select-active-role', {
      method: 'POST',
      body: JSON.stringify({ role: newRole })
    });
    if (!res.ok) {
      setActionAlert(res.body?.error || 'Failed to switch role');
      return;
    }
    setActiveRole(newRole);
    setRoleSelectionRequired(false);
    await refreshAll();
  };

  const handleSampleTypeChange = (stId: string) => {
    setSelectedSampleTypeId(stId);
    const st = sampleTypes.find((s) => s.sampleTypeId === stId);
    if (st) {
      setContainerType(st.containerType || 'amber-vial');
      setTempMin(String(st.temperatureMinC ?? 2));
      setTempMax(String(st.temperatureMaxC ?? 8));
    }
  };

  const handleCheckServiceability = async () => {
    setRequestFormError('');
    setRequestSuccessMsg('');
    setServiceabilityResult(null);

    const lat = Number(originLat);
    const lng = Number(originLng);
    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      setRequestFormError('Invalid origin coordinates (invalid_origin)');
      return;
    }
    if (!selectedSampleTypeId) {
      setRequestFormError('Please select a sample type (invalid_sample_type)');
      return;
    }

    const res = await apiFetch('/api/check-serviceability', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        sampleTypeId: selectedSampleTypeId,
        requestedAt: earliestCol,
        earliestCollectionAt: earliestCol,
        latestCollectionAt: latestCol,
        deliveryDeadline
      })
    });
    if (!res.ok) {
      setRequestFormError(`${res.body?.error || 'Validation error'} (${res.body?.code || 'invalid_request'})`);
      return;
    }
    setServiceabilityResult(res.body?.data);
  };

  const handleCreateRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setRequestFormError('');
    setRequestSuccessMsg('');

    const lat = Number(originLat);
    const lng = Number(originLng);
    const tMin = Number(tempMin);
    const tMax = Number(tempMax);

    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      setRequestFormError('Validation error: Origin coordinates out of bounds (invalid_origin)');
      return;
    }
    if (!containerType.trim() || Number.isNaN(tMin) || Number.isNaN(tMax) || tMin >= tMax) {
      setRequestFormError('Validation error: Invalid container or temperature range (handling_mismatch)');
      return;
    }

    const res = await apiFetch('/api/create-collection-request', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        requestedAt: earliestCol,
        earliestCollectionAt: earliestCol,
        latestCollectionAt: latestCol,
        deliveryDeadline,
        sampleTypeId: selectedSampleTypeId,
        containerType: containerType.trim(),
        temperatureMinC: tMin,
        temperatureMaxC: tMax,
        idempotencyKey: makeIdempKey('req')
      })
    });
    if (!res.ok) {
      setRequestFormError(`${res.body?.error || 'Request validation failed'} (${res.body?.code || 'validation_error'})`);
      return;
    }
    const created = res.body?.data;
    setRequestSuccessMsg(`Created sample ${created.sampleId} (${created.serviceability})`);
    await refreshAll();
  };

  const handleAcceptAssignment = async (assignmentId: string) => {
    setActionAlert('');
    const res = await apiFetch('/api/accept-assignment', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        idempotencyKey: makeIdempKey('accept')
      })
    });
    if (!res.ok) {
      setActionAlert(`${res.body?.error || 'Failed to accept assignment'} (${res.body?.code || 'error'})`);
      return;
    }
    setLocAssignmentId(assignmentId);
    await refreshAll();
  };

  const handleDeclineAssignment = async (assignmentId: string) => {
    setActionAlert('');
    const res = await apiFetch('/api/decline-assignment', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        reason: 'Worker declined via UI',
        declinedAt: new Date().toISOString(),
        idempotencyKey: makeIdempKey('decline')
      })
    });
    if (!res.ok) {
      setActionAlert(`${res.body?.error || 'Failed to decline assignment'} (${res.body?.code || 'error'})`);
      return;
    }
    await refreshAll();
  };

  const handleRecordWorkerLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setWorkerLocError('');
    setWorkerLocMsg('');
    const targetAssignId =
      locAssignmentId ||
      [...roleWork.inProgress, ...roleWork.pending].find((a: any) => a.assignmentId)?.assignmentId ||
      '';
    if (!targetAssignId) {
      setWorkerLocError('No active assignment selected');
      return;
    }
    const res = await apiFetch('/api/record-worker-location', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId: targetAssignId,
        coordinate: {
          latitude: Number(workerLat),
          longitude: Number(workerLng)
        },
        sequence: Number(workerSeq),
        recordedAt: new Date().toISOString()
      })
    });
    if (!res.ok) {
      setWorkerLocError(`${res.body?.error || 'Failed to record location'} (${res.body?.code || 'error'})`);
      return;
    }
    const d = res.body?.data;
    setWorkerLocMsg(
      `Recorded Location: ${d.coordinate.latitude}, ${d.coordinate.longitude} (seq ${d.sequence}) at ${d.recordedAt}`
    );
    setWorkerSeq(String(Number(workerSeq) + 1));
    await refreshAll();
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    setCapMsg('');
    if (!assignedLocation?.locationId) return;
    const res = await apiFetch('/api/configure-capacity', {
      method: 'POST',
      body: JSON.stringify({
        resourceId: assignedLocation.locationId,
        capacityUnits: Number(regCapInput),
        cooledCapacityUnits: Number(cooledCapInput)
      })
    });
    if (!res.ok) {
      setCapMsg(`Error: ${res.body?.error} (${res.body?.code})`);
      return;
    }
    setCapMsg('Capacity updated');
    await refreshAll();
  };

  const handleSearchAudit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const payload: Record<string, any> = { limit: 100 };
    if (auditQuery.trim()) payload.query = auditQuery.trim();
    if (auditActionFilter.trim()) payload.action = auditActionFilter.trim();
    if (auditEntityFilter.trim()) payload.entityId = auditEntityFilter.trim();

    const res = await apiFetch('/api/search-audit-trail', {
      method: 'POST',
      body: JSON.stringify(payload)
    });
    if (res.ok && res.body?.data) {
      setAuditEntries(res.body.data.entries || []);
    }
  };

  if (!token) {
    return (
      <main
        style={{
          maxWidth: '460px',
          margin: '60px auto',
          padding: '24px',
          border: '1px solid #cbd5e1',
          borderRadius: '8px',
          fontFamily: 'system-ui, sans-serif',
          background: '#ffffff'
        }}
      >
        <h1>Lab Sample Pickup &amp; Delivery System</h1>
        <h2>Sign In</h2>
        {authError && (
          <div
            role="alert"
            aria-label="Authentication Error"
            style={{
              padding: '10px',
              marginBottom: '12px',
              background: '#fee2e2',
              color: '#991b1b',
              borderRadius: '6px'
            }}
          >
            {authError}
          </div>
        )}
        <form onSubmit={handleLogin} aria-label="Sign In Form">
          <div style={{ marginBottom: '12px' }}>
            <label htmlFor="username-input" style={{ display: 'block', marginBottom: '4px', fontWeight: 600 }}>
              Username
            </label>
            <input
              id="username-input"
              name="username"
              aria-label="Username"
              type="text"
              placeholder="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            />
          </div>
          <div style={{ marginBottom: '16px' }}>
            <label htmlFor="password-input" style={{ display: 'block', marginBottom: '4px', fontWeight: 600 }}>
              Password
            </label>
            <input
              id="password-input"
              name="password"
              aria-label="Password"
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            />
          </div>
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '10px',
              background: '#0284c7',
              color: '#ffffff',
              border: 'none',
              borderRadius: '6px',
              fontWeight: 600,
              cursor: 'pointer'
            }}
          >
            Sign In
          </button>
        </form>
      </main>
    );
  }

  const allSamplesList = Object.values(sampleDetailsMap);
  const currentWorkItems = [...roleWork.pending, ...roleWork.inProgress];
  const pastWorkItems = roleWork.completed;

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: '16px', maxWidth: '1280px', margin: '0 auto' }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '12px 16px',
          background: '#0f172a',
          color: '#ffffff',
          borderRadius: '8px',
          marginBottom: '16px'
        }}
      >
        <div>
          <h1 style={{ margin: 0, fontSize: '20px' }}>Lab Sample Pickup &amp; Delivery System</h1>
          <div style={{ fontSize: '13px', color: '#cbd5e1', marginTop: '4px' }}>
            Signed in as: <strong>{user?.username}</strong> | Active Role:{' '}
            <strong data-testid="active-role-indicator">{activeRole || 'None selected'}</strong>
          </div>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <label htmlFor="active-role-select" style={{ fontSize: '14px' }}>
            Active Role
          </label>
          <select
            id="active-role-select"
            aria-label="Active Role"
            value={activeRole}
            onChange={(e) => handleSelectRole(e.target.value)}
            style={{ padding: '6px 10px', borderRadius: '4px' }}
          >
            <option value="">Select Role...</option>
            {(user?.roles || []).map((r: string) => (
              <option key={r} value={r}>
                {r}
              </option>
            ))}
          </select>
          <button
            type="button"
            onClick={() => handleSelectRole(activeRole)}
            style={{ padding: '6px 10px', borderRadius: '4px', cursor: 'pointer' }}
          >
            Apply Role
          </button>
          <button
            type="button"
            onClick={handleSignOut}
            style={{
              padding: '6px 12px',
              background: '#dc2626',
              color: '#ffffff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer'
            }}
          >
            Sign Out
          </button>
        </div>
      </header>

      {roleSelectionRequired && (
        <section
          role="region"
          aria-label="Select Role Context"
          style={{
            padding: '16px',
            marginBottom: '16px',
            background: '#fef3c7',
            border: '1px solid #f59e0b',
            borderRadius: '8px'
          }}
        >
          <h2 style={{ marginTop: 0, fontSize: '16px' }}>Select Active Role</h2>
          <p style={{ margin: '4px 0 12px' }}>
            Your account holds multiple roles. Please choose the role you are currently working under:
          </p>
          <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
            {(user?.roles || []).map((r: string) => (
              <button
                key={r}
                type="button"
                onClick={() => handleSelectRole(r)}
                style={{
                  padding: '8px 14px',
                  background: '#0284c7',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer'
                }}
              >
                Work as {r}
              </button>
            ))}
          </div>
        </section>
      )}

      {actionAlert && (
        <div
          role="alert"
          style={{
            padding: '10px',
            marginBottom: '12px',
            background: '#fee2e2',
            color: '#991b1b',
            borderRadius: '6px'
          }}
        >
          {actionAlert}
        </div>
      )}

      <MapView
        locations={operations?.locations || locations}
        workers={operations?.workers || []}
        samples={operations?.samples || allSamplesList}
        routes={operations?.routes || []}
      />

      {/* Laboratory / Node Capacity Panel for laboratory_team, node_handler, or administrator */}
      {(activeRole === 'laboratory_team' || activeRole === 'node_handler' || assignedLocation) && assignedLocation && (
        <section
          aria-label="Laboratory Capacity"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#f8fafc'
          }}
        >
          <h2 style={{ marginTop: 0 }}>
            Facility Capacity — {assignedLocation.name} ({assignedLocation.locationId})
          </h2>
          <div style={{ display: 'flex', gap: '24px', marginBottom: '12px', flexWrap: 'wrap' }}>
            <div>
              <strong>Regular Capacity:</strong>{' '}
              <span>
                {assignedLocation.capacity?.capacityUnits ?? 0} configured /{' '}
                {assignedLocation.capacity?.reservedUnits ?? 0} reserved /{' '}
                {assignedLocation.capacity?.availableUnits ?? 0} available
              </span>
            </div>
            <div>
              <strong>Cooled Capacity:</strong>{' '}
              <span>
                {assignedLocation.capacity?.cooledCapacityUnits ?? 0} configured /{' '}
                {assignedLocation.capacity?.cooledReservedUnits ?? 0} reserved /{' '}
                {assignedLocation.capacity?.cooledAvailableUnits ?? 0} available
              </span>
            </div>
          </div>
          <form onSubmit={handleUpdateCapacity} style={{ display: 'flex', gap: '12px', alignItems: 'flex-end' }}>
            <div>
              <label htmlFor="reg-cap-input" style={{ display: 'block', fontSize: '13px' }}>
                Regular Capacity Units
              </label>
              <input
                id="reg-cap-input"
                aria-label="Regular Capacity Units"
                type="number"
                value={regCapInput}
                onChange={(e) => setRegCapInput(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <div>
              <label htmlFor="cooled-cap-input" style={{ display: 'block', fontSize: '13px' }}>
                Cooled Capacity Units
              </label>
              <input
                id="cooled-cap-input"
                aria-label="Cooled Capacity Units"
                type="number"
                value={cooledCapInput}
                onChange={(e) => setCooledCapInput(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <button type="submit" style={{ padding: '7px 14px', cursor: 'pointer' }}>
              Update Capacity
            </button>
            {capMsg && <span role="status">{capMsg}</span>}
          </form>
        </section>
      )}

      {/* Worker Location Recording Panel for collection_professional and delivery_partner */}
      {(activeRole === 'collection_professional' || activeRole === 'delivery_partner') && (
        <section
          aria-label="Record Worker Location"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#f8fafc'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Record Worker Location</h2>
          {workerLocError && (
            <div role="alert" style={{ color: '#991b1b', marginBottom: '8px' }}>
              {workerLocError}
            </div>
          )}
          {workerLocMsg && (
            <div role="status" style={{ color: '#166534', marginBottom: '8px', fontWeight: 600 }}>
              {workerLocMsg}
            </div>
          )}
          <form onSubmit={handleRecordWorkerLocation} style={{ display: 'flex', gap: '12px', flexWrap: 'wrap', alignItems: 'flex-end' }}>
            <div>
              <label htmlFor="worker-assign-select" style={{ display: 'block', fontSize: '13px' }}>
                Assignment
              </label>
              <input
                id="worker-assign-select"
                aria-label="Assignment ID"
                type="text"
                value={locAssignmentId}
                onChange={(e) => setLocAssignmentId(e.target.value)}
                placeholder="Assignment ID"
                style={{ padding: '6px', width: '260px' }}
              />
            </div>
            <div>
              <label htmlFor="worker-lat-input" style={{ display: 'block', fontSize: '13px' }}>
                Location Latitude
              </label>
              <input
                id="worker-lat-input"
                aria-label="Location Latitude"
                type="number"
                step="any"
                value={workerLat}
                onChange={(e) => setWorkerLat(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <div>
              <label htmlFor="worker-lng-input" style={{ display: 'block', fontSize: '13px' }}>
                Location Longitude
              </label>
              <input
                id="worker-lng-input"
                aria-label="Location Longitude"
                type="number"
                step="any"
                value={workerLng}
                onChange={(e) => setWorkerLng(e.target.value)}
                style={{ padding: '6px', width: '120px' }}
              />
            </div>
            <div>
              <label htmlFor="worker-seq-input" style={{ display: 'block', fontSize: '13px' }}>
                Location Sequence
              </label>
              <input
                id="worker-seq-input"
                aria-label="Location Sequence"
                type="number"
                value={workerSeq}
                onChange={(e) => setWorkerSeq(e.target.value)}
                style={{ padding: '6px', width: '80px' }}
              />
            </div>
            <button
              type="submit"
              style={{
                padding: '8px 14px',
                background: '#0284c7',
                color: '#ffffff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              Record Location
            </button>
          </form>
        </section>
      )}

      {/* Requester / Dispatcher Collection Request & Dry-Run Serviceability Form */}
      {(activeRole === 'requester' || activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section
          aria-label="Collection Request and Serviceability"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Create Collection Request &amp; Check Serviceability</h2>
          {requestFormError && (
            <div
              role="alert"
              aria-label="Request Validation Error"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: '#fee2e2',
                color: '#991b1b',
                borderRadius: '6px'
              }}
            >
              {requestFormError}
            </div>
          )}
          {requestSuccessMsg && (
            <div
              role="status"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: '#dcfce7',
                color: '#166534',
                borderRadius: '6px'
              }}
            >
              {requestSuccessMsg}
            </div>
          )}
          {serviceabilityResult && (
            <div
              role="status"
              aria-label="Serviceability Check Result"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: serviceabilityResult.serviceable ? '#e0f2fe' : '#fef3c7',
                borderRadius: '6px'
              }}
            >
              <strong>Serviceability Check (Dry Run):</strong>{' '}
              {serviceabilityResult.serviceable ? 'Serviceable' : 'Unserviceable'} — Reason:{' '}
              <code>{serviceabilityResult.reason}</code> (Snapshot Version: {serviceabilityResult.serviceabilityVersion})
            </div>
          )}
          <form onSubmit={handleCreateRequest} aria-label="Collection Request Form">
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '12px', marginBottom: '12px' }}>
              <div>
                <label htmlFor="req-origin-type" style={{ display: 'block', fontSize: '13px' }}>
                  Origin Type
                </label>
                <select
                  id="req-origin-type"
                  aria-label="Origin Type"
                  value={originType}
                  onChange={(e) => setOriginType(e.target.value)}
                  style={{ width: '100%', padding: '6px' }}
                >
                  <option value="home">home</option>
                  <option value="clinic">clinic</option>
                  <option value="node">node</option>
                </select>
              </div>
              <div>
                <label htmlFor="req-origin-lat" style={{ display: 'block', fontSize: '13px' }}>
                  Origin Latitude
                </label>
                <input
                  id="req-origin-lat"
                  aria-label="Origin Latitude"
                  type="text"
                  value={originLat}
                  onChange={(e) => setOriginLat(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-origin-lng" style={{ display: 'block', fontSize: '13px' }}>
                  Origin Longitude
                </label>
                <input
                  id="req-origin-lng"
                  aria-label="Origin Longitude"
                  type="text"
                  value={originLng}
                  onChange={(e) => setOriginLng(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-sample-type" style={{ display: 'block', fontSize: '13px' }}>
                  Sample Type
                </label>
                <select
                  id="req-sample-type"
                  aria-label="Sample Type"
                  value={selectedSampleTypeId}
                  onChange={(e) => handleSampleTypeChange(e.target.value)}
                  style={{ width: '100%', padding: '6px' }}
                >
                  {sampleTypes.map((st) => (
                    <option key={st.sampleTypeId} value={st.sampleTypeId}>
                      {st.name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label htmlFor="req-container-type" style={{ display: 'block', fontSize: '13px' }}>
                  Container Type
                </label>
                <input
                  id="req-container-type"
                  aria-label="Container Type"
                  type="text"
                  value={containerType}
                  onChange={(e) => setContainerType(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-min" style={{ display: 'block', fontSize: '13px' }}>
                  Temperature Min (C)
                </label>
                <input
                  id="req-temp-min"
                  aria-label="Temperature Min (C)"
                  type="text"
                  value={tempMin}
                  onChange={(e) => setTempMin(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-temp-max" style={{ display: 'block', fontSize: '13px' }}>
                  Temperature Max (C)
                </label>
                <input
                  id="req-temp-max"
                  aria-label="Temperature Max (C)"
                  type="text"
                  value={tempMax}
                  onChange={(e) => setTempMax(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-earliest-col" style={{ display: 'block', fontSize: '13px' }}>
                  Collection Window Start
                </label>
                <input
                  id="req-earliest-col"
                  aria-label="Collection Window Start"
                  type="text"
                  value={earliestCol}
                  onChange={(e) => setEarliestCol(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-latest-col" style={{ display: 'block', fontSize: '13px' }}>
                  Collection Window End
                </label>
                <input
                  id="req-latest-col"
                  aria-label="Collection Window End"
                  type="text"
                  value={latestCol}
                  onChange={(e) => setLatestCol(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
              <div>
                <label htmlFor="req-deadline" style={{ display: 'block', fontSize: '13px' }}>
                  Delivery Deadline
                </label>
                <input
                  id="req-deadline"
                  aria-label="Delivery Deadline"
                  type="text"
                  value={deliveryDeadline}
                  onChange={(e) => setDeliveryDeadline(e.target.value)}
                  style={{ width: '100%', padding: '6px', boxSizing: 'border-box' }}
                />
              </div>
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button
                type="button"
                onClick={handleCheckServiceability}
                style={{
                  padding: '8px 14px',
                  background: '#475569',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                Check Serviceability
              </button>
              <button
                type="submit"
                style={{
                  padding: '8px 14px',
                  background: '#0284c7',
                  color: '#ffffff',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                Create Collection Request
              </button>
            </div>
          </form>
        </section>
      )}

      {/* Role Work View: Current Work and Past/Completed Work */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '16px' }}>
        <section
          aria-label="Current Work"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Current Work ({currentWorkItems.length})</h2>
          {currentWorkItems.length === 0 ? (
            <p style={{ color: '#64748b' }}>No current work items.</p>
          ) : (
            currentWorkItems.map((item: any, idx: number) => {
              const id = item.assignmentId || item.sampleId || item.journeyId || `item-${idx}`;
              const smp = item.sampleId ? sampleDetailsMap[item.sampleId] : null;
              return (
                <article
                  key={id}
                  aria-label={`Work Item ${id}`}
                  style={{
                    border: '1px solid #e2e8f0',
                    borderRadius: '6px',
                    padding: '12px',
                    marginBottom: '10px',
                    background: '#f8fafc'
                  }}
                >
                  <div>
                    <strong>{item.kind || 'work'}:</strong> <code>{id}</code> — Status:{' '}
                    <strong>{item.status}</strong>
                  </div>
                  {item.sampleId && (
                    <div style={{ fontSize: '13px', marginTop: '4px' }}>
                      Sample ID: <code>{item.sampleId}</code>
                    </div>
                  )}
                  {item.destinationCapacity && (
                    <div style={{ fontSize: '13px', marginTop: '4px' }}>
                      Destination Capacity: {item.destinationCapacity.availableUnits}/
                      {item.destinationCapacity.capacityUnits} regular,{' '}
                      {item.destinationCapacity.cooledAvailableUnits}/
                      {item.destinationCapacity.cooledCapacityUnits} cooled
                    </div>
                  )}
                  {item.assignmentId && (item.status === 'offered' || item.status === 'pending') && (
                    <div style={{ display: 'flex', gap: '8px', marginTop: '8px' }}>
                      <button
                        type="button"
                        onClick={() => handleAcceptAssignment(item.assignmentId)}
                        style={{
                          padding: '6px 12px',
                          background: '#16a34a',
                          color: '#ffffff',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: 'pointer'
                        }}
                      >
                        Accept Assignment
                      </button>
                      <button
                        type="button"
                        onClick={() => handleDeclineAssignment(item.assignmentId)}
                        style={{
                          padding: '6px 12px',
                          background: '#dc2626',
                          color: '#ffffff',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: 'pointer'
                        }}
                      >
                        Decline Assignment
                      </button>
                    </div>
                  )}
                  {Array.isArray(item.history) && item.history.length > 0 && (
                    <div style={{ marginTop: '8px' }}>
                      <strong style={{ fontSize: '12px' }}>Status History:</strong>
                      <ol aria-label="Status History" style={{ margin: '4px 0 0', paddingLeft: '20px', fontSize: '12px' }}>
                        {item.history.map((h: any, hIdx: number) => (
                          <li key={h.eventId || hIdx}>
                            {h.action} — {h.occurredAt} ({h.role})
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                  {smp && (
                    <div style={{ marginTop: '8px', fontSize: '12px', borderTop: '1px dashed #cbd5e1', paddingTop: '6px' }}>
                      <div>
                        Custodian: <strong>{smp.currentHolderId || 'Unassigned'}</strong> | Freshness:{' '}
                        <strong>{smp.locationStale ? 'Stale' : 'Fresh'}</strong>
                      </div>
                    </div>
                  )}
                </article>
              );
            })
          )}
        </section>

        <section
          aria-label="Past Work"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Past &amp; Completed Work ({pastWorkItems.length})</h2>
          {pastWorkItems.length === 0 ? (
            <p style={{ color: '#64748b' }}>No completed work items.</p>
          ) : (
            pastWorkItems.map((item: any, idx: number) => {
              const id = item.assignmentId || item.sampleId || item.journeyId || `past-${idx}`;
              return (
                <article
                  key={id}
                  aria-label={`Completed Work Item ${id}`}
                  style={{
                    border: '1px solid #e2e8f0',
                    borderRadius: '6px',
                    padding: '12px',
                    marginBottom: '10px',
                    background: '#f8fafc'
                  }}
                >
                  <div>
                    <strong>{item.kind || 'work'}:</strong> <code>{id}</code> — Status:{' '}
                    <strong>{item.status}</strong>
                  </div>
                  {Array.isArray(item.history) && item.history.length > 0 && (
                    <div style={{ marginTop: '8px' }}>
                      <strong style={{ fontSize: '12px' }}>Status History:</strong>
                      <ol aria-label="Completed Status History" style={{ margin: '4px 0 0', paddingLeft: '20px', fontSize: '12px' }}>
                        {item.history.map((h: any, hIdx: number) => (
                          <li key={h.eventId || hIdx}>
                            {h.action} — {h.occurredAt} ({h.role})
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </article>
              );
            })
          )}
        </section>
      </div>

      {/* Detailed Sample Views (Status History, Custodian, Location, Route Progress, Freshness, Exceptions) */}
      {allSamplesList.length > 0 && (
        <section
          aria-label="Sample Tracking Details"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Sample Tracking, Custody &amp; Status Timeline</h2>
          {allSamplesList.map((smp: any) => {
            const loc = smp.latestLocation || smp.origin;
            const legs = smp.journey?.legs || [];
            const completedCount = (smp.completedLegIds || []).length;
            const hasException =
              smp.status === 'exception' || smp.status === 'expired' || Boolean(smp.exception);
            return (
              <article
                key={smp.sampleId}
                aria-label={`Sample ${smp.sampleId}`}
                style={{
                  border: '1px solid #cbd5e1',
                  borderRadius: '6px',
                  padding: '14px',
                  marginBottom: '12px',
                  background: hasException ? '#fff1f2' : '#f8fafc'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px' }}>
                  <div>
                    <strong>Sample ID:</strong> <code>{smp.sampleId}</code> | <strong>Status:</strong>{' '}
                    <span>{smp.status}</span>
                  </div>
                  <div>
                    <strong>Location Freshness:</strong>{' '}
                    <span
                      style={{
                        padding: '2px 8px',
                        borderRadius: '4px',
                        background: smp.locationStale ? '#fef3c7' : '#dcfce7',
                        color: smp.locationStale ? '#92400e' : '#166534',
                        fontWeight: 600
                      }}
                    >
                      {smp.locationStale ? 'Stale' : 'Fresh'}
                    </span>{' '}
                    (Last Updated: {smp.locationRecordedAt || smp.requestedAt || 'N/A'})
                  </div>
                </div>

                {hasException && (
                  <div
                    role="alert"
                    aria-label="Sample Exception Flag"
                    style={{
                      marginTop: '8px',
                      padding: '8px 12px',
                      background: '#fee2e2',
                      color: '#991b1b',
                      borderRadius: '4px',
                      fontWeight: 600
                    }}
                  >
                    Exception Flag: {smp.status} —{' '}
                    {smp.exception?.reason || smp.exception?.code || 'Exception recorded'}
                  </div>
                )}

                <div style={{ marginTop: '8px', fontSize: '14px', display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                  <div>
                    <strong>Current Custodian:</strong> {smp.currentHolderId || 'Pending collection'}
                  </div>
                  <div>
                    <strong>Current Location:</strong>{' '}
                    {loc ? `${loc.latitude}, ${loc.longitude}` : 'Unknown'}
                  </div>
                  <div>
                    <strong>Route Progress:</strong> {completedCount} / {legs.length} transport legs completed (
                    {smp.journey?.routeMode || 'direct'})
                  </div>
                </div>

                {Array.isArray(smp.timeline) && smp.timeline.length > 0 && (
                  <div style={{ marginTop: '10px' }}>
                    <strong>Ordered Status Timeline:</strong>
                    <ol aria-label="Ordered Status History" style={{ margin: '4px 0 0', paddingLeft: '20px', fontSize: '13px' }}>
                      {smp.timeline.map((entry: any, idx: number) => (
                        <li key={entry.eventId || idx}>
                          <strong>{entry.action}</strong> — {entry.occurredAt} (Actor: {entry.actorId}, Role: {entry.role})
                        </li>
                      ))}
                    </ol>
                  </div>
                )}
              </article>
            );
          })}
        </section>
      )}

      {/* Operations Monitor Dashboard for Dispatcher & Administrator */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && operations && (
        <section
          aria-label="Monitor Dashboard"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Operations Monitor Dashboard</h2>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: '12px' }}>
            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Samples ({(operations.samples || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.samples || []).map((s: any) => (
                  <li key={s.sampleId}>
                    {s.sampleId} — {s.status} | Holder: {s.currentHolderId || 'none'} |{' '}
                    {s.locationStale ? 'Stale' : 'Fresh'}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Workers ({(operations.workers || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.workers || []).map((w: any) => (
                  <li key={w.workerId}>
                    {w.fullName || w.workerId} — {w.status} (Assignments: {w.assignmentCount})
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Collection Nodes ({(operations.locations || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.locations || []).map((l: any) => (
                  <li key={l.locationId}>
                    {l.name} ({l.active ? 'Active' : 'Inactive'}) — Cap:{' '}
                    {l.capacity?.availableUnits}/{l.capacity?.capacityUnits}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>
                Laboratories ({(operations.locations || []).filter((l: any) => l.functions?.laboratory).length})
              </h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.locations || [])
                  .filter((l: any) => l.functions?.laboratory)
                  .map((l: any) => (
                    <li key={l.locationId}>
                      {l.name} — Accepted Types: {(l.acceptedSampleTypeIds || []).length}
                    </li>
                  ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Routes ({(operations.routes || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.routes || []).map((rt: any) => (
                  <li key={rt.journeyId}>
                    {rt.journeyId} — {rt.routeMode} ({rt.status})
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Exceptions ({(operations.exceptions || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.exceptions || []).map((ex: any, i: number) => (
                  <li key={ex.sampleId || i}>
                    {ex.sampleId} — {ex.reason || ex.status}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </section>
      )}

      {/* Searchable Audit Trail for Dispatcher & Administrator */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section
          aria-label="Audit Trail"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Audit Trail &amp; Compliance Search</h2>
          <form
            onSubmit={handleSearchAudit}
            style={{ display: 'flex', gap: '12px', marginBottom: '12px', flexWrap: 'wrap', alignItems: 'flex-end' }}
          >
            <div>
              <label htmlFor="audit-search-input" style={{ display: 'block', fontSize: '13px' }}>
                Search Audit Logs
              </label>
              <input
                id="audit-search-input"
                aria-label="Search Audit Logs"
                type="text"
                placeholder="Search audit trail..."
                value={auditQuery}
                onChange={(e) => setAuditQuery(e.target.value)}
                style={{ padding: '6px', width: '240px' }}
              />
            </div>
            <div>
              <label htmlFor="audit-action-input" style={{ display: 'block', fontSize: '13px' }}>
                Filter by Action
              </label>
              <input
                id="audit-action-input"
                aria-label="Filter by Action"
                type="text"
                placeholder="e.g. authenticate_user"
                value={auditActionFilter}
                onChange={(e) => setAuditActionFilter(e.target.value)}
                style={{ padding: '6px', width: '180px' }}
              />
            </div>
            <div>
              <label htmlFor="audit-entity-input" style={{ display: 'block', fontSize: '13px' }}>
                Filter by Entity ID
              </label>
              <input
                id="audit-entity-input"
                aria-label="Filter by Entity ID"
                type="text"
                placeholder="Entity ID"
                value={auditEntityFilter}
                onChange={(e) => setAuditEntityFilter(e.target.value)}
                style={{ padding: '6px', width: '220px' }}
              />
            </div>
            <button
              type="submit"
              style={{
                padding: '7px 14px',
                background: '#0284c7',
                color: '#ffffff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              Search Audit
            </button>
          </form>

          <div style={{ maxHeight: '320px', overflowY: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
              <thead>
                <tr style={{ background: '#f1f5f9', textAlign: 'left' }}>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Time</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Action</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Actor</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Role</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Entity</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Outcome</th>
                </tr>
              </thead>
              <tbody>
                {auditEntries.map((entry: any) => (
                  <tr key={entry.eventId}>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>{entry.occurredAt}</td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>
                      <strong>{entry.action}</strong>
                    </td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>{entry.actorId}</td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>{entry.role}</td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>
                      {entry.entityType}: {entry.entityId}
                    </td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>
                      {entry.success ? 'Success' : 'Denied'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}
    </div>
  );
};

