		FromLocationID *string  `json:"fromLocationId"`
		ToLocationID   *string  `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if err := decodeStrictJSON(raw, &req); err != nil || req.FromLocationID == nil || req.ToLocationID == nil || req.TravelMinutes == nil || req.CostUnits == nil || req.Active == nil {
		writeError(w, http.StatusBadRequest, "invalid_json", "invalid JSON payload")
		return
	}

	srv.store.mu.Lock()
	defer srv.store.mu.Unlock()

	ac, authErr := srv.requireRoleLocked(r, "create_connection", "connection", "", true, "administrator")
