		_ = srv.store.saveLocked(r.Context())
		writeError(w, authErr.status, authErr.code, authErr.msg)
		return
	}

	fromID := strings.TrimSpace(*req.FromLocationID)
	toID := strings.TrimSpace(*req.ToLocationID)
	if !isValidUUID(fromID) || !isValidUUID(toID) || fromID == toID || *req.TravelMinutes < 1 || *req.CostUnits < 0 {
		writeError(w, http.StatusBadRequest, "invalid_connection", "invalid connection parameters")
