	cooled := false
	if req.Cooled != nil {
		cooled = *req.Cooled
	}
	cooledCap := 0
	if cooled {
		cooledCap = DefaultConnCapacity
	}

	connID := NewUUID()
	conn := &Connection{
		ConnectionID:   connID,
		FromLocationID: fromID,
		ToLocationID:   toID,
		TravelMinutes:  *req.TravelMinutes,
		CostUnits:      *req.CostUnits,
