func TestBatchingReplanningExceptionsAndPresealed(t *testing.T) {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	os.Setenv("ADMIN_USERNAME", "admin")
	os.Setenv("ADMIN_PASSWORD", "adminpass123")

	ctx := context.Background()
	if err := ResetDatabase(ctx, dbURL); err != nil {
		t.Fatalf("ResetDatabase: %v", err)
	}

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()

	srv := NewServer(store, "/workspace/frontend/dist", "/opt/arena/map-assets")

	// Login as admin
	_, loginResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "admin",
		"password": "adminpass123",
	})
	adminToken := loginResp["data"].(map[string]any)["sessionToken"].(string)

	// Create collection node & lab
	_, colResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Collection Node 1",
		"coordinate":      map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"active":          true,
		"functions":       []string{"collection_point", "transfer_point"},
	})
	colID := colResp["data"].(map[string]any)["locationId"].(string)

	_, labResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Main Lab",
		"coordinate":      map[string]any{"latitude": 12.9900, "longitude": 77.6100},
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"active":          true,
		"functions":       []string{"laboratory"},
	})
	labID := labResp["data"].(map[string]any)["locationId"].(string)

	_, _ = doReq(t, srv, http.MethodPost, "/api/create-connection", adminToken, map[string]any{
		"fromLocationId": colID,
		"toLocationId":   labID,
		"travelMinutes":  15,
		"costUnits":      5.0,
		"cooled":         true,
		"active":         true,
	})

	amberID := "00000000-0000-4000-8000-000000000001"
	indigoID := "00000000-0000-4000-8000-000000000002"
	frostID := "00000000-0000-4000-8000-000000000003"
	pulseID := "00000000-0000-4000-8000-000000000004"

	for _, stID := range []string{amberID, indigoID, frostID, pulseID} {
		_, _ = doReq(t, srv, http.MethodPost, "/api/configure-laboratory-acceptance", adminToken, map[string]any{
			"laboratoryId": labID,
			"sampleTypeId": stID,
			"accepts":      true,
		})
	}

	now := time.Now().UTC().Truncate(time.Second)
	tReq := now.Format(time.RFC3339)
	tEarliest := now.Add(5 * time.Minute).Format(time.RFC3339)
	tLatest := now.Add(60 * time.Minute).Format(time.RFC3339)
	tDeadline := now.Add(180 * time.Minute).Format(time.RFC3339)

	// 1. Create a Frost sample when NO qualified Frost collector exists -> should be flagged with no_qualified_worker exception
	code, frostReq := doReq(t, srv, http.MethodPost, "/api/create-collection-request", adminToken, map[string]any{
		"origin":               map[string]any{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"requestedAt":          tReq,
		"earliestCollectionAt": tEarliest,
		"latestCollectionAt":   tLatest,
		"deliveryDeadline":     tDeadline,
		"sampleTypeId":         frostID,
		"containerType":        "cryo_vial",
		"temperatureMinC":      -20.0,
		"temperatureMaxC":      8.0,
		"idempotencyKey":       "frost-no-worker",
	})
	if code != http.StatusCreated {
		t.Fatalf("create frost sample failed: %d %v", code, frostReq)
	}
	frostSampleID := frostReq["data"].(map[string]any)["sampleId"].(string)
	_, frostState := doReq(t, srv, http.MethodGet, "/api/read-sample-state/"+frostSampleID, adminToken, nil)
	stObj := frostState["data"].(map[string]any)
	if stObj["state"].(map[string]any)["status"] != "exception" {
		t.Fatalf("expected frost sample status=exception due to no qualified collector, got %v", stObj)
	}
	if stObj["exception"].(map[string]any)["code"] != "no_qualified_worker" {
		t.Fatalf("expected exception code=no_qualified_worker, got %v", stObj["exception"])
	}

	// 2. Create qualified collectors & courier & node_handler
	_, _ = doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, map[string]any{
		"username":        "col_all",
		"initialPassword": "password123",
		"roles":           []string{"collection_professional"},
		"qualifications":  []string{"Amber", "Indigo", "Frost", "Pulse"},
		"active":          true,
	})
	_, _ = doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, map[string]any{
		"username":        "courier_main",
		"initialPassword": "password123",
		"roles":           []string{"delivery_partner"},
		"active":          true,
	})
	_, _ = doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, map[string]any{
		"username":           "nh_col1",
		"initialPassword":    "password123",
		"roles":              []string{"node_handler"},
		"assignedLocationId": colID,
		"active":             true,
	})
	_, nhLogin := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "nh_col1",
		"password": "password123",
	})
	nhToken := nhLogin["data"].(map[string]any)["sessionToken"].(string)

	// 3. Pre-sealed sample registration from home must fail with 400 invalid_origin_type
	code, badPre := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "home",
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     amberID,
		"containerType":    "amber_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-bad",
	})
	if code != http.StatusBadRequest || badPre["code"] != "invalid_origin_type" {
		t.Fatalf("expected 400 invalid_origin_type for presealed home sample, got %d %v", code, badPre)
	}

	// Valid pre-sealed sample registration from node
	code, okPre := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "node",
		"originNodeId":     colID,
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     amberID,
		"containerType":    "amber_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-ok-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("ingest-presealed-sample failed: %d %v", code, okPre)
	}
	preSampleID := okPre["data"].(map[string]any)["sampleId"].(string)
	preJourneyID := okPre["data"].(map[string]any)["journeyId"].(string)
	if okPre["data"].(map[string]any)["collectionRequired"] != false {
		t.Fatalf("expected collectionRequired=false for presealed sample")
	}

	// 4. Record out-of-range temperature checkpoint by current holder (nhToken) -> marks sample as exception
	code, cpResp := doReq(t, srv, http.MethodPost, "/api/record-handling-checkpoint", nhToken, map[string]any{
		"sampleId":             preSampleID,
		"observedAt":           now.Add(2 * time.Minute).Format(time.RFC3339),
		"containerType":        "amber_vial",
		"observedTemperatureC": 35.0,
		"idempotencyKey":       "cp-hot-1",
	})
	if code != http.StatusCreated || cpResp["data"].(map[string]any)["withinRange"] != false || cpResp["data"].(map[string]any)["sampleStatus"] != "exception" {
		t.Fatalf("expected out-of-range checkpoint to mark sample exception, got %d %v", code, cpResp)
	}

	// 5. Create another Amber sample and an Indigo sample, test merge compatibility
	_, amb2Resp := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "node",
		"originNodeId":     colID,
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     amberID,
		"containerType":    "amber_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-ok-2",
	})
	amb2SampleID := amb2Resp["data"].(map[string]any)["sampleId"].(string)
	amb2JourneyID := amb2Resp["data"].(map[string]any)["journeyId"].(string)

	_, indResp := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "node",
		"originNodeId":     colID,
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
