package internal

import (
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"
)

func doReq(t *testing.T, srv *Server, method, path, token string, body any) (int, map[string]any) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		if err := json.NewEncoder(&buf).Encode(body); err != nil {
			t.Fatalf("encode body: %v", err)
		}
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	rec := httptest.NewRecorder()
	srv.ServeHTTP(rec, req)

	var out map[string]any
	if rec.Body.Len() > 0 {
		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
			t.Fatalf("unmarshal response (%d %s): %v; raw=%s", rec.Code, path, err, rec.Body.String())
		}
	}
	return rec.Code, out
}

func TestEndToEndSampleLifecycleAndContracts(t *testing.T) {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	os.Setenv("ADMIN_USERNAME", "admin")
	os.Setenv("ADMIN_PASSWORD", "adminpass123")

	ctx := context.Background()
	if err := ResetDatabase(ctx, dbURL); err != nil {
		t.Fatalf("ResetDatabase: %v", err)
	}

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()

	srv := NewServer(store, "/workspace/frontend/dist", "/opt/arena/map-assets")

	// 1. Check /ready
	code, readyResp := doReq(t, srv, http.MethodGet, "/ready", "", nil)
	if code != http.StatusOK || readyResp["status"] != "ready" {
		t.Fatalf("expected /ready 200 ready, got %d %v", code, readyResp)
	}

	// 2. Invalid login
	code, errResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "admin",
		"password": "wrong",
	})
	if code != http.StatusUnauthorized || errResp["code"] != "invalid_credentials" {
		t.Fatalf("expected 401 invalid_credentials, got %d %v", code, errResp)
	}

	// 3. Valid admin login
	code, loginResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "admin",
		"password": "adminpass123",
	})
	if code != http.StatusOK {
		t.Fatalf("expected 200 login, got %d %v", code, loginResp)
	}
	adminData := loginResp["data"].(map[string]any)
	adminToken := adminData["sessionToken"].(string)
	if adminData["activeRole"] != "administrator" {
		t.Fatalf("expected activeRole=administrator, got %v", adminData["activeRole"])
	}

	// 4. Create locations: collection centre -> hub -> laboratory
	code, colLocResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Central Collection Point",
		"coordinate":      map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"coverageKm":      5.0,
		"handlingMinutes": 10,
		"active":          true,
		"functions":       []string{"collection_point"},
	})
	if code != http.StatusCreated {
		t.Fatalf("create collection point failed: %d %v", code, colLocResp)
	}
	colLocID := colLocResp["data"].(map[string]any)["locationId"].(string)

	code, hubLocResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Midtown Hub",
		"coordinate":      map[string]any{"latitude": 12.9800, "longitude": 77.6000},
		"coverageKm":      5.0,
		"handlingMinutes": 10,
		"active":          true,
		"functions":       []string{"transfer_point", "hub"},
	})
	if code != http.StatusCreated {
		t.Fatalf("create hub failed: %d %v", code, hubLocResp)
	}
	hubLocID := hubLocResp["data"].(map[string]any)["locationId"].(string)

	code, labLocResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Diagnostic Lab Alpha",
		"coordinate":      map[string]any{"latitude": 12.9900, "longitude": 77.6100},
		"coverageKm":      5.0,
		"handlingMinutes": 10,
		"active":          true,
		"functions":       []string{"laboratory"},
	})
	if code != http.StatusCreated {
		t.Fatalf("create lab failed: %d %v", code, labLocResp)
	}
	labLocID := labLocResp["data"].(map[string]any)["locationId"].(string)

	// 5. Create connections: colLoc -> hubLoc -> labLoc
	code, conn1Resp := doReq(t, srv, http.MethodPost, "/api/create-connection", adminToken, map[string]any{
		"fromLocationId": colLocID,
		"toLocationId":   hubLocID,
		"travelMinutes":  20,
		"costUnits":      10.0,
		"cooled":         true,
		"active":         true,
	})
	if code != http.StatusCreated {
		t.Fatalf("create conn1 failed: %d %v", code, conn1Resp)
	}
	_ = conn1Resp

	code, conn2Resp := doReq(t, srv, http.MethodPost, "/api/create-connection", adminToken, map[string]any{
		"fromLocationId": hubLocID,
		"toLocationId":   labLocID,
		"travelMinutes":  25,
		"costUnits":      12.0,
		"cooled":         true,
		"active":         true,
	})
	if code != http.StatusCreated {
		t.Fatalf("create conn2 failed: %d %v", code, conn2Resp)
	}
	_ = conn2Resp

	// 6. Configure laboratory acceptance for Amber (00000000-0000-4000-8000-000000000001)
	amberTypeID := "00000000-0000-4000-8000-000000000001"
	code, accResp := doReq(t, srv, http.MethodPost, "/api/configure-laboratory-acceptance", adminToken, map[string]any{
		"laboratoryId": labLocID,
		"sampleTypeId": amberTypeID,
		"accepts":      true,
	})
	if code != http.StatusOK {
		t.Fatalf("configure lab acceptance failed: %d %v", code, accResp)
	}

	// 7. Create users: requester, collector, courier1, courier2, node_handler, lab_operator, multi_role_user
	createUser := func(uname string, roles []string, quals []string, certs []map[string]any, locID string) (string, string) {
		payload := map[string]any{
			"username":        uname,
			"initialPassword": "password123",
			"roles":           roles,
			"qualifications":  quals,
			"certifications":  certs,
			"active":          true,
		}
		if locID != "" {
			payload["assignedLocationId"] = locID
		}
		c, r := doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, payload)
		if c != http.StatusCreated {
			t.Fatalf("createUser %s failed: %d %v", uname, c, r)
		}
		uid := r["data"].(map[string]any)["userId"].(string)

		c, lResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
			"username": uname,
			"password": "password123",
		})
		if c != http.StatusOK {
			t.Fatalf("login %s failed: %d %v", uname, c, lResp)
		}
		tok := lResp["data"].(map[string]any)["sessionToken"].(string)
		return uid, tok
	}

	_, reqToken := createUser("requester1", []string{"requester"}, nil, nil, "")
	colUID, colToken := createUser("collector1", []string{"collection_professional"}, []string{"Amber"}, []map[string]any{
		{"code": "Amber", "active": true, "expiresAt": "2030-01-01T00:00:00Z"},
	}, "")
	cour1UID, cour1Token := createUser("courier1", []string{"delivery_partner"}, nil, nil, "")
	_, nodeToken := createUser("nodehandler1", []string{"node_handler"}, nil, nil, hubLocID)
	labOpUID, labOpToken := createUser("labop1", []string{"laboratory_team"}, nil, nil, labLocID)
	_, multiToken := createUser("multirole1", []string{"dispatcher", "requester"}, nil, nil, "")

	// 8. Multi-role user must select active role before calling protected endpoints
	code, roleErr := doReq(t, srv, http.MethodPost, "/api/list-role-work", multiToken, map[string]any{})
	if code != http.StatusConflict || roleErr["code"] != "role_not_selected" {
		t.Fatalf("expected 409 role_not_selected for multirole user, got %d %v", code, roleErr)
	}
	code, selResp := doReq(t, srv, http.MethodPost, "/api/select-active-role", multiToken, map[string]any{"role": "dispatcher"})
	if code != http.StatusOK {
		t.Fatalf("select-active-role failed: %d %v", code, selResp)
	}

	// 9. Requester performs dry-run serviceability check
	now := time.Now().UTC().Truncate(time.Second)
	tReq := now.Format(time.RFC3339)
	tEarliest := now.Add(5 * time.Minute).Format(time.RFC3339)
	tLatest := now.Add(60 * time.Minute).Format(time.RFC3339)
	tDeadline := now.Add(240 * time.Minute).Format(time.RFC3339)

	code, srvResp := doReq(t, srv, http.MethodPost, "/api/check-serviceability", reqToken, map[string]any{
		"origin":               map[string]any{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"sampleTypeId":         amberTypeID,
		"requestedAt":          tReq,
		"earliestCollectionAt": tEarliest,
		"latestCollectionAt":   tLatest,
		"deliveryDeadline":     tDeadline,
	})
	if code != http.StatusOK || srvResp["data"].(map[string]any)["serviceable"] != true {
		t.Fatalf("expected serviceable=true, got %d %v", code, srvResp)
	}
	// Verify dry run created 0 samples
	if len(store.state.Samples) != 0 {
		t.Fatalf("dry run check-serviceability created samples: %d", len(store.state.Samples))
	}

	// 10. Create collection request
	code, createReqResp := doReq(t, srv, http.MethodPost, "/api/create-collection-request", reqToken, map[string]any{
		"origin":               map[string]any{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"requestedAt":          tReq,
		"earliestCollectionAt": tEarliest,
		"latestCollectionAt":   tLatest,
		"deliveryDeadline":     tDeadline,
		"sampleTypeId":         amberTypeID,
		"containerType":        "amber_vial",
		"temperatureMinC":      2.0,
		"temperatureMaxC":      8.0,
		"idempotencyKey":       "req-key-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("create-collection-request failed: %d %v", code, createReqResp)
	}
	reqCreatedData := createReqResp["data"].(map[string]any)
	sampleID := reqCreatedData["sampleId"].(string)
	journeyID := reqCreatedData["journeyId"].(string)

	// 11. Read journey plan as dispatcher
	code, jpResp := doReq(t, srv, http.MethodPost, "/api/read-journey-plan", multiToken, map[string]any{
		"journeyId": journeyID,
	})
	if code != http.StatusOK {
		t.Fatalf("read-journey-plan failed: %d %v", code, jpResp)
	}
	jpData := jpResp["data"].(map[string]any)
	colAssignID := jpData["collectionAssignmentId"].(string)
	firstTransID := jpData["firstTransportAssignmentId"].(string)
	finalTransID := jpData["finalTransportAssignmentId"].(string)
	nodeAssignIDs := jpData["nodeAssignmentIds"].([]any)
	nodeAssignID := nodeAssignIDs[0].(string)
	labAssignIDs := jpData["laboratoryAssignmentIds"].([]any)
	labAssignID := labAssignIDs[0].(string)

	// 12. Accept assignments
	for _, item := range []struct {
		tok string
		aid string
	}{
		{colToken, colAssignID},
		{cour1Token, firstTransID},
		{cour1Token, finalTransID},
		{nodeToken, nodeAssignID},
		{labOpToken, labAssignID},
	} {
		c, r := doReq(t, srv, http.MethodPost, "/api/accept-assignment", item.tok, map[string]any{
			"assignmentId":   item.aid,
			"idempotencyKey": "acc-" + item.aid,
		})
		if c != http.StatusCreated {
			t.Fatalf("accept-assignment %s failed: %d %v", item.aid, c, r)
		}
	}

	// 13. Collect and seal sample
	tCollect := now.Add(10 * time.Minute).Format(time.RFC3339)
	code, sealResp := doReq(t, srv, http.MethodPost, "/api/collect-and-seal-sample", colToken, map[string]any{
		"sampleId":             sampleID,
		"assignmentId":         colAssignID,
		"collectedAt":          tCollect,
		"containerType":        "amber_vial",
		"observedTemperatureC": 4.5,
		"idempotencyKey":       "seal-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("collect-and-seal-sample failed: %d %v", code, sealResp)
	}
	if sealResp["data"].(map[string]any)["currentHolderId"] != colUID {
		t.Fatalf("expected currentHolderId=%s", colUID)
	}

	// 14. Handoff from collector -> courier1 (leg 1)
	tHo1 := now.Add(15 * time.Minute).Format(time.RFC3339)
	code, ho1Resp := doReq(t, srv, http.MethodPost, "/api/initiate-handoff", colToken, map[string]any{
		"sampleId":         sampleID,
		"fromAssignmentId": colAssignID,
		"toAssignmentId":   firstTransID,
		"receiverId":       cour1UID,
		"initiatedAt":      tHo1,
		"idempotencyKey":   "ho1-init",
	})
	if code != http.StatusCreated {
		t.Fatalf("initiate-handoff 1 failed: %d %v", code, ho1Resp)
	}
	ho1ID := ho1Resp["data"].(map[string]any)["handoffId"].(string)

	// Confirm sender side -> sender still holder
	code, ho1Sender := doReq(t, srv, http.MethodPost, "/api/confirm-handoff", colToken, map[string]any{
		"handoffId":        ho1ID,
		"confirmationSide": "sender",
		"confirmedAt":      now.Add(16 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":   "ho1-sender",
	})
	if code != http.StatusCreated || ho1Sender["data"].(map[string]any)["currentHolderId"] != colUID {
		t.Fatalf("expected sender still holder until receiver confirms, got %d %v", code, ho1Sender)
	}

	// Confirm receiver side -> receiver becomes holder
	code, ho1Recv := doReq(t, srv, http.MethodPost, "/api/confirm-handoff", cour1Token, map[string]any{
		"handoffId":        ho1ID,
		"confirmationSide": "receiver",
		"confirmedAt":      now.Add(17 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":   "ho1-recv",
	})
	if code != http.StatusCreated || ho1Recv["data"].(map[string]any)["currentHolderId"] != cour1UID {
		t.Fatalf("expected courier1 to become holder, got %d %v", code, ho1Recv)
	}

	// 15. Courier1 progresses leg 1 & leg 2 and hands off to lab operator
	for _, legID := range []string{firstTransID, finalTransID} {
		for idx, st := range []string{"in_transit", "delivered"} {
			c, r := doReq(t, srv, http.MethodPost, "/api/update-assignment-progress", cour1Token, map[string]any{
				"assignmentId":   legID,
				"status":         st,
				"occurredAt":     now.Add(time.Duration(20+idx*5) * time.Minute).Format(time.RFC3339),
				"idempotencyKey": "prog-" + legID + "-" + st,
			})
			if c != http.StatusCreated {
				t.Fatalf("update-assignment-progress %s %s failed: %d %v", legID, st, c, r)
			}
		}
	}

	// Handoff from courier1 (final leg) -> lab operator
	code, ho2Resp := doReq(t, srv, http.MethodPost, "/api/initiate-handoff", cour1Token, map[string]any{
		"sampleId":         sampleID,
		"fromAssignmentId": finalTransID,
		"toAssignmentId":   labAssignID,
		"receiverId":       labOpUID,
		"initiatedAt":      now.Add(40 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":   "ho2-init",
	})
	if code != http.StatusCreated {
		t.Fatalf("initiate-handoff 2 failed: %d %v", code, ho2Resp)
	}
	ho2ID := ho2Resp["data"].(map[string]any)["handoffId"].(string)

	_, _ = doReq(t, srv, http.MethodPost, "/api/confirm-handoff", cour1Token, map[string]any{
		"handoffId":        ho2ID,
		"confirmationSide": "sender",
		"confirmedAt":      now.Add(41 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":   "ho2-sender",
	})
	_, _ = doReq(t, srv, http.MethodPost, "/api/confirm-handoff", labOpToken, map[string]any{
		"handoffId":        ho2ID,
		"confirmationSide": "receiver",
		"confirmedAt":      now.Add(42 * time.Minute).Format(time.RFC3339),
		"idempotencyKey":   "ho2-recv",
	})

	// 16. Lab operator confirms laboratory receipt
	code, recResp := doReq(t, srv, http.MethodPost, "/api/confirm-laboratory-receipt", labOpToken, map[string]any{
		"sampleId":       sampleID,
		"laboratoryId":   labLocID,
		"receivedAt":     now.Add(45 * time.Minute).Format(time.RFC3339),
		"idempotencyKey": "lab-rec-1",
	})
	if code != http.StatusCreated || recResp["data"].(map[string]any)["status"] != "received" {
		t.Fatalf("confirm-laboratory-receipt failed: %d %v", code, recResp)
	}

	// 17. Search audit trail
	code, audResp := doReq(t, srv, http.MethodPost, "/api/search-audit-trail", multiToken, map[string]any{
		"entityId": sampleID,
	})
	if code != http.StatusOK {
		t.Fatalf("search-audit-trail failed: %d %v", code, audResp)
	}
	entries := audResp["data"].(map[string]any)["entries"].([]any)
	if len(entries) < 3 {
		t.Fatalf("expected >= 3 audit entries for sample, got %d", len(entries))
	}
}

func TestBatchingReplanningExceptionsAndPresealed(t *testing.T) {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	os.Setenv("ADMIN_USERNAME", "admin")
	os.Setenv("ADMIN_PASSWORD", "adminpass123")

	ctx := context.Background()
	if err := ResetDatabase(ctx, dbURL); err != nil {
		t.Fatalf("ResetDatabase: %v", err)
	}

	store, err := NewStore(ctx, dbURL)
	if err != nil {
		t.Fatalf("NewStore: %v", err)
	}
	defer store.Close()

	srv := NewServer(store, "/workspace/frontend/dist", "/opt/arena/map-assets")

	// Login as admin
	_, loginResp := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "admin",
		"password": "adminpass123",
	})
	adminToken := loginResp["data"].(map[string]any)["sessionToken"].(string)

	// Create collection node & lab
	_, colResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Collection Node 1",
		"coordinate":      map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"active":          true,
		"functions":       []string{"collection_point", "transfer_point"},
	})
	colID := colResp["data"].(map[string]any)["locationId"].(string)

	_, labResp := doReq(t, srv, http.MethodPost, "/api/create-location", adminToken, map[string]any{
		"name":            "Main Lab",
		"coordinate":      map[string]any{"latitude": 12.9900, "longitude": 77.6100},
		"coverageKm":      5.0,
		"handlingMinutes": 5,
		"active":          true,
		"functions":       []string{"laboratory"},
	})
	labID := labResp["data"].(map[string]any)["locationId"].(string)

	_, _ = doReq(t, srv, http.MethodPost, "/api/create-connection", adminToken, map[string]any{
		"fromLocationId": colID,
		"toLocationId":   labID,
		"travelMinutes":  15,
		"costUnits":      5.0,
		"cooled":         true,
		"active":         true,
	})

	amberID := "00000000-0000-4000-8000-000000000001"
	indigoID := "00000000-0000-4000-8000-000000000002"
	frostID := "00000000-0000-4000-8000-000000000003"
	pulseID := "00000000-0000-4000-8000-000000000004"

	for _, stID := range []string{amberID, indigoID, frostID, pulseID} {
		_, _ = doReq(t, srv, http.MethodPost, "/api/configure-laboratory-acceptance", adminToken, map[string]any{
			"laboratoryId": labID,
			"sampleTypeId": stID,
			"accepts":      true,
		})
	}

	now := time.Now().UTC().Truncate(time.Second)
	tReq := now.Format(time.RFC3339)
	tEarliest := now.Add(5 * time.Minute).Format(time.RFC3339)
	tLatest := now.Add(60 * time.Minute).Format(time.RFC3339)
	tDeadline := now.Add(180 * time.Minute).Format(time.RFC3339)

	// 1. Create a Frost sample when NO qualified Frost collector exists -> should be flagged with no_qualified_worker exception
	code, frostReq := doReq(t, srv, http.MethodPost, "/api/create-collection-request", adminToken, map[string]any{
		"origin":               map[string]any{"latitude": 12.9720, "longitude": 77.5950},
		"originType":           "home",
		"requestedAt":          tReq,
		"earliestCollectionAt": tEarliest,
		"latestCollectionAt":   tLatest,
		"deliveryDeadline":     tDeadline,
		"sampleTypeId":         frostID,
		"containerType":        "cryo_vial",
		"temperatureMinC":      -20.0,
		"temperatureMaxC":      8.0,
		"idempotencyKey":       "frost-no-worker",
	})
	if code != http.StatusCreated {
		t.Fatalf("create frost sample failed: %d %v", code, frostReq)
	}
	frostSampleID := frostReq["data"].(map[string]any)["sampleId"].(string)
	_, frostState := doReq(t, srv, http.MethodGet, "/api/read-sample-state/"+frostSampleID, adminToken, nil)
	stObj := frostState["data"].(map[string]any)
	if stObj["state"].(map[string]any)["status"] != "exception" {
		t.Fatalf("expected frost sample status=exception due to no qualified collector, got %v", stObj)
	}
	_, frostLC := doReq(t, srv, http.MethodPost, "/api/read-sample-lifecycle", adminToken, map[string]any{"sampleId": frostSampleID})
	lcObj := frostLC["data"].(map[string]any)
	if lcObj["exception"].(map[string]any)["code"] != "no_qualified_worker" {
		t.Fatalf("expected exception code=no_qualified_worker, got %v", lcObj["exception"])
	}

	// 2. Create qualified collectors & courier & node_handler
	_, _ = doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, map[string]any{
		"username":        "col_all",
		"initialPassword": "password123",
		"roles":           []string{"collection_professional"},
		"qualifications":  []string{"Amber", "Indigo", "Frost", "Pulse"},
		"active":          true,
	})
	_, _ = doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, map[string]any{
		"username":        "courier_main",
		"initialPassword": "password123",
		"roles":           []string{"delivery_partner"},
		"active":          true,
	})
	_, _ = doReq(t, srv, http.MethodPost, "/api/create-user", adminToken, map[string]any{
		"username":           "nh_col1",
		"initialPassword":    "password123",
		"roles":              []string{"node_handler"},
		"assignedLocationId": colID,
		"active":             true,
	})
	_, nhLogin := doReq(t, srv, http.MethodPost, "/api/authenticate-user", "", map[string]any{
		"username": "nh_col1",
		"password": "password123",
	})
	nhToken := nhLogin["data"].(map[string]any)["sessionToken"].(string)

	// 3. Pre-sealed sample registration from home must fail with 400 invalid_origin_type
	code, badPre := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "home",
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     amberID,
		"containerType":    "amber_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-bad",
	})
	if code != http.StatusBadRequest || badPre["code"] != "invalid_origin_type" {
		t.Fatalf("expected 400 invalid_origin_type for presealed home sample, got %d %v", code, badPre)
	}

	// Valid pre-sealed sample registration from node
	code, okPre := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "node",
		"originNodeId":     colID,
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     amberID,
		"containerType":    "amber_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-ok-1",
	})
	if code != http.StatusCreated {
		t.Fatalf("ingest-presealed-sample failed: %d %v", code, okPre)
	}
	preSampleID := okPre["data"].(map[string]any)["sampleId"].(string)
	preJourneyID := okPre["data"].(map[string]any)["journeyId"].(string)
	if okPre["data"].(map[string]any)["alreadySealed"] != true {
		t.Fatalf("expected alreadySealed=true for presealed sample")
	}

	// 4. Record out-of-range temperature checkpoint by current holder (nhToken) -> marks sample as exception
	code, cpResp := doReq(t, srv, http.MethodPost, "/api/record-handling-checkpoint", nhToken, map[string]any{
		"sampleId":             preSampleID,
		"observedAt":           now.Add(2 * time.Minute).Format(time.RFC3339),
		"containerType":        "amber_vial",
		"observedTemperatureC": 35.0,
		"idempotencyKey":       "cp-hot-1",
	})
	if code != http.StatusCreated || cpResp["data"].(map[string]any)["withinRange"] != false || cpResp["data"].(map[string]any)["sampleStatus"] != "exception" {
		t.Fatalf("expected out-of-range checkpoint to mark sample exception, got %d %v", code, cpResp)
	}

	// 5. Create another Amber sample and an Indigo sample, test merge compatibility
	_, amb2Resp := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "node",
		"originNodeId":     colID,
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     amberID,
		"containerType":    "amber_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-ok-2",
	})
	amb2SampleID := amb2Resp["data"].(map[string]any)["sampleId"].(string)
	amb2JourneyID := amb2Resp["data"].(map[string]any)["journeyId"].(string)

	_, indResp := doReq(t, srv, http.MethodPost, "/api/ingest-presealed-sample", nhToken, map[string]any{
		"origin":           map[string]any{"latitude": 12.9716, "longitude": 77.5946},
		"originType":       "node",
		"originNodeId":     colID,
		"requestedAt":      tReq,
		"deliveryDeadline": tDeadline,
		"sampleTypeId":     indigoID,
		"containerType":    "indigo_vial",
		"temperatureMinC":  2.0,
		"temperatureMaxC":  25.0,
		"idempotencyKey":   "pre-indigo-1",
	})
	indSampleID := indResp["data"].(map[string]any)["sampleId"].(string)

	// Merging Amber + Indigo must fail with 409 incompatible_batch
	code, badMerge := doReq(t, srv, http.MethodPost, "/api/split-or-merge-journey", adminToken, map[string]any{
		"action":              "merge",
		"journeyId":           amb2JourneyID,
		"expectedPlanVersion": 1,
		"sampleIds":           []string{amb2SampleID, indSampleID},
		"idempotencyKey":      "merge-bad-indigo",
	})
	if code != http.StatusConflict || badMerge["code"] != "incompatible_batch" {
		t.Fatalf("expected 409 incompatible_batch for Amber+Indigo, got %d %v", code, badMerge)
	}

	// Merging two Amber samples succeeds
	code, okMerge := doReq(t, srv, http.MethodPost, "/api/split-or-merge-journey", adminToken, map[string]any{
		"action":              "merge",
		"journeyId":           preJourneyID,
		"expectedPlanVersion": 1,
		"sampleIds":           []string{preSampleID, amb2SampleID},
		"idempotencyKey":      "merge-ok-amber",
	})
	if code != http.StatusCreated {
		t.Fatalf("expected 201 for merging two Amber samples, got %d %v", code, okMerge)
	}
}

