SRV_PID=$!
for i in $(seq 1 30); do
  if curl -sf http://127.0.0.1:8080/ready >/dev/null; then break; fi
  sleep 0.2
done
node /tmp/verify_ui.mjs
TEST_EXIT=$?
kill $SRV_PID 2>/dev/null || true
wait $SRV_PID 2>/dev/null || true
rm -f /tmp/verify_ui.mjs /tmp/server.log
exit $TEST_EXIT

