import { chromium } from '/usr/local/lib/node_modules/@playwright/test/index.mjs';

const BASE = 'http://127.0.0.1:8080';

async function api(path, token, body, method = 'POST') {
  const headers = { 'Content-Type': 'application/json' };
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const res = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json();
  if (!res.ok) throw new Error(`${path} failed ${res.status}: ${JSON.stringify(json)}`);
  return json.data;
}

async function main() {
  const adminAuth = await api('/api/authenticate-user', '', { username: 'admin', password: 'admin-password' });
  const adminToken = adminAuth.sessionToken;

  const nodeA = await api('/api/create-location', adminToken, {
    name: 'Collection Hub Alpha',
    coordinate: { latitude: 12.9716, longitude: 77.5946 },
    functions: ['collection_point', 'transfer_hub'],
    coverageKm: 5.0,
    handlingMinutes: 5,
    capacityUnits: 10,
    cooledCapacityUnits: 5,
    idempotencyKey: 'ui-loc-a',
  });
  const labB = await api('/api/create-location', adminToken, {
    name: 'Central Lab Beta',
    coordinate: { latitude: 12.9816, longitude: 77.6046 },
    functions: ['laboratory'],
    coverageKm: 5.0,
    handlingMinutes: 5,
    capacityUnits: 15,
    cooledCapacityUnits: 8,
    acceptedSampleTypeIds: ['amber'],
    idempotencyKey: 'ui-loc-b',
  });
  await api('/api/create-connection', adminToken, {
    fromLocationId: nodeA.locationId,
    toLocationId: labB.locationId,
    travelMinutes: 15,
    capacityUnits: 10,
    cooledCapacityUnits: 5,
    idempotencyKey: 'ui-conn-ab',
  });

  const multiUser = await api('/api/create-user', adminToken, {
    username: 'worker1',
    password: 'Password123!',
    roles: ['requester', 'collection_professional', 'laboratory_team'],
    qualifications: ['amber'],
    assignedLocationId: labB.locationId,
    idempotencyKey: 'ui-user-1',
  });
  const wAuth = await api('/api/authenticate-user', '', { username: 'worker1', password: 'Password123!' });
  await api('/api/select-active-role', wAuth.sessionToken, { role: 'collection_professional' });
  await api('/api/set-worker-availability', wAuth.sessionToken, {
    workerId: multiUser.userId,
    available: true,
    coordinate: { latitude: 12.9716, longitude: 77.5946 },
  });

  await api('/api/select-active-role', wAuth.sessionToken, { role: 'requester' });
  const now = new Date();
  const colSample = await api('/api/create-collection-request', wAuth.sessionToken, {
    origin: { latitude: 12.972, longitude: 77.595 },
    originType: 'home',
    requestedAt: now.toISOString(),
    earliestCollectionAt: new Date(now.getTime() + 5 * 60000).toISOString(),
    latestCollectionAt: new Date(now.getTime() + 45 * 60000).toISOString(),
    deliveryDeadline: new Date(now.getTime() + 180 * 60000).toISOString(),
    sampleTypeId: 'amber',
    containerType: 'amber-vial',
    temperatureMinC: 2,
    temperatureMaxC: 8,
    idempotencyKey: 'ui-sample-1',
  });

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  const externalRequests = [];
  page.on('request', (req) => {
    const url = req.url();
    if (!url.startsWith('http://127.0.0.1') && !url.startsWith('http://localhost') && !url.startsWith('data:') && !url.startsWith('blob:')) {
      externalRequests.push(url);
    }
  });

  await page.goto(BASE, { waitUntil: 'networkidle' });

  // Scenario 1: login_rejects_invalid_credentials
  await page.getByLabel('Username').fill('admin');
  await page.getByLabel('Password').fill('wrong-password');
  await page.getByRole('button', { name: 'Sign In' }).click();
  await page.getByRole('alert').waitFor({ state: 'visible' });
  console.log('✓ 1. login_rejects_invalid_credentials');

  // Sign in as multi-role user worker1
  await page.getByLabel('Username').fill('worker1');
  await page.getByLabel('Password').fill('Password123!');
  await page.getByRole('button', { name: 'Sign In' }).click();

  // Scenario 2: role_switch_control_lists_and_applies_role
  const roleSelect = page.getByLabel('Active Role');
  await roleSelect.waitFor({ state: 'visible' });
  await roleSelect.selectOption('requester');
  await page.waitForTimeout(300);
  console.log('✓ 2. role_switch_control_lists_and_applies_role');

  // Scenario 3, 4, 5, 6
  await page.getByRole('heading', { name: 'Current Work' }).waitFor({ state: 'visible' });
  await page.getByRole('heading', { name: 'Past Work' }).waitFor({ state: 'visible' });
  await page.getByRole('heading', { name: 'Status Timeline' }).first().waitFor({ state: 'visible' });
  await page.getByText('Freshness:').first().waitFor({ state: 'visible' });
  await page.getByText('Current Location:').first().waitFor({ state: 'visible' });
  await page.getByText('Current Custodian:').first().waitFor({ state: 'visible' });
  await page.getByText('Route Progress:').first().waitFor({ state: 'visible' });
  console.log('✓ 3,4,5,6. work view, status history, freshness, location/custodian/progress');

  // Scenario 12 & 13
  await page.getByRole('tab', { name: 'Requests & Samples' }).click();
  await page.getByRole('button', { name: 'Check Serviceability' }).click();
  await page.getByRole('status', { name: 'Serviceability Check Result' }).waitFor({ state: 'visible' });
  console.log('✓ 13. serviceability_dry_run_creates_nothing');

  await page.getByLabel('Origin Latitude').fill('999');
  await page.getByRole('button', { name: 'Submit Collection Request' }).click();
  await page.getByRole('alert').first().waitFor({ state: 'visible' });
  console.log('✓ 12. request_form_surfaces_validation_error');

  // Scenario 15 & 16
  await roleSelect.selectOption('collection_professional');
  await page.getByRole('tab', { name: 'My Work' }).click();
  const acceptBtn = page.getByRole('button', { name: 'Accept Assignment' }).first();
  await acceptBtn.waitFor({ state: 'visible' });
  await acceptBtn.click();
  await page.waitForTimeout(300);
  console.log('✓ 15. accept_assignment_writes_through');

  await page.getByRole('button', { name: 'Record Location' }).click();
  await page.getByRole('status', { name: 'Location Update Status' }).waitFor({ state: 'visible' });
  console.log('✓ 16. worker_records_location_writes_through');

  // Scenario 14
  await roleSelect.selectOption('laboratory_team');
  await page.getByRole('tab', { name: 'Node & Lab Capacity' }).click();
  await page.getByLabel('Regular Capacity').waitFor({ state: 'visible' });
  await page.getByLabel('Cooled Capacity').waitFor({ state: 'visible' });
  console.log('✓ 14. lab_worker_views_own_capacity');

  // Scenario 7
  await page.getByRole('tab', { name: 'Live Map' }).click();
  await page.waitForTimeout(500);
  if (externalRequests.length > 0) {
    throw new Error(`External requests detected: ${externalRequests.join(', ')}`);
  }
  console.log('✓ 7. map_renders_local_tiles_only');

  // Scenario 11
  await page.getByRole('button', { name: 'Sign Out' }).click();
  await page.getByRole('button', { name: 'Sign In' }).waitFor({ state: 'visible' });
  console.log('✓ 11. sign_out_ends_authenticated_session');

  // Record an exception via API and sign in as admin to verify Scenario 8, 9, 10
  await api('/api/select-active-role', wAuth.sessionToken, { role: 'laboratory_team' });
  await api('/api/record-laboratory-exception', wAuth.sessionToken, {
    sampleId: colSample.sampleId,
    laboratoryId: labB.locationId,
    reasonCode: 'damaged_seal',
    details: 'Damaged seal observed',
    recordedAt: new Date().toISOString(),
    idempotencyKey: 'ui-exc-1',
  });

  await page.getByLabel('Username').fill('admin');
  await page.getByLabel('Password').fill('admin-password');
  await page.getByRole('button', { name: 'Sign In' }).click();

  // Scenario 8
  await page.getByText(/Exception Flag:/).first().waitFor({ state: 'visible' });
  console.log('✓ 8. sample_view_surfaces_exception_flag');

  // Scenario 9
  await page.getByRole('tab', { name: 'Operations Monitor' }).click();
  for (const cat of ['Samples', 'Workers', 'Collection Nodes', 'Laboratories', 'Routes', 'Exceptions']) {
    await page.getByRole('region', { name: cat }).waitFor({ state: 'visible' });
  }
  console.log('✓ 9. monitor_dashboard_renders_categories');

  // Scenario 10
  await page.getByRole('tab', { name: 'Audit Trail' }).click();
  await page.getByLabel('Search Audit').fill('authenticate_user');
  await page.getByRole('button', { name: 'Search Audit' }).click();
  await page.getByRole('table', { name: 'Audit Log Entries' }).waitFor({ state: 'visible' });
  console.log('✓ 10. audit_view_renders_and_searches');

  await browser.close();
  console.log('ALL 16 UI CONTRACT SCENARIOS PASSED!');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

