  1510	func (srv *Server) validateHandoffAdjacencyLocked(jp *JourneyPlan, fromA, toA *Assignment) (string, bool) {
  1511		if fromA.SampleID != toA.SampleID || fromA.JourneyID != toA.JourneyID {
  1512			return "invalid_handoff_route", false
  1513		}
  1514		switch fromA.Kind {
  1515		case "collection":
  1516			if toA.Kind == "node" && toA.NodeID == fromA.ToLocationID {
  1517				return "", true
  1518			}
  1519			if toA.Kind == "transport" && toA.Sequence == 1 {
  1520				return "", true
  1521			}
  1522			return "nonadjacent_handoff", false
  1523		case "node":
  1524			if toA.Kind == "transport" {
  1525				if toA.FromLocationID == fromA.NodeID {
  1526					return "", true
  1527				}
  1528				return "node_assignment_mismatch", false
  1529			}
  1530			if toA.Kind == "laboratory" && toA.LaboratoryID == fromA.NodeID {
  1531				return "", true
  1532			}
  1533			return "nonadjacent_handoff", false
  1534		case "transport":
  1535			if toA.Kind == "node" {
  1536				if toA.NodeID == fromA.ToLocationID {
  1537					return "", true
  1538				}
  1539				return "node_assignment_mismatch", false
  1540			}
  1541			if toA.Kind == "transport" {
  1542				if toA.Sequence == fromA.Sequence+1 && toA.FromLocationID == fromA.ToLocationID {
  1543					return "", true
  1544				}
  1545				return "nonadjacent_handoff", false
  1546			}
  1547			if toA.Kind == "laboratory" {
  1548				if jp != nil && fromA.Sequence == len(jp.Legs) && toA.LaboratoryID == fromA.ToLocationID {
  1549					return "", true
  1550				}
  1551				return "nonadjacent_handoff", false
  1552			}
  1553		}
  1554		return "invalid_handoff_route", false
  1555	}
