  await roleSelect.selectOption('requester');
  await page.waitForTimeout(300);
  console.log('✓ 2. role_switch_control_lists_and_applies_role');

  // Scenario 3, 4, 5, 6
  await page.getByRole('region', { name: 'Current Work' }).waitFor({ state: 'visible' });
  await page.getByRole('region', { name: 'Past Work' }).waitFor({ state: 'visible' });
  await page.getByRole('list', { name: 'Ordered Status History' }).first().waitFor({ state: 'visible' });
  await page.getByText('Location Freshness:').first().waitFor({ state: 'visible' });
