    setCapMsg('');
    if (!assignedLocation?.locationId) return;
    const res = await apiFetch('/api/configure-capacity', {
      method: 'POST',
      body: JSON.stringify({
        resourceId: assignedLocation.locationId,
        capacityUnits: Number(regCapInput),
        cooledCapacityUnits: Number(cooledCapInput)
      })
    });
    if (!res.ok) {
      setCapMsg(`Error: ${res.body?.error} (${res.body?.code})`);
      return;
    }
    setCapMsg('Capacity updated');
    await refreshAll();
  };

  const handleSearchAudit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const payload: Record<string, any> = { limit: 100 };
    if (auditQuery.trim()) payload.query = auditQuery.trim();
    if (auditActionFilter.trim()) payload.action = auditActionFilter.trim();
    if (auditEntityFilter.trim()) payload.entityId = auditEntityFilter.trim();

    const res = await apiFetch('/api/search-audit-trail', {
      method: 'POST',
      body: JSON.stringify(payload)
