                  )}
                  {smp && (
                    <div style={{ marginTop: '8px', fontSize: '12px', borderTop: '1px dashed #cbd5e1', paddingTop: '6px' }}>
                      <div>
                        Custodian: <strong>{smp.currentHolderId || 'Unassigned'}</strong> | Freshness:{' '}
                        <strong>{smp.locationStale ? 'Stale' : 'Fresh'}</strong>
                      </div>
                    </div>
                  )}
                </article>
              );
            })
          )}
        </section>

        <section
          aria-label="Past Work"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Past &amp; Completed Work ({pastWorkItems.length})</h2>
          {pastWorkItems.length === 0 ? (
            <p style={{ color: '#64748b' }}>No completed work items.</p>
          ) : (
            pastWorkItems.map((item: any, idx: number) => {
              const id = item.assignmentId || item.sampleId || item.journeyId || `past-${idx}`;
              return (
                <article
                  key={id}
                  aria-label={`Completed Work Item ${id}`}
                  style={{
                    border: '1px solid #e2e8f0',
                    borderRadius: '6px',
                    padding: '12px',
                    marginBottom: '10px',
                    background: '#f8fafc'
                  }}
                >
                  <div>
                    <strong>{item.kind || 'work'}:</strong> <code>{id}</code> — Status:{' '}
                    <strong>{item.status}</strong>
                  </div>
                  {Array.isArray(item.history) && item.history.length > 0 && (
                    <div style={{ marginTop: '8px' }}>
                      <strong style={{ fontSize: '12px' }}>Status History:</strong>
                      <ol aria-label="Completed Status History" style={{ margin: '4px 0 0', paddingLeft: '20px', fontSize: '12px' }}>
                        {item.history.map((h: any, hIdx: number) => (
                          <li key={h.eventId || hIdx}>
                            {h.action} — {h.occurredAt} ({h.role})
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </article>
              );
            })
          )}
        </section>
      </div>

      {/* Detailed Sample Views (Status History, Custodian, Location, Route Progress, Freshness, Exceptions) */}
      {allSamplesList.length > 0 && (
        <section
          aria-label="Sample Tracking Details"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Sample Tracking, Custody &amp; Status Timeline</h2>
          {allSamplesList.map((smp: any) => {
            const loc = smp.latestLocation || smp.origin;
            const legs = smp.journey?.legs || [];
            const completedCount = (smp.completedLegIds || []).length;
            const hasException =
              smp.status === 'exception' || smp.status === 'expired' || Boolean(smp.exception);
            return (
              <article
                key={smp.sampleId}
                aria-label={`Sample ${smp.sampleId}`}
                style={{
                  border: '1px solid #cbd5e1',
                  borderRadius: '6px',
                  padding: '14px',
                  marginBottom: '12px',
                  background: hasException ? '#fff1f2' : '#f8fafc'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px' }}>
                  <div>
                    <strong>Sample ID:</strong> <code>{smp.sampleId}</code> | <strong>Status:</strong>{' '}
                    <span>{smp.status}</span>
                  </div>
                  <div>
                    <strong>Location Freshness:</strong>{' '}
                    <span
                      style={{
                        padding: '2px 8px',
                        borderRadius: '4px',
                        background: smp.locationStale ? '#fef3c7' : '#dcfce7',
                        color: smp.locationStale ? '#92400e' : '#166534',
                        fontWeight: 600
                      }}
                    >
                      {smp.locationStale ? 'Stale' : 'Fresh'}
                    </span>{' '}
                    (Last Updated: {smp.locationRecordedAt || smp.requestedAt || 'N/A'})
                  </div>
                </div>

                {hasException && (
                  <div
                    role="alert"
                    aria-label="Sample Exception Flag"
                    style={{
                      marginTop: '8px',
                      padding: '8px 12px',
                      background: '#fee2e2',
                      color: '#991b1b',
                      borderRadius: '4px',
                      fontWeight: 600
                    }}
                  >
                    Exception Flag: {smp.status} —{' '}
                    {smp.exception?.reason || smp.exception?.code || 'Exception recorded'}
                  </div>
                )}

                <div style={{ marginTop: '8px', fontSize: '14px', display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                  <div>
                    <strong>Current Custodian:</strong> {smp.currentHolderId || 'Pending collection'}
                  </div>
                  <div>
                    <strong>Current Location:</strong>{' '}
                    {loc ? `${loc.latitude}, ${loc.longitude}` : 'Unknown'}
                  </div>
                  <div>
                    <strong>Route Progress:</strong> {completedCount} / {legs.length} transport legs completed (
                    {smp.journey?.routeMode || 'direct'})
                  </div>
                </div>

                {Array.isArray(smp.timeline) && smp.timeline.length > 0 && (
                  <div style={{ marginTop: '10px' }}>
                    <strong>Ordered Status Timeline:</strong>
                    <ol aria-label="Ordered Status History" style={{ margin: '4px 0 0', paddingLeft: '20px', fontSize: '13px' }}>
                      {smp.timeline.map((entry: any, idx: number) => (
                        <li key={entry.eventId || idx}>
                          <strong>{entry.action}</strong> — {entry.occurredAt} (Actor: {entry.actorId}, Role: {entry.role})
                        </li>
                      ))}
                    </ol>
                  </div>
                )}
              </article>
            );
          })}
        </section>
      )}

      {/* Operations Monitor Dashboard for Dispatcher & Administrator */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && operations && (
        <section
          aria-label="Monitor Dashboard"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Operations Monitor Dashboard</h2>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))', gap: '12px' }}>
            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Samples ({(operations.samples || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.samples || []).map((s: any) => (
                  <li key={s.sampleId}>
                    {s.sampleId} — {s.status} | Holder: {s.currentHolderId || 'none'} |{' '}
                    {s.locationStale ? 'Stale' : 'Fresh'}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Workers ({(operations.workers || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.workers || []).map((w: any) => (
                  <li key={w.workerId}>
                    {w.fullName || w.workerId} — {w.status} (Assignments: {w.assignmentCount})
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Collection Nodes ({(operations.locations || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.locations || []).map((l: any) => (
                  <li key={l.locationId}>
                    {l.name} ({l.active ? 'Active' : 'Inactive'}) — Cap:{' '}
                    {l.capacity?.availableUnits}/{l.capacity?.capacityUnits}
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>
                Laboratories ({(operations.locations || []).filter((l: any) => l.functions?.laboratory).length})
              </h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.locations || [])
                  .filter((l: any) => l.functions?.laboratory)
                  .map((l: any) => (
                    <li key={l.locationId}>
                      {l.name} — Accepted Types: {(l.acceptedSampleTypeIds || []).length}
                    </li>
                  ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Routes ({(operations.routes || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.routes || []).map((rt: any) => (
                  <li key={rt.journeyId}>
                    {rt.journeyId} — {rt.routeMode} ({rt.status})
                  </li>
                ))}
              </ul>
            </div>

            <div style={{ border: '1px solid #e2e8f0', borderRadius: '6px', padding: '12px' }}>
              <h3 style={{ marginTop: 0 }}>Exceptions ({(operations.exceptions || []).length})</h3>
              <ul style={{ paddingLeft: '18px', fontSize: '13px' }}>
                {(operations.exceptions || []).map((ex: any, i: number) => (
                  <li key={ex.sampleId || i}>
                    {ex.sampleId} — {ex.reason || ex.status}
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </section>
      )}

      {/* Searchable Audit Trail for Dispatcher & Administrator */}
      {(activeRole === 'dispatcher' || activeRole === 'administrator') && (
        <section
          aria-label="Audit Trail"
          style={{
            border: '1px solid #cbd5e1',
            borderRadius: '8px',
            padding: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Audit Trail &amp; Compliance Search</h2>
          <form
            onSubmit={handleSearchAudit}
            style={{ display: 'flex', gap: '12px', marginBottom: '12px', flexWrap: 'wrap', alignItems: 'flex-end' }}
          >
            <div>
              <label htmlFor="audit-search-input" style={{ display: 'block', fontSize: '13px' }}>
                Search Audit Logs
              </label>
              <input
                id="audit-search-input"
                aria-label="Search Audit Logs"
                type="text"
                placeholder="Search audit trail..."
                value={auditQuery}
                onChange={(e) => setAuditQuery(e.target.value)}
                style={{ padding: '6px', width: '240px' }}
              />
            </div>
            <div>
              <label htmlFor="audit-action-input" style={{ display: 'block', fontSize: '13px' }}>
                Filter by Action
              </label>
              <input
                id="audit-action-input"
                aria-label="Filter by Action"
                type="text"
                placeholder="e.g. authenticate_user"
                value={auditActionFilter}
                onChange={(e) => setAuditActionFilter(e.target.value)}
                style={{ padding: '6px', width: '180px' }}
              />
            </div>
            <div>
              <label htmlFor="audit-entity-input" style={{ display: 'block', fontSize: '13px' }}>
                Filter by Entity ID
              </label>
              <input
                id="audit-entity-input"
                aria-label="Filter by Entity ID"
                type="text"
                placeholder="Entity ID"
                value={auditEntityFilter}
                onChange={(e) => setAuditEntityFilter(e.target.value)}
                style={{ padding: '6px', width: '220px' }}
              />
            </div>
            <button
              type="submit"
              style={{
                padding: '7px 14px',
                background: '#0284c7',
                color: '#ffffff',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              Search Audit
            </button>
          </form>

          <div style={{ maxHeight: '320px', overflowY: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '13px' }}>
              <thead>
                <tr style={{ background: '#f1f5f9', textAlign: 'left' }}>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Time</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Action</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Actor</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Role</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Entity</th>
                  <th style={{ padding: '8px', borderBottom: '1px solid #cbd5e1' }}>Outcome</th>
                </tr>
              </thead>
              <tbody>
                {auditEntries.map((entry: any) => (
                  <tr key={entry.eventId}>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>{entry.occurredAt}</td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>
                      <strong>{entry.action}</strong>
                    </td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>{entry.actorId}</td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>{entry.role}</td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>
                      {entry.entityType}: {entry.entityId}
                    </td>
                    <td style={{ padding: '6px 8px', borderBottom: '1px solid #e2e8f0' }}>
                      {entry.success ? 'Success' : 'Denied'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}
    </div>
  );
};

