import React, { useEffect, useState, useCallback } from 'react';
import { MapView } from './MapView';

function makeIdempKey(prefix: string): string {
  return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
}

export const App: React.FC = () => {
  const [token, setToken] = useState<string>(() => localStorage.getItem('sessionToken') || '');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [authError, setAuthError] = useState('');

  const [user, setUser] = useState<any>(null);
  const [activeRole, setActiveRole] = useState<string>('');
  const [roleSelectionRequired, setRoleSelectionRequired] = useState<boolean>(false);
  const [sampleTypes, setSampleTypes] = useState<any[]>([]);
  const [locations, setLocations] = useState<any[]>([]);
  const [assignedLocation, setAssignedLocation] = useState<any>(null);

  const [roleWork, setRoleWork] = useState<{ pending: any[]; inProgress: any[]; completed: any[] }>({
    pending: [],
    inProgress: [],
    completed: []
  });
  const [sampleDetailsMap, setSampleDetailsMap] = useState<Record<string, any>>({});
  const [operations, setOperations] = useState<any>(null);
  const [auditEntries, setAuditEntries] = useState<any[]>([]);
  const [auditQuery, setAuditQuery] = useState('');
  const [auditActionFilter, setAuditActionFilter] = useState('');
  const [auditEntityFilter, setAuditEntityFilter] = useState('');

  // Request & Serviceability form state
  const [originType, setOriginType] = useState('home');
  const [originLat, setOriginLat] = useState('12.9716');
  const [originLng, setOriginLng] = useState('77.5946');
  const [selectedSampleTypeId, setSelectedSampleTypeId] = useState('');
  const [containerType, setContainerType] = useState('amber-vial');
  const [tempMin, setTempMin] = useState('2');
  const [tempMax, setTempMax] = useState('8');
  const [earliestCol, setEarliestCol] = useState('2026-10-16T09:00:00Z');
  const [latestCol, setLatestCol] = useState('2026-10-16T11:00:00Z');
  const [deliveryDeadline, setDeliveryDeadline] = useState('2026-10-16T16:00:00Z');
  const [serviceabilityResult, setServiceabilityResult] = useState<any>(null);
  const [requestFormError, setRequestFormError] = useState('');
  const [requestSuccessMsg, setRequestSuccessMsg] = useState('');

  // Worker location form state
  const [locAssignmentId, setLocAssignmentId] = useState('');
  const [workerLat, setWorkerLat] = useState('12.9750');
  const [workerLng, setWorkerLng] = useState('77.6010');
  const [workerSeq, setWorkerSeq] = useState('1');
  const [workerLocMsg, setWorkerLocMsg] = useState('');
  const [workerLocError, setWorkerLocError] = useState('');

  // Capacity configuration state
  const [regCapInput, setRegCapInput] = useState('');
  const [cooledCapInput, setCooledCapInput] = useState('');
  const [capMsg, setCapMsg] = useState('');

  // General action feedback
  const [actionAlert, setActionAlert] = useState('');

  const apiFetch = useCallback(
    async (path: string, options: RequestInit = {}, overrideToken?: string) => {
      const tok = overrideToken !== undefined ? overrideToken : token;
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        ...((options.headers as Record<string, string>) || {})
      };
      if (tok) {
        headers['Authorization'] = `Bearer ${tok}`;
      }
      const res = await fetch(path, { ...options, headers });
      let json: any = null;
      try {
        json = await res.json();
      } catch {
        json = null;
      }
      return { status: res.status, ok: res.ok, body: json };
    },
    [token]
  );

  const loadSampleDetails = useCallback(
    async (sampleIds: string[], tok?: string) => {
      const uniqueIds = Array.from(new Set(sampleIds.filter(Boolean)));
      if (uniqueIds.length === 0) return;

      const updated: Record<string, any> = {};
      for (const sid of uniqueIds) {
        const [stRes, lcRes] = await Promise.all([
          apiFetch(`/api/read-sample-state/${sid}`, { method: 'GET' }, tok),
          apiFetch('/api/read-sample-lifecycle', { method: 'POST', body: JSON.stringify({ sampleId: sid }) }, tok)
        ]);
        const stData = stRes.ok ? stRes.body?.data : null;
        const lcData = lcRes.ok ? lcRes.body?.data : null;
        const jId = stData?.activeJourneyId || lcData?.activeJourneyId;
        let jpData: any = null;
        if (jId) {
          const jpRes = await apiFetch('/api/read-journey-plan', { method: 'POST', body: JSON.stringify({ journeyId: jId }) }, tok);
          if (jpRes.ok) {
            jpData = jpRes.body?.data;
          }
        }
        if (stData || lcData) {
          updated[sid] = {
            ...(stData || {}),
            ...(lcData || {}),
            status: lcData?.status || stData?.state?.status || stData?.status,
            timeline: lcData?.timeline || stData?.timeline || [],
            journey: jpData
          };
        }
      }
      setSampleDetailsMap((prev) => ({ ...prev, ...updated }));
    },
    [apiFetch]
  );

  const refreshAll = useCallback(
    async (tok?: string) => {
      const activeTok = tok !== undefined ? tok : token;
      if (!activeTok) return;

      const bootRes = await apiFetch('/api/ui/bootstrap', { method: 'GET' }, activeTok);
      if (!bootRes.ok) {
        if (bootRes.status === 401) {
          localStorage.removeItem('sessionToken');
          setToken('');
          setUser(null);
        }
        return;
      }
      const bData = bootRes.body?.data || {};
      const u = bData.user || {};
      setUser(u);
      setActiveRole(u.activeRole || '');
      setRoleSelectionRequired(Boolean(u.roleSelectionRequired));
      const sts = bData.sampleTypes || [];
      setSampleTypes(sts);
      if (sts.length > 0 && !selectedSampleTypeId) {
        setSelectedSampleTypeId(sts[0].sampleTypeId);
        setContainerType(sts[0].containerType || 'amber-vial');
        setTempMin(String(sts[0].temperatureMinC ?? 2));
        setTempMax(String(sts[0].temperatureMaxC ?? 8));
      }
      setLocations(bData.locations || []);
      if (bData.assignedLocation) {
        setAssignedLocation(bData.assignedLocation);
        if (bData.assignedLocation.capacity) {
          setRegCapInput(String(bData.assignedLocation.capacity.capacityUnits ?? 10));
          setCooledCapInput(String(bData.assignedLocation.capacity.cooledCapacityUnits ?? 10));
        }
      } else {
        setAssignedLocation(null);
      }

      if (!u.roleSelectionRequired && u.activeRole) {
        const workRes = await apiFetch(
          '/api/list-role-work',
          { method: 'POST', body: JSON.stringify({ role: u.activeRole }) },
          activeTok
        );
        const sidsToLoad: string[] = [];
        if (workRes.ok && workRes.body?.data) {
          const rw = workRes.body.data;
          setRoleWork({
            pending: rw.pending || [],
            inProgress: rw.inProgress || [],
            completed: rw.completed || []
          });
          const allItems = [...(rw.pending || []), ...(rw.inProgress || []), ...(rw.completed || [])];
          allItems.forEach((it: any) => {
            if (it.sampleId) sidsToLoad.push(it.sampleId);
            if (Array.isArray(it.sampleIds)) sidsToLoad.push(...it.sampleIds);
          });
          const firstAssign = [...(rw.inProgress || []), ...(rw.pending || [])].find((it: any) => it.assignmentId);
          if (firstAssign && !locAssignmentId) {
            setLocAssignmentId(firstAssign.assignmentId);
          }
        }
        if (Array.isArray(bData.requesterSamples)) {
          bData.requesterSamples.forEach((s: any) => {
            if (s.sampleId) sidsToLoad.push(s.sampleId);
          });
        }
        if (u.activeRole === 'dispatcher' || u.activeRole === 'administrator') {
          const [opsRes, audRes] = await Promise.all([
            apiFetch('/api/read-operations-state', { method: 'POST', body: JSON.stringify({}) }, activeTok),
            apiFetch('/api/search-audit-trail', { method: 'POST', body: JSON.stringify({ limit: 100 }) }, activeTok)
          ]);
          if (opsRes.ok && opsRes.body?.data) {
            setOperations(opsRes.body.data);
            (opsRes.body.data.samples || []).forEach((s: any) => {
              if (s.sampleId) sidsToLoad.push(s.sampleId);
            });
          }
          if (audRes.ok && audRes.body?.data) {
            setAuditEntries(audRes.body.data.entries || []);
          }
        }
        if (sidsToLoad.length > 0) {
          await loadSampleDetails(sidsToLoad, activeTok);
        }
      }
    },
    [apiFetch, loadSampleDetails, locAssignmentId, selectedSampleTypeId, token]
  );

  useEffect(() => {
    if (token) {
      refreshAll(token);
    }
  }, [token, refreshAll]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError('');
    if (!username.trim() || !password) {
      setAuthError('Username and password are required');
      return;
    }
    const res = await apiFetch(
      '/api/authenticate-user',
      {
        method: 'POST',
        body: JSON.stringify({ username: username.trim(), password })
      },
      ''
    );
    if (!res.ok) {
      const errMsg = res.body?.error || 'Invalid username or password';
      const errCode = res.body?.code || 'invalid_credentials';
      setAuthError(`${errMsg} (${errCode})`);
      return;
    }
    const data = res.body?.data;
    const tok = data.sessionToken;
    localStorage.setItem('sessionToken', tok);
    setToken(tok);
    await refreshAll(tok);
  };

  const handleSignOut = () => {
    localStorage.removeItem('sessionToken');
    setToken('');
    setUser(null);
    setActiveRole('');
    setRoleWork({ pending: [], inProgress: [], completed: [] });
    setOperations(null);
    setAuditEntries([]);
    setAuthError('');
  };

  const handleSelectRole = async (newRole: string) => {
    if (!newRole) return;
    setActionAlert('');
    const res = await apiFetch('/api/select-active-role', {
      method: 'POST',
      body: JSON.stringify({ role: newRole })
    });
    if (!res.ok) {
      setActionAlert(res.body?.error || 'Failed to switch role');
      return;
    }
    setActiveRole(newRole);
    setRoleSelectionRequired(false);
    await refreshAll();
  };

  const handleSampleTypeChange = (stId: string) => {
    setSelectedSampleTypeId(stId);
    const st = sampleTypes.find((s) => s.sampleTypeId === stId);
    if (st) {
      setContainerType(st.containerType || 'amber-vial');
      setTempMin(String(st.temperatureMinC ?? 2));
      setTempMax(String(st.temperatureMaxC ?? 8));
    }
  };

  const handleCheckServiceability = async () => {
    setRequestFormError('');
    setRequestSuccessMsg('');
    setServiceabilityResult(null);

    const lat = Number(originLat);
    const lng = Number(originLng);
    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      setRequestFormError('Invalid origin coordinates (invalid_origin)');
      return;
    }
    if (!selectedSampleTypeId) {
      setRequestFormError('Please select a sample type (invalid_sample_type)');
      return;
    }

    const res = await apiFetch('/api/check-serviceability', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        sampleTypeId: selectedSampleTypeId,
        requestedAt: earliestCol,
        earliestCollectionAt: earliestCol,
        latestCollectionAt: latestCol,
        deliveryDeadline
      })
    });
    if (!res.ok) {
      setRequestFormError(`${res.body?.error || 'Validation error'} (${res.body?.code || 'invalid_request'})`);
      return;
    }
    setServiceabilityResult(res.body?.data);
  };

  const handleCreateRequest = async (e: React.FormEvent) => {
    e.preventDefault();
    setRequestFormError('');
    setRequestSuccessMsg('');

    const lat = Number(originLat);
    const lng = Number(originLng);
    const tMin = Number(tempMin);
    const tMax = Number(tempMax);

    if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
      setRequestFormError('Validation error: Origin coordinates out of bounds (invalid_origin)');
      return;
    }
    if (!containerType.trim() || Number.isNaN(tMin) || Number.isNaN(tMax) || tMin >= tMax) {
      setRequestFormError('Validation error: Invalid container or temperature range (handling_mismatch)');
      return;
    }

    const res = await apiFetch('/api/create-collection-request', {
      method: 'POST',
      body: JSON.stringify({
        origin: { latitude: lat, longitude: lng },
        originType,
        requestedAt: earliestCol,
        earliestCollectionAt: earliestCol,
        latestCollectionAt: latestCol,
        deliveryDeadline,
        sampleTypeId: selectedSampleTypeId,
        containerType: containerType.trim(),
        temperatureMinC: tMin,
        temperatureMaxC: tMax,
        idempotencyKey: makeIdempKey('req')
      })
    });
    if (!res.ok) {
      setRequestFormError(`${res.body?.error || 'Request validation failed'} (${res.body?.code || 'validation_error'})`);
      return;
    }
    const created = res.body?.data;
    setRequestSuccessMsg(`Created sample ${created.sampleId} (${created.serviceability})`);
    await refreshAll();
  };

  const handleAcceptAssignment = async (assignmentId: string) => {
    setActionAlert('');
    const res = await apiFetch('/api/accept-assignment', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        idempotencyKey: makeIdempKey('accept')
      })
    });
    if (!res.ok) {
      setActionAlert(`${res.body?.error || 'Failed to accept assignment'} (${res.body?.code || 'error'})`);
      return;
    }
    setLocAssignmentId(assignmentId);
    await refreshAll();
  };

  const handleDeclineAssignment = async (assignmentId: string) => {
    setActionAlert('');
    const res = await apiFetch('/api/decline-assignment', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId,
        reason: 'Worker declined via UI',
        declinedAt: new Date().toISOString(),
        idempotencyKey: makeIdempKey('decline')
      })
    });
    if (!res.ok) {
      setActionAlert(`${res.body?.error || 'Failed to decline assignment'} (${res.body?.code || 'error'})`);
      return;
    }
    await refreshAll();
  };

  const handleRecordWorkerLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setWorkerLocError('');
    setWorkerLocMsg('');
    const targetAssignId =
      locAssignmentId ||
      [...roleWork.inProgress, ...roleWork.pending].find((a: any) => a.assignmentId)?.assignmentId ||
      '';
    if (!targetAssignId) {
      setWorkerLocError('No active assignment selected');
      return;
    }
    const res = await apiFetch('/api/record-worker-location', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId: targetAssignId,
        coordinate: {
          latitude: Number(workerLat),
          longitude: Number(workerLng)
        },
        sequence: Number(workerSeq),
        recordedAt: new Date().toISOString()
      })
    });
    if (!res.ok) {
      setWorkerLocError(`${res.body?.error || 'Failed to record location'} (${res.body?.code || 'error'})`);
      return;
    }
    const d = res.body?.data;
    setWorkerLocMsg(
      `Recorded Location: ${d.coordinate.latitude}, ${d.coordinate.longitude} (seq ${d.sequence}) at ${d.recordedAt}`
    );
    setWorkerSeq(String(Number(workerSeq) + 1));
    await refreshAll();
  };

  const handleUpdateCapacity = async (e: React.FormEvent) => {
    e.preventDefault();
    setCapMsg('');
    if (!assignedLocation?.locationId) return;
    const res = await apiFetch('/api/configure-capacity', {
      method: 'POST',
      body: JSON.stringify({
        resourceId: assignedLocation.locationId,
        capacityUnits: Number(regCapInput),
        cooledCapacityUnits: Number(cooledCapInput)
      })
    });
    if (!res.ok) {
      setCapMsg(`Error: ${res.body?.error} (${res.body?.code})`);
      return;
    }
    setCapMsg('Capacity updated');
    await refreshAll();
  };

  const handleSearchAudit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const payload: Record<string, any> = { limit: 100 };
    if (auditQuery.trim()) payload.query = auditQuery.trim();
    if (auditActionFilter.trim()) payload.action = auditActionFilter.trim();
    if (auditEntityFilter.trim()) payload.entityId = auditEntityFilter.trim();

    const res = await apiFetch('/api/search-audit-trail', {
      method: 'POST',
      body: JSON.stringify(payload)
