          </div>
          <div style={{ marginBottom: '16px' }}>
            <label htmlFor="password-input" style={{ display: 'block', marginBottom: '4px', fontWeight: 600 }}>
              Password
            </label>
            <input
              id="password-input"
              name="password"
              aria-label="Password"
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            />
          </div>
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '10px',
              background: '#0284c7',
              color: '#ffffff',
              border: 'none',
              borderRadius: '6px',
              fontWeight: 600,
              cursor: 'pointer'
            }}
          >
            Sign In
          </button>
        </form>
      </main>
    );
  }

  const allSamplesList = Object.values(sampleDetailsMap);
