            borderRadius: '8px',
            padding: '16px',
            marginBottom: '16px',
            background: '#ffffff'
          }}
        >
          <h2 style={{ marginTop: 0 }}>Create Collection Request &amp; Check Serviceability</h2>
          {requestFormError && (
            <div
              role="alert"
              aria-label="Request Validation Error"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: '#fee2e2',
                color: '#991b1b',
                borderRadius: '6px'
              }}
            >
              {requestFormError}
            </div>
          )}
          {requestSuccessMsg && (
            <div
              role="status"
              style={{
                padding: '10px',
                marginBottom: '12px',
                background: '#dcfce7',
